# Do not edit this file: edit those and build again.
#Requires -Version 5.1
<#
.SYNOPSIS
    Fujikyun RPA macro builder, PowerShell edition (Windows Forms).

.DESCRIPTION
    Start it with fujikyun.bat (Windows PowerShell 5.1, single-threaded apartment). The macros file
    and the other working files (fujikyun_macros.json, samples, rpa_images, macro_export ...) are
    kept in this folder, next to fujikyun_ja.json, fujikyun_commands.json and fujikyun_templates.json.

    fujikyun.ps1 is built from ps\build\Main.ps1 (this text) with the functions of ps\src and
    ps\gui put in place of the SOURCES mark, so the app is one script file:
        powershell -NoProfile -File ps\build\Build-FujiBundle.ps1
#>
[CmdletBinding()]
param()

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$here = $PSScriptRoot
$script:StartWatch = [System.Diagnostics.Stopwatch]::StartNew()
$script:StartMarks = New-Object -TypeName 'System.Collections.Generic.List[double]'
$textReady = $false
try {
    # ===== src/Commands.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Commands
#  fujikyun_commands.json holds each command's display data (title, icon, help, input fields,
#  palette, key presets, condition and string operations). This file holds the logic: reading and
#  writing a step's value, checking the settings, and the automatic label.
#
#  Step value formats (fujikyun_commands.json "format"):
#    text  one setting, stored as the plain value          KEY "{TAB}", SWITCH "Notepad"
#    json  several settings, stored as a compact JSON text  WAIT_FOR {"title":"..","key":"..","timeout":"30"}
#    none  block markers without settings                   LOOP_END, ELSE, ...
# ---------------------------------------------------------------------------------------------

$script:FujiCommands = $null
$script:FujiBlockEnds = @{}

function Import-FujiCommand {
    param([Parameter(Mandatory)][string]$Path)
    $script:FujiCommands = ConvertFrom-FujiJson -Json (Read-FujiUtf8File -Path $Path)
    $script:FujiBlockEnds = @{}
    foreach ($start in $script:FujiCommands['blocks']['pairs'].Keys) {
        $script:FujiBlockEnds[$script:FujiCommands['blocks']['pairs'][$start]] = $start
    }
}

function Get-FujiCommandDef {
    param([Parameter(Mandatory)][string]$Cmd)
    if ($script:FujiCommands['commands'].Contains($Cmd)) { return $script:FujiCommands['commands'][$Cmd] }
    return $null
}

function Get-FujiCommandName {
    return @($script:FujiCommands['commands'].Keys)
}

# ----------------------------------------------------------------- blocks
function Test-FujiBlockStart { param([string]$Cmd) return $script:FujiCommands['blocks']['pairs'].Contains($Cmd) }
function Test-FujiBlockEnd { param([string]$Cmd) return $script:FujiBlockEnds.ContainsKey($Cmd) }
function Test-FujiBlockMiddle { param([string]$Cmd) return $script:FujiCommands['blocks']['middles'].Contains($Cmd) }
function Get-FujiBlockEndOf { param([string]$Cmd) return $script:FujiCommands['blocks']['pairs'][$Cmd] }
function Get-FujiBlockStartOf { param([string]$Cmd) return $script:FujiBlockEnds[$Cmd] }
function Get-FujiBlockOwnerOf { param([string]$Cmd) return $script:FujiCommands['blocks']['middles'][$Cmd] }

# ----------------------------------------------------------------- small helpers
# The HTA's truncateText: line breaks shown as one mark, long text cut with an ellipsis
function Format-FujiShort {
    param([AllowNull()][AllowEmptyString()][string]$Text, [int]$Max)
    $s = [regex]::Replace([string]$Text, '\r\n|\r|\n', (Get-FujiText 'label.newline'))
    if ($s.Length -gt $Max) { return $s.Substring(0, $Max) + (Get-FujiText 'label.ellipsis') }
    return $s
}

# 'x {name} y' with @{ name = 'v' }; unknown names stay as written
function Format-FujiTemplate {
    param([Parameter(Mandatory)][string]$Template, [hashtable]$Values = @{})
    $sb = New-Object -TypeName System.Text.StringBuilder
    $last = 0
    foreach ($m in [regex]::Matches($Template, '\{(\w+)\}')) {
        [void]$sb.Append($Template, $last, $m.Index - $last)
        $k = $m.Groups[1].Value
        if ($Values.ContainsKey($k)) { [void]$sb.Append([string]$Values[$k]) } else { [void]$sb.Append($m.Value) }
        $last = $m.Index + $m.Length
    }
    [void]$sb.Append($Template, $last, $Template.Length - $last)
    return $sb.ToString()
}

function Get-FujiLabelText {
    param([Parameter(Mandatory)][string]$Key, [hashtable]$Values = @{})
    return Format-FujiTemplate -Template (Get-FujiText ('label.' + $Key)) -Values $Values
}

function Get-FujiKeyName {
    param([AllowEmptyString()][string]$Key)
    foreach ($p in $script:FujiCommands['keyPresets']) {
        if ([string]::Equals([string]$p[0], $Key, [System.StringComparison]::OrdinalIgnoreCase)) { return [string]$p[1] }
    }
    return $Key
}

function Get-FujiStrOpName {
    param([string]$Op)
    foreach ($o in $script:FujiCommands['strOps']) {
        # The option text is "name<full-width colon>explanation"
        if ($o[0] -eq $Op) { return ([string]$o[1]).Split([char]0xFF1A)[0] }
    }
    return $Op
}

function Test-FujiConditionNeedsLeft { param([string]$Op) return ($Op -ne 'EMPTY' -and $Op -ne 'NOT_EMPTY') }

function Get-FujiConditionText {
    param([System.Collections.IDictionary]$Condition)
    $left = Get-FujiLabelText 'condLeft' @{ left = (Format-FujiShort $Condition['left'] 20) }
    $unary = (Get-FujiText 'label.condUnary').PSObject.Properties[[string]$Condition['op']]
    if ($null -ne $unary) { return $left + [string]$unary.Value }
    $binary = (Get-FujiText 'label.condBinary').PSObject.Properties[[string]$Condition['op']]
    $tail = (Get-FujiText 'label.condBinary').EQ
    if ($null -ne $binary) { $tail = [string]$binary.Value }
    return $left + (Get-FujiLabelText 'condRight' @{ right = (Format-FujiShort $Condition['right'] 20) }) + $tail
}

function Get-FujiOcrAreaText {
    param([System.Collections.IDictionary]$Settings)
    switch ([string]$Settings['area']) {
        'FULL' { return (Get-FujiText 'label.areaFull') }
        'RECT' { return (Get-FujiLabelText 'areaRect' @{ x = $Settings['x']; y = $Settings['y']; w = $Settings['w']; h = $Settings['h'] }) }
        default { return (Get-FujiText 'label.areaWindow') }
    }
}

function Get-FujiFileName { param([AllowEmptyString()][string]$Path) return ($Path -replace '^.*[\\/]', '') }

# ----------------------------------------------------------------- value <-> settings
function Get-FujiValueFieldId {
    param([System.Collections.IDictionary]$Def)
    $ids = @()
    foreach ($f in $Def['fields']) {
        if (-not $f.Contains('prop') -and $f['type'] -ne 'capture' -and $f['type'] -ne 'rectcapture') { $ids += [string]$f['id'] }
    }
    return , $ids
}

# Step value -> ordered settings (every value a string; missing JSON keys get their defaults)
function ConvertFrom-FujiStepValue {
    param([Parameter(Mandatory)][string]$Cmd, [AllowNull()][AllowEmptyString()][string]$Value)
    $def = Get-FujiCommandDef -Cmd $Cmd
    $settings = [ordered]@{}
    if ($null -eq $def -or $def['format'] -eq 'none') { return $settings }
    if ($def['format'] -eq 'text') {
        $ids = Get-FujiValueFieldId -Def $def
        $settings[$ids[0]] = [string]$Value
        return $settings
    }
    $parsed = $null
    try { $parsed = ConvertFrom-FujiJson -Json ([string]$Value) } catch { $parsed = $null }
    if ($parsed -isnot [System.Collections.IDictionary]) { $parsed = @{} }
    foreach ($k in $def['parseDefaults'].Keys) {
        if ($parsed.Contains($k) -and $null -ne $parsed[$k]) { $settings[$k] = [string]$parsed[$k] } else { $settings[$k] = [string]$def['parseDefaults'][$k] }
    }
    switch ($Cmd) {
        'WINDOW_CHECK' { $settings['mode'] = Get-FujiCheckMode $settings['mode'] }
        'CLICK_POS' { if ($settings['kind'] -ne 'DOUBLE' -and $settings['kind'] -ne 'RIGHT') { $settings['kind'] = 'LEFT' } }
        'SCREENSHOT' { if ($settings['scope'] -ne 'FULL') { $settings['scope'] = 'WINDOW' } }
    }
    return $settings
}

function Get-FujiCheckMode {
    param([AllowEmptyString()][string]$Mode)
    $m = ([string]$Mode).ToUpperInvariant()
    if ($m -eq 'SKIP' -or $m -eq 'CONTINUE') { return $m }
    return 'STOP'
}

function Get-FujiThreshold {
    param([AllowEmptyString()][string]$Text)
    $n = 0.0
    if (-not [double]::TryParse(([string]$Text).Trim(), [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$n)) { return 0.9 }
    return [Math]::Min(1.0, [Math]::Max(0.5, $n))
}

# Settings -> step value. MacroName: the called macro's current name (CALL_MACRO keeps both)
function ConvertTo-FujiStepValue {
    param([Parameter(Mandatory)][string]$Cmd, [Parameter(Mandatory)][System.Collections.IDictionary]$Settings, [string]$MacroName = '')
    $def = Get-FujiCommandDef -Cmd $Cmd
    if ($null -eq $def -or $def['format'] -eq 'none') { return '' }
    $v = [ordered]@{}
    foreach ($k in $Settings.Keys) { $v[$k] = [string]$Settings[$k] }
    switch ($Cmd) {
        'CSV' { return [string](Get-FujiInt -Text $v['col'] -Default 1) }
        'WAIT' { return [string](Get-FujiInt -Text $v['ms'] -Default 0) }
        'WAIT_FOR' { $v['timeout'] = [string](Get-FujiInt -Text $v['timeout'] -Default 30) }
        'WINDOW_CHECK' { $v['mode'] = Get-FujiCheckMode $v['mode'] }
        'CLICK_POS' {
            $v['x'] = [string](Get-FujiInt -Text $v['x'] -Default 0)
            $v['y'] = [string](Get-FujiInt -Text $v['y'] -Default 0)
            if ($v['kind'] -ne 'DOUBLE' -and $v['kind'] -ne 'RIGHT') { $v['kind'] = 'LEFT' }
        }
        'CLICK_IMG' { $v['threshold'] = (Get-FujiThreshold $v['threshold']).ToString('R', [System.Globalization.CultureInfo]::InvariantCulture) }
        'SCREENSHOT' { if ($v['scope'] -ne 'FULL') { $v['scope'] = 'WINDOW' } }
        'CALL_MACRO' { $v['name'] = $MacroName }
    }
    if ($def['format'] -eq 'text') {
        $ids = Get-FujiValueFieldId -Def $def
        return [string]$v[$ids[0]]
    }
    $out = [ordered]@{}
    foreach ($k in $def['parseDefaults'].Keys) {
        if ($v.Contains($k)) { $out[$k] = $v[$k] } else { $out[$k] = [string]$def['parseDefaults'][$k] }
    }
    return (ConvertTo-FujiJson -InputObject $out -Indent 0)
}

# ----------------------------------------------------------------- checking the settings
function Get-FujiVarNameError {
    param([AllowEmptyString()][string]$Name)
    $n = ([string]$Name).Trim()
    if ($n -eq '') { return (Get-FujiText 'validate.varEmpty') }
    if ($n -match '[\s{}:,$]') { return (Get-FujiText 'validate.varBad') }
    return ''
}

function Get-FujiRectError {
    param([System.Collections.IDictionary]$S)
    if ($S['area'] -ne 'RECT') { return '' }
    foreach ($k in @('x', 'y', 'w', 'h')) {
        if ((ConvertTo-FujiHalfWidthDigit -Text ([string]$S[$k]).Trim()) -notmatch '^-?[0-9]+$') { return (Get-FujiText 'validate.rect') }
    }
    if ((Get-FujiInt $S['w'] 0) -lt 4 -or (Get-FujiInt $S['h'] 0) -lt 4) { return (Get-FujiText 'validate.rectSize') }
    return ''
}

function Test-FujiPositiveInt {
    param([AllowEmptyString()][string]$Text, [int]$Min = 1)
    $t = (ConvertTo-FujiHalfWidthDigit -Text ([string]$Text).Trim())
    return ($t -match '^[0-9]+$' -and [long]$t -ge $Min)
}

# Settings as entered (already trimmed except raw fields) -> error message, or '' when fine
function Test-FujiStepSetting {
    param([Parameter(Mandatory)][string]$Cmd, [Parameter(Mandatory)][System.Collections.IDictionary]$Settings)
    $s = $Settings
    switch ($Cmd) {
        'KEY' { if ($s['key'] -eq '') { return (Get-FujiText 'validate.key') } }
        'TEXT' { if ($s['text'] -eq '') { return (Get-FujiText 'validate.text') } }
        'CSV' { if (-not (Test-FujiPositiveInt $s['col'] 1)) { return (Get-FujiText 'validate.csvCol') } }
        'COPY' { return (Get-FujiVarNameError $s['name']) }
        'WAIT' { if (-not (Test-FujiPositiveInt $s['ms'] 0)) { return (Get-FujiText 'validate.waitMs') } }
        'WAIT_FOR' {
            if ($s['title'] -eq '') { return (Get-FujiText 'validate.waitTitle') }
            if (-not (Test-FujiPositiveInt $s['timeout'] 1)) { return (Get-FujiText 'validate.timeout') }
        }
        'WINDOW_CHECK' { if ($s['title'] -eq '') { return (Get-FujiText 'validate.checkTitle') } }
        'CONFIRM' { if (([string]$s['message']).Trim() -eq '') { return (Get-FujiText 'validate.message') } }
        'CLICK_NAME' { if ($s['name'] -eq '') { return (Get-FujiText 'validate.clickName') } }
        'CLICK_POS' { if ($s['x'] -notmatch '^-?[0-9]+$' -or $s['y'] -notmatch '^-?[0-9]+$') { return (Get-FujiText 'validate.xy') } }
        'CLICK_IMG' {
            if ($s['path'] -eq '') { return (Get-FujiText 'validate.imgPath') }
            $n = 0.0
            $ok = $s['threshold'] -match '^[0-9]*\.?[0-9]+$' -and [double]::TryParse($s['threshold'], [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$n)
            if (-not $ok -or $n -lt 0.5 -or $n -gt 1) { return (Get-FujiText 'validate.threshold') }
        }
        'CLICK_TEXT' {
            if (([string]$s['text']).Trim() -eq '') { return (Get-FujiText 'validate.findText') }
            $nth = [string]$s['nth']
            if ($nth -eq '') { $nth = '1' }
            if (-not (Test-FujiPositiveInt $nth 1)) { return (Get-FujiText 'validate.nth') }
            return (Get-FujiRectError $s)
        }
        'READ_TEXT' {
            $e = Get-FujiRectError $s
            if ($e) { return $e }
            return (Get-FujiVarNameError $s['name'])
        }
        'SWITCH' { if ($s['title'] -eq '') { return (Get-FujiText 'validate.switchTitle') } }
        'RUN' { if ($s['path'] -eq '') { return (Get-FujiText 'validate.runPath') } }
        'SCREENSHOT' { if ($s['name'] -eq '') { return (Get-FujiText 'validate.fileName') } }
        'MAIL' { if (([string]$s['to']).Trim() -eq '') { return (Get-FujiText 'validate.mailTo') } }
        'LOOP_START' {
            if ($s['mode'] -eq 'COUNT' -and ([string]$s['count']).Trim() -eq '') { return (Get-FujiText 'validate.count') }
            if ($s['mode'] -eq 'WHILE' -and (Test-FujiConditionNeedsLeft $s['op']) -and ([string]$s['left']).Trim() -eq '') { return (Get-FujiText 'validate.left') }
            if (-not (Test-FujiPositiveInt $s['max'] 1)) { return (Get-FujiText 'validate.max') }
            return (Get-FujiVarNameError $s['counter'])
        }
        'IF_START' { if ((Test-FujiConditionNeedsLeft $s['op']) -and ([string]$s['left']).Trim() -eq '') { return (Get-FujiText 'validate.left') } }
        'TRY_START' { if ($s['name'] -eq '') { return (Get-FujiText 'validate.tryName') } }
        'CALL_MACRO' { if ($s['id'] -eq '') { return (Get-FujiText 'validate.macro') } }
        'SET_VAR' { return (Get-FujiVarNameError $s['name']) }
        'STR_OP' {
            $e = Get-FujiVarNameError $s['name']
            if ($e) { return $e }
            if (($s['op'] -eq 'REGEX_REPLACE' -or $s['op'] -eq 'REGEX_EXTRACT') -and $s['a'] -ne '' -and $s['a'] -notmatch '\{\{') {
                try { [void][regex]::new($s['a']) } catch { return (Get-FujiText 'validate.regex' $_.Exception.InnerException.Message) }
            }
        }
        'ASK' { return (Get-FujiVarNameError $s['name']) }
        'RECORD' { return (Get-FujiVarNameError $s['name']) }
        'EXCEL_READ' {
            if (([string]$s['path']).Trim() -eq '') { return (Get-FujiText 'validate.bookPath') }
            if (([string]$s['cell']).Trim() -eq '') { return (Get-FujiText 'validate.cell') }
            return (Get-FujiVarNameError $s['name'])
        }
        'EXCEL_WRITE' {
            if (([string]$s['path']).Trim() -eq '') { return (Get-FujiText 'validate.bookPath') }
            if (([string]$s['cell']).Trim() -eq '') { return (Get-FujiText 'validate.cell') }
        }
        'GROUP_START' { if ($s['name'] -eq '') { return (Get-FujiText 'validate.groupName') } }
        'COMMENT' { if ($s['memo'] -eq '') { return (Get-FujiText 'validate.memo') } }
    }
    return ''
}

# ----------------------------------------------------------------- automatic label
# MacroNameOf: scriptblock { param($Id) ... } giving a macro's current name (CALL_MACRO)
function Get-FujiStepLabel {
    param([Parameter(Mandatory)][string]$Cmd, [AllowNull()][AllowEmptyString()][string]$Value, [scriptblock]$MacroNameOf = $null)
    $def = Get-FujiCommandDef -Cmd $Cmd
    if ($null -eq $def) { return [string]$Value }
    if ($def['format'] -eq 'none') { return [string]$def['title'] }
    $val = [string]$Value
    $p = ConvertFrom-FujiStepValue -Cmd $Cmd -Value $val
    switch ($Cmd) {
        'KEY' {
            $name = Get-FujiKeyName $val
            if ($name -eq $val) { return (Get-FujiLabelText 'key' @{ key = $val }) }
            return $name
        }
        'TEXT' { return (Get-FujiLabelText 'text' @{ text = (Format-FujiShort $val 20) }) }
        'CSV' {
            $name = ''
            if ($script:FujiCsvHeaderNameOf) { $name = & $script:FujiCsvHeaderNameOf (Get-FujiInt $val 0) }
            $nameText = ''
            if ($name) { $nameText = Get-FujiLabelText 'csvName' @{ name = $name } }
            return (Get-FujiLabelText 'csv' @{ col = $val; name = $nameText })
        }
        'COPY' { return (Get-FujiLabelText 'copy' @{ name = $val }) }
        'WAIT' { return (Get-FujiLabelText 'wait' @{ ms = $val }) }
        'WAIT_FOR' {
            $key = ''
            if ($p['key']) { $key = Get-FujiLabelText 'waitForKey' @{ key = (Get-FujiKeyName $p['key']) } }
            return (Get-FujiLabelText 'waitFor' @{ title = $p['title']; timeout = $p['timeout'] }) + $key
        }
        'WINDOW_CHECK' {
            $key = ''
            if ($p['key']) { $key = Get-FujiLabelText 'checkKey' @{ key = (Get-FujiKeyName $p['key']) } }
            $action = Get-FujiText 'label.checkStop'
            if ($p['mode'] -eq 'SKIP') { $action = Get-FujiText 'label.checkSkip' } elseif ($p['mode'] -eq 'CONTINUE') { $action = Get-FujiText 'label.checkContinue' }
            return (Get-FujiLabelText 'check' @{ title = $p['title']; key = $key; action = $action })
        }
        'CONFIRM' { return (Get-FujiLabelText 'confirm' @{ message = (Format-FujiShort $val 30) }) }
        'CLICK_NAME' { return (Get-FujiLabelText 'clickName' @{ name = $val }) }
        'CLICK_POS' {
            $kind = Get-FujiText 'label.posLeft'
            if ($p['kind'] -eq 'DOUBLE') { $kind = Get-FujiText 'label.posDouble' } elseif ($p['kind'] -eq 'RIGHT') { $kind = Get-FujiText 'label.posRight' }
            return (Get-FujiLabelText 'clickPos' @{ x = $p['x']; y = $p['y']; kind = $kind })
        }
        'CLICK_IMG' {
            $file = Get-FujiFileName $p['path']
            if (-not $file) { $file = Get-FujiText 'label.noFile' }
            $percent = [int][Math]::Round((Get-FujiThreshold $p['threshold']) * 100, [System.MidpointRounding]::AwayFromZero)
            return (Get-FujiLabelText 'clickImg' @{ file = $file; percent = $percent })
        }
        'CLICK_TEXT' { return (Get-FujiLabelText 'clickText' @{ text = (Format-FujiShort $p['text'] 20); area = (Get-FujiOcrAreaText $p) }) }
        'READ_TEXT' { return (Get-FujiLabelText 'readText' @{ area = (Get-FujiOcrAreaText $p); name = $p['name'] }) }
        'SWITCH' { return (Get-FujiLabelText 'switch' @{ title = $val }) }
        'RUN' { return (Get-FujiLabelText 'run' @{ path = (Format-FujiShort $val 30) }) }
        'SCREENSHOT' {
            $scope = Get-FujiText 'label.shotWindow'
            if ($p['scope'] -eq 'FULL') { $scope = Get-FujiText 'label.shotFull' }
            return (Get-FujiLabelText 'screenshot' @{ name = (Format-FujiShort $p['name'] 20); scope = $scope })
        }
        'MAIL' {
            $how = Get-FujiText 'label.mailDraft'
            if ($p['method'] -eq 'MAILTO') { $how = Get-FujiText 'label.mailTo' }
            elseif ($p['mode'] -eq 'SEND') { $how = Get-FujiText 'label.mailSend' }
            elseif ($p['mode'] -eq 'DISPLAY') { $how = Get-FujiText 'label.mailDisplay' }
            return (Get-FujiLabelText 'mail' @{ to = (Format-FujiShort $p['to'] 24); subject = (Format-FujiShort $p['subject'] 20); how = $how })
        }
        'LOOP_START' {
            if ($p['mode'] -eq 'WHILE') { return (Get-FujiLabelText 'loopWhile' @{ cond = (Get-FujiConditionText $p) }) }
            return (Get-FujiLabelText 'loopCount' @{ count = $p['count'] })
        }
        'IF_START' { return (Get-FujiLabelText 'if' @{ cond = (Get-FujiConditionText $p) }) }
        'TRY_START' { return (Get-FujiLabelText 'try' @{ name = $val }) }
        'CALL_MACRO' {
            $name = ''
            if ($MacroNameOf) { $name = [string](& $MacroNameOf $p['id']) }
            if (-not $name) { $name = $p['name'] }
            if (-not $name) { $name = '?' }
            return (Get-FujiLabelText 'call' @{ name = $name })
        }
        'SET_VAR' {
            $calc = ''
            if ($p['mode'] -eq 'CALC') { $calc = Get-FujiText 'label.setVarCalc' }
            return (Get-FujiLabelText 'setVar' @{ name = $p['name']; value = (Format-FujiShort $p['value'] 30); calc = $calc })
        }
        'STR_OP' { return (Get-FujiLabelText 'strOp' @{ name = $p['name']; src = (Format-FujiShort $p['src'] 20); op = (Get-FujiStrOpName $p['op']) }) }
        'ASK' { return (Get-FujiLabelText 'ask' @{ name = $p['name'] }) }
        'RECORD' { return (Get-FujiLabelText 'record' @{ name = $p['name']; value = (Format-FujiShort $p['value'] 30) }) }
        'EXCEL_READ' { return (Get-FujiLabelText 'excelRead' @{ file = (Get-FujiFileName $p['path']); cell = $p['cell']; name = $p['name'] }) }
        'EXCEL_WRITE' { return (Get-FujiLabelText 'excelWrite' @{ file = (Get-FujiFileName $p['path']); cell = $p['cell']; value = (Format-FujiShort $p['value'] 20) }) }
        'GROUP_START' { return $val }
        'COMMENT' { return (Format-FujiShort $val 40) }
    }
    return $val
}

# Set by the editor: { param($Column) ... } giving the loaded CSV's header name for a column number
$script:FujiCsvHeaderNameOf = $null

# ===== src/Csv.ps1 =====
# ---------------------------------------------------------------------------------------------
#  CSV  (same rules as the HTA's parseCsv)
#  Like Excel / RFC 4180: a quote opens a quoted field only as the field's first character
#  (12"monitor stays text). Blank lines inside the data keep their place so row numbers match the
#  file; only trailing blank lines are dropped. Scanning is per field (one regex match each), not
#  per character, so large files stay fast in PowerShell.
# ---------------------------------------------------------------------------------------------

$script:FujiCsvField = New-Object -TypeName System.Text.RegularExpressions.Regex -ArgumentList @(
    '\G(?:"(?<q>(?:[^"]|"")*)(?<close>"?)(?<tail>[^,\r\n]*)|(?<plain>[^,\r\n]*))',
    [System.Text.RegularExpressions.RegexOptions]::CultureInvariant
)

# Returns @{ Records = List[string[]]; Warnings = string[] }
function ConvertFrom-FujiCsv {
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Text)
    $records = New-Object -TypeName 'System.Collections.Generic.List[string[]]'
    $warnings = New-Object -TypeName 'System.Collections.Generic.List[string]'
    $len = $Text.Length
    $pos = 0
    if ($len -eq 0) { return @{ Records = $records; Warnings = $warnings.ToArray() } }
    $row = New-Object -TypeName 'System.Collections.Generic.List[string]'
    while ($true) {
        $m = $script:FujiCsvField.Match($Text, $pos)
        if ($m.Groups['q'].Success) {
            $field = $m.Groups['q'].Value.Replace('""', '"') + $m.Groups['tail'].Value
            if ($m.Groups['close'].Value -eq '') {
                $warnings.Add((Get-FujiText 'csv.unclosedQuote' ($records.Count + 1)))
            }
        } else {
            $field = $m.Groups['plain'].Value
        }
        $pos = $m.Index + $m.Length
        $row.Add($field)
        if ($pos -ge $len) {
            $records.Add($row.ToArray())
            break
        }
        $c = $Text[$pos]
        if ($c -eq ',') {
            $pos++
            continue
        }
        # \r\n, \r or \n ends the record
        $records.Add($row.ToArray())
        $row.Clear()
        $pos++
        if ($c -eq "`r" -and $pos -lt $len -and $Text[$pos] -eq "`n") { $pos++ }
        if ($pos -ge $len) { break }
    }
    while ($records.Count -gt 0 -and (Test-FujiBlankRow -Row $records[$records.Count - 1])) {
        $records.RemoveAt($records.Count - 1)
    }
    return @{ Records = $records; Warnings = $warnings.ToArray() }
}

function Test-FujiBlankRow {
    param([AllowEmptyCollection()][string[]]$Row)
    foreach ($v in $Row) { if ($v -ne '') { return $false } }
    return $true
}

function ConvertTo-FujiCsvField {
    param([AllowNull()][AllowEmptyString()][string]$Value)
    if ($null -eq $Value) { return '' }
    if ($Value -match '[",\r\n]') { return '"' + $Value.Replace('"', '""') + '"' }
    return $Value
}

function ConvertTo-FujiCsvText {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Rows)
    $lines = foreach ($r in $Rows) { (@($r) | ForEach-Object { ConvertTo-FujiCsvField -Value ([string]$_) }) -join ',' }
    return ((@($lines) -join "`r`n") + "`r`n")
}

# ===== src/Data.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Data model: macros file, steps and block structure
#  A macro: [ordered]@{ id; name; targetWindow; steps = List[object] }
#  A step:  [ordered]@{ cmd; val; label [; when = 'first'|'last'] [; disabled = $true] }
#  The file format is the HTA's fujikyun_macros.json (data version 27).
# ---------------------------------------------------------------------------------------------

$script:FujiDataVersion = 27

function New-FujiId {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Creates an in-memory value only')]
    param()
    # 8 hex digits like the HTA's generateId
    return [guid]::NewGuid().ToString('N').Substring(0, 8)
}

function New-FujiStep {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Creates an in-memory value only')]
    param([Parameter(Mandatory)][string]$Cmd, [AllowEmptyString()][string]$Value = '', [string]$Label = '', [scriptblock]$MacroNameOf = $null)
    $step = [ordered]@{ cmd = $Cmd; val = $Value; label = $Label }
    if (-not $step.label) { $step.label = Get-FujiStepLabel -Cmd $Cmd -Value $Value -MacroNameOf $MacroNameOf }
    return $step
}

# Parsed file content (dictionary) -> clean data. Unknown commands become comments so nothing is
# lost silently; every macro gets a unique id. Returns @{ Data; NewerVersion }.
function ConvertTo-FujiMacroData {
    param($Source)
    $data = [ordered]@{ version = $script:FujiDataVersion; macros = (New-Object -TypeName 'System.Collections.Generic.List[object]') }
    $newer = $false
    if ($Source -is [System.Collections.IDictionary]) {
        if ($Source.Contains('version') -and $Source['version'] -is [ValueType] -and [double]$Source['version'] -gt $script:FujiDataVersion) { $newer = $true }
    }
    $list = @()
    if ($Source -is [System.Collections.IDictionary] -and $Source.Contains('macros') -and $Source['macros'] -is [System.Collections.IList]) { $list = $Source['macros'] }
    $used = @{}
    $known = @{}
    foreach ($c in Get-FujiCommandName) { $known[$c] = $true }
    foreach ($m in $list) {
        if ($m -isnot [System.Collections.IDictionary]) { $m = @{} }
        $steps = New-Object -TypeName 'System.Collections.Generic.List[object]'
        $src = @()
        if ($m.Contains('steps') -and $m['steps'] -is [System.Collections.IList]) { $src = $m['steps'] }
        foreach ($s in $src) {
            if ($s -isnot [System.Collections.IDictionary] -or -not $s.Contains('cmd') -or -not $s['cmd']) { continue }
            $cmd = ([string]$s['cmd']).ToUpperInvariant()
            $val = ''
            if ($s.Contains('val') -and $null -ne $s['val']) { $val = [string]$s['val'] }
            if (-not $known.ContainsKey($cmd)) {
                $val = Get-FujiText 'data.unknownCommand' $cmd $val
                $cmd = 'COMMENT'
            }
            $label = ''
            if ($s.Contains('label') -and $null -ne $s['label']) { $label = [string]$s['label'] }
            $step = [ordered]@{ cmd = $cmd; val = $val; label = $label }
            if ($cmd -eq 'GROUP_START' -and $s.Contains('when') -and ($s['when'] -eq 'first' -or $s['when'] -eq 'last')) { $step['when'] = [string]$s['when'] }
            if ($s.Contains('disabled') -and $s['disabled'] -eq $true) { $step['disabled'] = $true }
            if (-not $step.label) { $step.label = Get-FujiStepLabel -Cmd $cmd -Value $val }
            $steps.Add($step)
        }
        $id = ''
        if ($m.Contains('id') -and $m['id']) { $id = [string]$m['id'] }
        if (-not $id) { $id = New-FujiId }
        while ($used.ContainsKey($id)) { $id = New-FujiId }
        $used[$id] = $true
        $name = Get-FujiText 'data.unnamedMacro'
        if ($m.Contains('name') -and $m['name']) { $name = [string]$m['name'] }
        $target = ''
        if ($m.Contains('targetWindow') -and $m['targetWindow']) { $target = [string]$m['targetWindow'] }
        $data.macros.Add([ordered]@{ id = $id; name = $name; targetWindow = $target; steps = $steps })
    }
    return @{ Data = $data; NewerVersion = $newer }
}

# Clean data -> file text (same shape and indentation as the HTA's JSON.stringify(..., null, 2)).
# The editor's "collapsed" mark on a block start is view state and is not written.
function ConvertTo-FujiMacroJson {
    param([Parameter(Mandatory)][System.Collections.IDictionary]$Data)
    $macros = New-Object -TypeName 'System.Collections.Generic.List[object]'
    foreach ($m in $Data.macros) {
        $steps = New-Object -TypeName 'System.Collections.Generic.List[object]'
        foreach ($s in $m.steps) {
            if ($s.Contains('collapsed')) {
                $c = [ordered]@{}
                foreach ($k in $s.Keys) { if ($k -ne 'collapsed') { $c[$k] = $s[$k] } }
                $steps.Add($c)
            } else {
                $steps.Add($s)
            }
        }
        $macros.Add([ordered]@{ id = $m.id; name = $m.name; targetWindow = $m.targetWindow; steps = $steps })
    }
    return (ConvertTo-FujiJson -InputObject ([ordered]@{ version = $script:FujiDataVersion; macros = $macros }) -Indent 2)
}

# ----------------------------------------------------------------- block structure (same as the HTA)
function Get-FujiDepth {
    param([Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.IList]$Steps)
    $depths = New-Object -TypeName 'System.Collections.Generic.List[int]'
    $depth = 0
    foreach ($s in $Steps) {
        if (Test-FujiBlockEnd $s.cmd) {
            $depth = [Math]::Max(0, $depth - 1)
            $depths.Add($depth)
        } elseif (Test-FujiBlockMiddle $s.cmd) {
            $depths.Add([Math]::Max(0, $depth - 1))
        } else {
            $depths.Add($depth)
            if (Test-FujiBlockStart $s.cmd) { $depth++ }
        }
    }
    return , $depths.ToArray()
}

function Find-FujiBlockEnd {
    param([System.Collections.IList]$Steps, [int]$StartIndex)
    $depth = 0
    for ($i = $StartIndex; $i -lt $Steps.Count; $i++) {
        if (Test-FujiBlockStart $Steps[$i].cmd) { $depth++ }
        elseif (Test-FujiBlockEnd $Steps[$i].cmd) { $depth--; if ($depth -eq 0) { return $i } }
    }
    return -1
}

function Find-FujiBlockStart {
    param([System.Collections.IList]$Steps, [int]$EndIndex)
    $depth = 0
    for ($i = $EndIndex; $i -ge 0; $i--) {
        if (Test-FujiBlockEnd $Steps[$i].cmd) { $depth++ }
        elseif (Test-FujiBlockStart $Steps[$i].cmd) { $depth--; if ($depth -eq 0) { return $i } }
    }
    return -1
}

# The middle marker (ELSE / CATCH) that belongs directly to the block starting at StartIndex
function Find-FujiBlockMiddle {
    param([System.Collections.IList]$Steps, [int]$StartIndex, [string]$Cmd)
    $depth = 0
    for ($i = $StartIndex + 1; $i -lt $Steps.Count; $i++) {
        if (Test-FujiBlockStart $Steps[$i].cmd) { $depth++ }
        elseif (Test-FujiBlockEnd $Steps[$i].cmd) { if ($depth -eq 0) { return -1 }; $depth-- }
        elseif ($depth -eq 0 -and $Steps[$i].cmd -eq $Cmd) { return $i }
    }
    return -1
}

# Index of the block start that directly contains Index, or -1
function Find-FujiBlockOwner {
    param([System.Collections.IList]$Steps, [int]$Index)
    $depth = 0
    for ($i = $Index - 1; $i -ge 0; $i--) {
        if (Test-FujiBlockEnd $Steps[$i].cmd) { $depth++ }
        elseif (Test-FujiBlockStart $Steps[$i].cmd) { if ($depth -eq 0) { return $i }; $depth-- }
    }
    return -1
}

function Get-FujiBlockMiddleIndex {
    param([System.Collections.IList]$Steps, [int]$Start, [int]$End)
    $list = @()
    $depth = 0
    for ($i = $Start + 1; $i -lt $End; $i++) {
        if (Test-FujiBlockStart $Steps[$i].cmd) { $depth++ }
        elseif (Test-FujiBlockEnd $Steps[$i].cmd) { $depth-- }
        elseif ($depth -eq 0 -and (Test-FujiBlockMiddle $Steps[$i].cmd)) { $list += $i }
    }
    return , $list
}

# @{ From; To }: a block start covers its whole block
function Get-FujiBlockRange {
    param([System.Collections.IList]$Steps, [int]$Index)
    $to = $Index
    if ($Index -ge 0 -and $Index -lt $Steps.Count -and (Test-FujiBlockStart $Steps[$Index].cmd)) {
        $end = Find-FujiBlockEnd -Steps $Steps -StartIndex $Index
        if ($end -gt $Index) { $to = $end }
    }
    return @{ From = $Index; To = $to }
}

# Every block closed by its own kind of end; ELSE only directly inside an if-block, CATCH only
# directly inside a try-block, at most one each
function Test-FujiBlockBalanced {
    param([Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.IList]$Steps)
    $stack = New-Object -TypeName 'System.Collections.Generic.List[object]'
    foreach ($s in $Steps) {
        $c = $s.cmd
        if (Test-FujiBlockStart $c) {
            $stack.Add(@{ Cmd = $c; Middles = @{} })
        } elseif (Test-FujiBlockEnd $c) {
            if ($stack.Count -eq 0 -or $stack[$stack.Count - 1].Cmd -ne (Get-FujiBlockStartOf $c)) { return $false }
            $stack.RemoveAt($stack.Count - 1)
        } elseif (Test-FujiBlockMiddle $c) {
            if ($stack.Count -eq 0) { return $false }
            $top = $stack[$stack.Count - 1]
            if ($top.Cmd -ne (Get-FujiBlockOwnerOf $c) -or $top.Middles.ContainsKey($c)) { return $false }
            $top.Middles[$c] = $true
        }
    }
    return ($stack.Count -eq 0)
}

# Variables a macro defines (for the placeholder helper), "error text" always included
function Get-FujiDefinedVarName {
    param([Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.IList]$Steps, [string]$ErrorVarName = '')
    $names = New-Object -TypeName 'System.Collections.Generic.List[string]'
    if ($ErrorVarName) { $names.Add($ErrorVarName) }
    foreach ($s in $Steps) {
        $def = Get-FujiCommandDef -Cmd $s.cmd
        if ($null -eq $def -or -not $def.Contains('definesVar')) { continue }
        $name = ([string](ConvertFrom-FujiStepValue -Cmd $s.cmd -Value $s.val)[$def['definesVar']]).Trim()
        if (-not $name -and $s.cmd -eq 'LOOP_START') { $name = [string]$def['parseDefaults']['counter'] }
        if ($name -and -not $names.Contains($name)) { $names.Add($name) }
    }
    return , $names.ToArray()
}

function Test-FujiExecutableStep {
    param([System.Collections.IDictionary]$Step)
    if ($Step.Contains('disabled') -and $Step['disabled']) { return $false }
    $c = $Step.cmd
    return -not ($c -eq 'COMMENT' -or (Test-FujiBlockStart $c) -or (Test-FujiBlockEnd $c) -or (Test-FujiBlockMiddle $c))
}

# ===== src/Editor.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Editor: state and operations behind the window (no Windows Forms here, so it is testable)
#  The window calls these functions and redraws; every change goes through Submit-FujiEditorChange
#  (undo history, "unsaved" mark, autosave to the temp file) like the HTA's commitChange.
#
#  Editor (hashtable):
#    Directory   folder of the macros file and the other working files
#    Log         { param($Message, $Level) }  Level: info | ok | warn | error
#    Data        [ordered]@{ version; macros = List }   (Data.ps1)
#    MacroIndex  current macro;  Selected  selected step index or -1
#    History     List of @{ Desc; Time; MacroIndex; Selected; Data };  HistoryPos
#    Dirty, SaveBlockReason (save needs confirming), Notices (shown once after start)
#    Csv         @{ Path; Encoding; Records; Header; Rows; Warnings }
#  A collapsed block start carries collapsed = $true (view state, never written to files).
# ---------------------------------------------------------------------------------------------

$script:FujiFileNames = @{
    Macro         = 'fujikyun_macros.json'
    Temp          = 'fujikyun_macros_temp.json'
    DiscardedTemp = 'fujikyun_macros_temp_discarded'
    Broken        = 'fujikyun_macros_broken'
    Backup        = 'fujikyun_macros_backup.json'
    Samples       = 'samples'
    Export        = 'macro_export'
    Images        = 'rpa_images'
}
$script:FujiHistoryLimit = 30

function New-FujiEditor {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Creates an in-memory value only')]
    param([Parameter(Mandatory)][string]$Directory, [scriptblock]$Log = $null)
    return @{
        Directory       = $Directory
        Log             = $Log
        Data            = [ordered]@{ version = $script:FujiDataVersion; macros = (New-Object -TypeName 'System.Collections.Generic.List[object]') }
        MacroIndex      = 0
        Selected        = -1
        History         = (New-Object -TypeName 'System.Collections.Generic.List[object]')
        HistoryPos      = -1
        Dirty           = $false
        SaveBlockReason = ''
        Notices         = (New-Object -TypeName 'System.Collections.Generic.List[string]')
        Csv             = (New-FujiCsvState)
    }
}

function Write-FujiEditorLog {
    param([hashtable]$Editor, [string]$Message, [string]$Level = 'info')
    if ($Editor.Log) { & $Editor.Log $Message $Level }
}

function Get-FujiEditorPath {
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][string]$Name)
    return (Join-Path -Path $Editor.Directory -ChildPath $Name)
}

# A path typed by the user: absolute (C:\.. or \\server\..) as is, otherwise inside the working folder
function Resolve-FujiEditorPath {
    param([Parameter(Mandatory)][hashtable]$Editor, [AllowEmptyString()][string]$Path)
    $p = ([string]$Path).Trim().Trim('"')
    if ($p -eq '') { return '' }
    if ($p -match '^[A-Za-z]:[\\/]' -or $p -match '^\\\\') { return $p }
    return (Get-FujiEditorPath -Editor $Editor -Name ($p -replace '/', '\'))
}

function Get-FujiTimeStamp { return (Get-Date -Format 'yyyyMMdd_HHmmss') }

# File name from free text (macro names): no path characters, at most 80 characters
function Get-FujiSafeFileName {
    param([AllowEmptyString()][string]$Text)
    $name = ([regex]::Replace([string]$Text, '[\\/:*?"<>|\r\n\t]', '_')).Trim()
    if ($name.Length -gt 80) { $name = $name.Substring(0, 80) }
    return $name
}

# ----------------------------------------------------------------- copies (undo history, duplicates)
function Copy-FujiStep {
    param([Parameter(Mandatory)][System.Collections.IDictionary]$Step)
    $o = [ordered]@{}
    foreach ($k in $Step.Keys) { $o[$k] = $Step[$k] }
    return $o
}

function Copy-FujiMacro {
    param([Parameter(Mandatory)][System.Collections.IDictionary]$Macro)
    $steps = New-Object -TypeName 'System.Collections.Generic.List[object]'
    foreach ($s in $Macro.steps) {
        $o = [ordered]@{}
        foreach ($k in $s.Keys) { $o[$k] = $s[$k] }
        $steps.Add($o)
    }
    return [ordered]@{ id = $Macro.id; name = $Macro.name; targetWindow = $Macro.targetWindow; steps = $steps }
}

function Copy-FujiMacroData {
    param([Parameter(Mandatory)][System.Collections.IDictionary]$Data)
    $list = New-Object -TypeName 'System.Collections.Generic.List[object]'
    foreach ($m in $Data.macros) { $list.Add((Copy-FujiMacro -Macro $m)) }
    return [ordered]@{ version = $Data.version; macros = $list }
}

# ----------------------------------------------------------------- current macro
function Get-FujiCurrentMacro {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $i = $Editor.MacroIndex
    if ($i -ge 0 -and $i -lt $Editor.Data.macros.Count) { return $Editor.Data.macros[$i] }
    return $null
}

function Get-FujiCurrentStepList {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $m = Get-FujiCurrentMacro -Editor $Editor
    if ($null -eq $m) { return , (New-Object -TypeName 'System.Collections.Generic.List[object]') }
    return , $m.steps
}

function New-FujiMacroId {
    param([Parameter(Mandatory)][hashtable]$Editor)
    do {
        $id = New-FujiId
        $used = $false
        foreach ($m in $Editor.Data.macros) { if ($m.id -eq $id) { $used = $true } }
    } while ($used)
    return $id
}

# { param($Id) ... } giving a macro's current name (CALL_MACRO labels)
function Get-FujiMacroNameLookup {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $ed = $Editor
    return {
        param($Id)
        foreach ($m in $ed.Data.macros) { if ($m.id -eq $Id) { return $m.name } }
        return ''
    }.GetNewClosure()
}

function Initialize-FujiMacroList {
    param([Parameter(Mandatory)][hashtable]$Editor)
    if ($Editor.Data.macros.Count -eq 0) {
        $steps = New-Object -TypeName 'System.Collections.Generic.List[object]'
        $Editor.Data.macros.Add([ordered]@{ id = (New-FujiMacroId -Editor $Editor); name = (Get-FujiText 'editor.newMacro'); targetWindow = ''; steps = $steps })
    }
    if ($Editor.MacroIndex -lt 0 -or $Editor.MacroIndex -ge $Editor.Data.macros.Count) { $Editor.MacroIndex = 0 }
}

# ----------------------------------------------------------------- loading and saving
function New-FujiSampleData {
    $steps = @(
        [ordered]@{ cmd = 'COMMENT'; val = (Get-FujiText 'editor.sampleComment'); label = '' }
        [ordered]@{ cmd = 'GROUP_START'; val = (Get-FujiText 'editor.sampleGroup'); label = '' }
        [ordered]@{ cmd = 'CSV'; val = '1'; label = '' }
        [ordered]@{ cmd = 'KEY'; val = '{TAB}'; label = '' }
        [ordered]@{ cmd = 'CSV'; val = '2'; label = '' }
        [ordered]@{ cmd = 'KEY'; val = '{ENTER}'; label = '' }
        [ordered]@{ cmd = 'GROUP_END'; val = ''; label = '' }
        [ordered]@{ cmd = 'WAIT'; val = '500'; label = '' }
    )
    return [ordered]@{
        version = $script:FujiDataVersion
        macros  = @([ordered]@{ id = (New-FujiId); name = (Get-FujiText 'editor.sampleName'); targetWindow = (Get-FujiText 'editor.sampleTarget'); steps = $steps })
    }
}

# Parsed file content, or $null (logged) when the file cannot be read as JSON
function Read-FujiMacroFile {
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][string]$Path)
    try {
        return (ConvertFrom-FujiJson -Json (Read-FujiUtf8File -Path $Path))
    } catch {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.readFailed' $Path $_.Exception.Message) -Level 'error'
        return $null
    }
}

function Get-FujiFileDataVersion {
    param($Source)
    if ($Source -is [System.Collections.IDictionary] -and $Source.Contains('version') -and $Source['version'] -is [ValueType]) {
        return [double]$Source['version']
    }
    return 0
}

# A file from a newer edition: saving it here would turn unknown commands into comments
function Test-FujiEditorDataVersion {
    param([Parameter(Mandatory)][hashtable]$Editor, $Source, [string]$What)
    $v = Get-FujiFileDataVersion -Source $Source
    if ($v -gt $script:FujiDataVersion) {
        $Editor.SaveBlockReason = Get-FujiText 'editor.newerVersion' $What $v $script:FujiDataVersion
        $Editor.Notices.Add($Editor.SaveBlockReason)
    }
}

# Moves the temp file aside under a timestamped name; $false when it could not be moved
function Move-FujiTempFileAside {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $name = $script:FujiFileNames.DiscardedTemp + '_' + (Get-FujiTimeStamp) + '.json'
    try {
        Move-Item -LiteralPath (Get-FujiEditorPath $Editor $script:FujiFileNames.Temp) -Destination (Get-FujiEditorPath $Editor $name) -ErrorAction Stop
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.tempMoved' $name)
        return $true
    } catch {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.tempMoveFailed' $_.Exception.Message) -Level 'warn'
        return $false
    }
}

function Copy-FujiUnreadableFile {
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][string]$Path)
    $name = $script:FujiFileNames.Broken + '_' + (Get-FujiTimeStamp) + '.json'
    $dest = Get-FujiEditorPath $Editor $name
    try {
        if (Test-Path -LiteralPath $dest) { return '' }
        Copy-Item -LiteralPath $Path -Destination $dest -ErrorAction Stop
        return $name
    } catch {
        return ''
    }
}

# Startup (the HTA's loadInitialData). AskRestoreTemp: { $true = restore the temp file }
function Initialize-FujiEditorData {
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][scriptblock]$AskRestoreTemp)
    $loaded = $null
    $tempPath = Get-FujiEditorPath $Editor $script:FujiFileNames.Temp
    $mainPath = Get-FujiEditorPath $Editor $script:FujiFileNames.Macro
    if (Test-Path -LiteralPath $tempPath -PathType Leaf) {
        if (& $AskRestoreTemp) {
            $loaded = Read-FujiMacroFile -Editor $Editor -Path $tempPath
            if ($null -ne $loaded) {
                $Editor.Dirty = $true
                Test-FujiEditorDataVersion -Editor $Editor -Source $loaded -What (Get-FujiText 'editor.whatTemp')
                Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.tempRestored') -Level 'ok'
            }
        } elseif (-not (Move-FujiTempFileAside -Editor $Editor)) {
            # It could not be moved aside: open it rather than let the next autosave overwrite it unseen
            $loaded = Read-FujiMacroFile -Editor $Editor -Path $tempPath
            if ($null -ne $loaded) {
                $Editor.Dirty = $true
                Test-FujiEditorDataVersion -Editor $Editor -Source $loaded -What (Get-FujiText 'editor.whatTemp')
                $Editor.Notices.Add((Get-FujiText 'editor.tempNotMoved' $script:FujiFileNames.Macro))
            }
        }
    }
    if ($null -eq $loaded -and (Test-Path -LiteralPath $mainPath -PathType Leaf)) {
        $loaded = Read-FujiMacroFile -Editor $Editor -Path $mainPath
        if ($null -ne $loaded) {
            Test-FujiEditorDataVersion -Editor $Editor -Source $loaded -What (Get-FujiText 'editor.whatMain')
            Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.mainLoaded' $script:FujiFileNames.Macro) -Level 'ok'
        } else {
            # Never treat an existing but unreadable file like a missing one: keep a copy and guard the next save
            $copy = Copy-FujiUnreadableFile -Editor $Editor -Path $mainPath
            $kept = Get-FujiText 'editor.brokenNotCopied'
            if ($copy) { $kept = Get-FujiText 'editor.brokenCopied' $copy }
            $Editor.SaveBlockReason = Get-FujiText 'editor.mainUnreadable' $script:FujiFileNames.Macro $kept
            $hint = ''
            if (Test-Path -LiteralPath (Get-FujiEditorPath $Editor $script:FujiFileNames.Backup) -PathType Leaf) {
                $hint = Get-FujiText 'editor.backupHint' $script:FujiFileNames.Backup
            }
            $Editor.Notices.Add($Editor.SaveBlockReason + (Get-FujiText 'editor.mainUnreadableNotice' $hint))
        }
    }
    if ($null -eq $loaded) {
        $loaded = New-FujiSampleData
        if ($Editor.SaveBlockReason) {
            Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.sampleShownBroken') -Level 'error'
        } else {
            Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.sampleCreated')
        }
    }
    $Editor.Data = (ConvertTo-FujiMacroData -Source $loaded).Data
    $Editor.MacroIndex = 0
    $Editor.Selected = -1
    Initialize-FujiMacroList -Editor $Editor
    $Editor.History.Clear()
    $Editor.HistoryPos = -1
    Add-FujiHistory -Editor $Editor -Description (Get-FujiText 'editor.historyStart')
}

function Save-FujiEditorTemp {
    param([Parameter(Mandatory)][hashtable]$Editor)
    try {
        Write-FujiTextFile -Path (Get-FujiEditorPath $Editor $script:FujiFileNames.Temp) -Text (ConvertTo-FujiMacroJson -Data $Editor.Data)
    } catch {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.autoSaveFailed' $_.Exception.Message) -Level 'error'
    }
}

# Writes the macros file (previous version kept as the backup) and removes the temp file.
# The caller asks first when SaveBlockReason is set. Returns '' or the error text.
function Save-FujiEditorData {
    param([Parameter(Mandatory)][hashtable]$Editor)
    try {
        Write-FujiFileSafely -Path (Get-FujiEditorPath $Editor $script:FujiFileNames.Macro) -Text (ConvertTo-FujiMacroJson -Data $Editor.Data) -BackupPath (Get-FujiEditorPath $Editor $script:FujiFileNames.Backup)
    } catch {
        $msg = $_.Exception.Message
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.saveFailed' $msg) -Level 'error'
        return $msg
    }
    $temp = Get-FujiEditorPath $Editor $script:FujiFileNames.Temp
    if (Test-Path -LiteralPath $temp) { Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue }
    $Editor.Dirty = $false
    Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.saved' $script:FujiFileNames.Macro $script:FujiFileNames.Backup) -Level 'ok'
    return ''
}

# ----------------------------------------------------------------- undo / redo
function Add-FujiHistory {
    param([Parameter(Mandatory)][hashtable]$Editor, [string]$Description)
    $h = $Editor.History
    if ($Editor.HistoryPos -lt $h.Count - 1) {
        $h.RemoveRange($Editor.HistoryPos + 1, $h.Count - $Editor.HistoryPos - 1)
    }
    $h.Add(@{
            Desc       = $Description
            Time       = (Get-Date -Format 'HH:mm:ss')
            MacroIndex = $Editor.MacroIndex
            Selected   = $Editor.Selected
            Data       = (Copy-FujiMacroData -Data $Editor.Data)
        })
    while ($h.Count -gt $script:FujiHistoryLimit) { $h.RemoveAt(0) }
    $Editor.HistoryPos = $h.Count - 1
}

# After every data change (add / edit / delete / move ...)
function Submit-FujiEditorChange {
    param([Parameter(Mandatory)][hashtable]$Editor, [string]$Description)
    Add-FujiHistory -Editor $Editor -Description $Description
    $Editor.Dirty = $true
    Save-FujiEditorTemp -Editor $Editor
}

# ShowMacroIndex: macro to display (undo shows the macro whose change is being undone)
function Restore-FujiHistory {
    param([Parameter(Mandatory)][hashtable]$Editor, [int]$Position, [int]$ShowMacroIndex = -1, [string]$UndoneDescription = '')
    if ($Position -lt 0 -or $Position -ge $Editor.History.Count -or $Position -eq $Editor.HistoryPos) { return $false }
    $h = $Editor.History[$Position]
    $Editor.Data = Copy-FujiMacroData -Data $h.Data
    $Editor.HistoryPos = $Position
    $target = $h.MacroIndex
    if ($ShowMacroIndex -ge 0) { $target = $ShowMacroIndex }
    $Editor.MacroIndex = [Math]::Min($target, $Editor.Data.macros.Count - 1)
    Initialize-FujiMacroList -Editor $Editor
    $Editor.Selected = -1
    if ($target -eq $h.MacroIndex) { $Editor.Selected = [Math]::Min($h.Selected, (Get-FujiCurrentStepList $Editor).Count - 1) }
    $Editor.Dirty = $true
    Save-FujiEditorTemp -Editor $Editor
    if ($UndoneDescription) {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.undone' $UndoneDescription)
    } else {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.jumped' ($Position + 1) $h.Desc)
    }
    return $true
}

function Undo-FujiEditorChange {
    param([Parameter(Mandatory)][hashtable]$Editor)
    if ($Editor.HistoryPos -lt 1) { return $false }
    $current = $Editor.History[$Editor.HistoryPos]
    return (Restore-FujiHistory -Editor $Editor -Position ($Editor.HistoryPos - 1) -ShowMacroIndex $current.MacroIndex -UndoneDescription $current.Desc)
}

function Redo-FujiEditorChange {
    param([Parameter(Mandatory)][hashtable]$Editor)
    return (Restore-FujiHistory -Editor $Editor -Position ($Editor.HistoryPos + 1))
}

# ----------------------------------------------------------------- macros
function Add-FujiMacro {
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][string]$Name)
    $Editor.Data.macros.Add([ordered]@{ id = (New-FujiMacroId $Editor); name = $Name; targetWindow = ''; steps = (New-Object -TypeName 'System.Collections.Generic.List[object]') })
    $Editor.MacroIndex = $Editor.Data.macros.Count - 1
    $Editor.Selected = -1
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.macroAdd' $Name)
    Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.macroAdded' $Name) -Level 'ok'
}

function Rename-FujiMacro {
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][string]$Name)
    $m = Get-FujiCurrentMacro $Editor
    if ($null -eq $m -or $m.name -ceq $Name) { return }
    $m.name = $Name
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.macroRename' $Name)
}

function Copy-FujiCurrentMacro {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $m = Get-FujiCurrentMacro $Editor
    if ($null -eq $m) { return }
    $copy = Copy-FujiMacro -Macro $m
    $copy.id = New-FujiMacroId $Editor
    $copy.name = Get-FujiText 'editor.copyName' $m.name
    $Editor.Data.macros.Insert($Editor.MacroIndex + 1, $copy)
    $Editor.MacroIndex++
    $Editor.Selected = -1
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.macroCopy' $copy.name)
    Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.macroCopied' $copy.name) -Level 'ok'
}

function Remove-FujiCurrentMacro {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'The window asks before calling; undo restores it')]
    param([Parameter(Mandatory)][hashtable]$Editor)
    $m = Get-FujiCurrentMacro $Editor
    if ($null -eq $m) { return }
    $Editor.Data.macros.RemoveAt($Editor.MacroIndex)
    Initialize-FujiMacroList -Editor $Editor
    if ($Editor.MacroIndex -ge $Editor.Data.macros.Count) { $Editor.MacroIndex = $Editor.Data.macros.Count - 1 }
    $Editor.Selected = -1
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.macroDelete' $m.name)
    Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.macroDeleted' $m.name) -Level 'warn'
}

function Set-FujiTargetWindow {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Edits in-memory data; undo restores it')]
    param([Parameter(Mandatory)][hashtable]$Editor, [AllowEmptyString()][string]$Title)
    $m = Get-FujiCurrentMacro $Editor
    $value = ([string]$Title).Trim()
    if ($null -eq $m -or $m.targetWindow -ceq $value) { return }
    $m.targetWindow = $value
    $shown = $value
    if (-not $shown) { $shown = Get-FujiText 'editor.history.none' }
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.target' $shown)
    if (-not $value) { $value = Get-FujiText 'editor.targetNone' }
    Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.targetSet' $value)
}

# Writes the current macro to macro_export\<name>.json (never overwriting) and returns the path
function Export-FujiCurrentMacro {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $m = Get-FujiCurrentMacro $Editor
    $folder = Get-FujiEditorPath $Editor $script:FujiFileNames.Export
    if (-not (Test-Path -LiteralPath $folder -PathType Container)) { [void](New-Item -ItemType Directory -Path $folder) }
    $stem = Get-FujiSafeFileName $m.name
    if (-not $stem) { $stem = 'macro' }
    $path = Join-Path $folder ($stem + '.json')
    for ($n = 2; Test-Path -LiteralPath $path; $n++) { $path = Join-Path $folder ('{0} ({1}).json' -f $stem, $n) }
    Write-FujiTextFile -Path $path -Text (ConvertTo-FujiMacroJson -Data @{ macros = @($m) })
    Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.exported' $m.name $path) -Level 'ok'
    return $path
}

# Adds the macros of an exported file. Returns '' or a message the window shows (file too new).
function Import-FujiMacroFile {
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][string]$Path)
    $obj = Read-FujiMacroFile -Editor $Editor -Path $Path
    if ($null -eq $obj) { return '' }
    $v = Get-FujiFileDataVersion -Source $obj
    if ($v -gt $script:FujiDataVersion) { return (Get-FujiText 'editor.importNewer' $v $script:FujiDataVersion) }
    $data = (ConvertTo-FujiMacroData -Source $obj).Data
    if ($data.macros.Count -eq 0) {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.importEmpty' $Path) -Level 'warn'
        return ''
    }
    foreach ($m in $data.macros) {
        $m.id = New-FujiMacroId $Editor
        $Editor.Data.macros.Add($m)
    }
    $Editor.MacroIndex = $Editor.Data.macros.Count - 1
    $Editor.Selected = -1
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.import' $data.macros[0].name)
    Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.imported' $data.macros.Count $Path) -Level 'ok'
    return ''
}

# ----------------------------------------------------------------- templates
function Get-FujiTemplateStep {
    param([Parameter(Mandatory)][System.Collections.IDictionary]$Template, [scriptblock]$MacroNameOf = $null)
    $out = New-Object -TypeName 'System.Collections.Generic.List[object]'
    foreach ($item in $Template['steps']) {
        $val = ''
        if ($item.Count -gt 1 -and $null -ne $item[1]) { $val = [string]$item[1] }
        $step = [ordered]@{ cmd = [string]$item[0]; val = $val; label = '' }
        if ($item.Count -gt 2 -and $item[2] -is [System.Collections.IDictionary]) {
            foreach ($k in $item[2].Keys) { $step[$k] = $item[2][$k] }
        }
        if (-not $step.label) { $step.label = Get-FujiStepLabel -Cmd $step.cmd -Value $val -MacroNameOf $MacroNameOf }
        $out.Add($step)
    }
    return , $out
}

function ConvertTo-FujiTemplateCsvText {
    param([Parameter(Mandatory)][System.Collections.IDictionary]$Template)
    $rows = @()
    foreach ($r in $Template['csv']) { $rows += , ([string[]]@($r)) }
    return (ConvertTo-FujiCsvText -Rows $rows)
}

# samples\<csvFile> (an existing file is kept so user edits survive); returns its path or ''
function Write-FujiTemplateCsv {
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][System.Collections.IDictionary]$Template)
    if (-not $Template['csvFile']) { return '' }
    $folder = Get-FujiEditorPath $Editor $script:FujiFileNames.Samples
    if (-not (Test-Path -LiteralPath $folder -PathType Container)) { [void](New-Item -ItemType Directory -Path $folder) }
    $path = Join-Path $folder ([string]$Template['csvFile'])
    if (-not (Test-Path -LiteralPath $path)) {
        Write-FujiTextFile -Path $path -Text (ConvertTo-FujiTemplateCsvText -Template $Template) -Bom
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.templateCsv' $path) -Level 'ok'
    }
    return $path
}

# New macro from a built-in template; returns its name
function New-FujiMacroFromTemplate {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Edits in-memory data; undo restores it')]
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][System.Collections.IDictionary]$Template)
    $base = [string]$Template['name']
    $name = $base
    $n = 2
    while (@($Editor.Data.macros | Where-Object { $_.name -ceq $name }).Count -gt 0) {
        $name = '{0} ({1})' -f $base, $n
        $n++
    }
    $steps = Get-FujiTemplateStep -Template $Template -MacroNameOf (Get-FujiMacroNameLookup $Editor)
    $Editor.Data.macros.Add([ordered]@{ id = (New-FujiMacroId $Editor); name = $name; targetWindow = [string]$Template['targetWindow']; steps = $steps })
    $Editor.MacroIndex = $Editor.Data.macros.Count - 1
    $Editor.Selected = -1
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.template' $name)
    Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.templateCreated' $base) -Level 'ok'
    return $name
}

# ----------------------------------------------------------------- the step list
# Visible rows: @{ Index; Depth; HiddenCount } (blocks inside a collapsed block are left out).
# Moves the selection off a hidden step, like the HTA's renderSteps.
function Get-FujiStepRow {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $steps = Get-FujiCurrentStepList $Editor
    $rows = New-Object -TypeName 'System.Collections.Generic.List[object]'
    $depths = Get-FujiDepth -Steps $steps
    $hideUntil = -1
    $hidden = New-Object -TypeName 'System.Collections.Generic.List[bool]'
    for ($i = 0; $i -lt $steps.Count; $i++) {
        $isHidden = $i -le $hideUntil
        $hidden.Add($isHidden)
        if ($isHidden) { continue }
        $count = 0
        if ((Test-FujiBlockStart $steps[$i].cmd) -and $steps[$i].Contains('collapsed') -and $steps[$i]['collapsed']) {
            $end = Find-FujiBlockEnd -Steps $steps -StartIndex $i
            if ($end -lt 0) { $hideUntil = $steps.Count - 1; $count = $steps.Count - $i - 1 } else { $hideUntil = $end; $count = [Math]::Max(0, $end - $i - 1) }
        }
        $rows.Add(@{ Index = $i; Depth = $depths[$i]; HiddenCount = $count })
    }
    if ($Editor.Selected -ge $steps.Count) { $Editor.Selected = $steps.Count - 1 }
    while ($Editor.Selected -gt 0 -and $hidden[$Editor.Selected]) { $Editor.Selected-- }
    return , $rows
}

# New commands go right after the selected step (after the whole block if it is collapsed)
function Get-FujiInsertionIndex {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $steps = Get-FujiCurrentStepList $Editor
    $sel = $Editor.Selected
    if ($sel -lt 0 -or $sel -ge $steps.Count) { return $steps.Count }
    if ((Test-FujiBlockStart $steps[$sel].cmd) -and $steps[$sel].Contains('collapsed') -and $steps[$sel]['collapsed']) {
        $end = Find-FujiBlockEnd -Steps $steps -StartIndex $sel
        if ($end -ge 0) { return $end + 1 }
    }
    return $sel + 1
}

function Expand-FujiAncestor {
    param([Parameter(Mandatory)][AllowEmptyCollection()][System.Collections.IList]$Steps, [int]$Index)
    $stack = New-Object -TypeName 'System.Collections.Generic.List[int]'
    for ($i = 0; $i -lt $Index -and $i -lt $Steps.Count; $i++) {
        if (Test-FujiBlockStart $Steps[$i].cmd) { $stack.Add($i) }
        elseif ((Test-FujiBlockEnd $Steps[$i].cmd) -and $stack.Count -gt 0) { $stack.RemoveAt($stack.Count - 1) }
    }
    foreach ($j in $stack) { $Steps[$j].Remove('collapsed') }
}

function Switch-FujiBlockCollapsed {
    param([Parameter(Mandatory)][hashtable]$Editor, [int]$Index)
    $steps = Get-FujiCurrentStepList $Editor
    if ($Index -lt 0 -or $Index -ge $steps.Count -or -not (Test-FujiBlockStart $steps[$Index].cmd)) { return }
    $step = $steps[$Index]
    if ($step.Contains('collapsed')) { $step.Remove('collapsed'); return }
    $step['collapsed'] = $true
    if ($Editor.Selected -gt $Index) {
        $end = Find-FujiBlockEnd -Steps $steps -StartIndex $Index
        if ($end -lt 0 -or $Editor.Selected -le $end) { $Editor.Selected = $Index }
    }
}

function Set-FujiAllCollapsed {
    param([Parameter(Mandatory)][hashtable]$Editor, [bool]$Collapsed)
    foreach ($s in (Get-FujiCurrentStepList $Editor)) {
        if (-not (Test-FujiBlockStart $s.cmd)) { continue }
        if ($Collapsed) { $s['collapsed'] = $true } else { $s.Remove('collapsed') }
    }
    if ($Collapsed) { $Editor.Selected = -1 }
}

function Get-FujiStepCaption {
    param([System.Collections.IDictionary]$Step, [int]$Max = 24)
    $t = [string]$Step.label
    if (-not $t) { $t = [string]$Step.cmd }
    return (Format-FujiShort $t $Max)
}

# ----------------------------------------------------------------- step operations
# Step: @{ cmd; val; label [; when] } from Complete-FujiStepEdit. $false when it cannot go there.
function Add-FujiEditorStep {
    param([Parameter(Mandatory)][hashtable]$Editor, [Parameter(Mandatory)][System.Collections.IDictionary]$Step)
    $steps = Get-FujiCurrentStepList $Editor
    $cmd = $Step.cmd
    $at = Get-FujiInsertionIndex $Editor
    $pieces = New-Object -TypeName 'System.Collections.Generic.List[object]'
    $pieces.Add($Step)
    if ($cmd -eq 'TRY_START') { $pieces.Add([ordered]@{ cmd = 'CATCH'; val = ''; label = (Get-FujiCommandDef 'CATCH')['title'] }) }
    if (Test-FujiBlockStart $cmd) {
        $endCmd = Get-FujiBlockEndOf $cmd
        $pieces.Add([ordered]@{ cmd = $endCmd; val = ''; label = ((Get-FujiCommandDef $endCmd)['title']) })
    }
    if (Test-FujiBlockMiddle $cmd) {
        $trial = New-Object -TypeName 'System.Collections.Generic.List[object]' -ArgumentList (, [object[]]$steps.ToArray())
        $trial.InsertRange($at, $pieces)
        if (-not (Test-FujiBlockBalanced -Steps $trial)) {
            $owner = Get-FujiBlockOwnerOf $cmd
            Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.middleMisplaced' ((Get-FujiCommandDef $cmd)['title']) ((Get-FujiCommandDef $owner)['title'])) -Level 'warn'
            return $false
        }
    }
    $steps.InsertRange($at, $pieces)
    Expand-FujiAncestor -Steps $steps -Index $at
    $Editor.Selected = $at
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.add' ((Get-FujiCommandDef $cmd)['title']) (Format-FujiShort $Step.label 20))
    return $true
}

# Updated: result of Complete-FujiStepEdit for the same command
function Set-FujiEditorStep {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Edits in-memory data; undo restores it')]
    param([Parameter(Mandatory)][hashtable]$Editor, [int]$Index, [Parameter(Mandatory)][System.Collections.IDictionary]$Updated)
    $steps = Get-FujiCurrentStepList $Editor
    $step = $steps[$Index]
    $step.val = $Updated.val
    $step.label = $Updated.label
    foreach ($f in (Get-FujiCommandDef $step.cmd)['fields']) {
        if (-not $f.Contains('prop')) { continue }
        $id = [string]$f['id']
        if ($Updated.Contains($id) -and $Updated[$id]) { $step[$id] = $Updated[$id] } else { $step.Remove($id) }
    }
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.edit' (Format-FujiShort $Updated.label 24))
}

# Moves steps From..To so that they start at InsertAt (an index of the list before the move)
function Move-FujiEditorRange {
    param([Parameter(Mandatory)][hashtable]$Editor, [int]$From, [int]$To, [int]$InsertAt, [string]$DescriptionKey = 'move')
    $steps = Get-FujiCurrentStepList $Editor
    $count = $To - $From + 1
    if ($InsertAt -ge $From -and $InsertAt -le $To + 1) { return $false }
    # Try the move on a copy first: a block end moved above its own start would leave an unclosed block
    $trial = New-Object -TypeName 'System.Collections.Generic.List[object]' -ArgumentList (, [object[]]$steps.ToArray())
    $moved = $trial.GetRange($From, $count)
    $trial.RemoveRange($From, $count)
    $at = $InsertAt
    if ($at -gt $From) { $at -= $count }
    $trial.InsertRange($at, $moved)
    if ((Test-FujiBlockBalanced -Steps $steps) -and -not (Test-FujiBlockBalanced -Steps $trial)) {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.moveBlocked') -Level 'warn'
        return $false
    }
    $steps.Clear()
    $steps.AddRange($trial)
    Expand-FujiAncestor -Steps $steps -Index $at
    $Editor.Selected = $at
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText ('editor.history.' + $DescriptionKey) (Get-FujiStepCaption $moved[0]))
    return $true
}

# Direction -1 up / 1 down: the selected step, or the whole block when it is a block start
function Move-FujiEditorStep {
    param([Parameter(Mandatory)][hashtable]$Editor, [ValidateSet(-1, 1)][int]$Direction)
    $steps = Get-FujiCurrentStepList $Editor
    $sel = $Editor.Selected
    if ($sel -lt 0 -or $sel -ge $steps.Count) { return $false }
    $range = Get-FujiBlockRange -Steps $steps -Index $sel
    if ($Direction -lt 0) {
        if ($range.From -gt 0) { return (Move-FujiEditorRange -Editor $Editor -From $range.From -To $range.To -InsertAt ($range.From - 1) -DescriptionKey 'moveUp') }
    } elseif ($range.To -lt $steps.Count - 1) {
        return (Move-FujiEditorRange -Editor $Editor -From $range.From -To $range.To -InsertAt ($range.To + 2) -DescriptionKey 'moveDown')
    }
    return $false
}

# The block a start or end step belongs to: @{ Start; End; Name; Kind }, or $null for other steps
function Get-FujiEditorBlock {
    param([Parameter(Mandatory)][hashtable]$Editor, [int]$Index)
    $steps = Get-FujiCurrentStepList $Editor
    if ($Index -lt 0 -or $Index -ge $steps.Count) { return $null }
    $cmd = $steps[$Index].cmd
    $start = -1
    $end = -1
    if (Test-FujiBlockStart $cmd) { $start = $Index; $end = Find-FujiBlockEnd -Steps $steps -StartIndex $Index }
    elseif (Test-FujiBlockEnd $cmd) { $end = $Index; $start = Find-FujiBlockStart -Steps $steps -EndIndex $Index }
    if ($start -lt 0 -or $end -lt 0) { return $null }
    $s = $steps[$start]
    $name = [string]$s.label
    if (-not $name) { $name = Get-FujiStepLabel -Cmd $s.cmd -Value $s.val }
    return @{ Start = $start; End = $end; Name = $name; Kind = [string]((Get-FujiCommandDef $s.cmd)['title']) }
}

# Mode: Step (one step), All (a block with its contents), Frame (a block's start, end and ELSE / CATCH)
function Remove-FujiEditorStep {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'The window asks before removing a block; undo restores it')]
    param([Parameter(Mandatory)][hashtable]$Editor, [int]$Index, [ValidateSet('Step', 'All', 'Frame')][string]$Mode = 'Step')
    $steps = Get-FujiCurrentStepList $Editor
    if ($Index -lt 0 -or $Index -ge $steps.Count) { return }
    $block = $null
    if ($Mode -ne 'Step') { $block = Get-FujiEditorBlock -Editor $Editor -Index $Index }
    if ($null -eq $block) {
        $step = $steps[$Index]
        $steps.RemoveAt($Index)
        $at = $Index
        $desc = Get-FujiText 'editor.history.delete' (Get-FujiStepCaption $step)
    } elseif ($Mode -eq 'All') {
        $steps.RemoveRange($block.Start, $block.End - $block.Start + 1)
        $at = $block.Start
        $desc = Get-FujiText 'editor.history.deleteAll' $block.Kind $block.Name
    } else {
        $middles = Get-FujiBlockMiddleIndex -Steps $steps -Start $block.Start -End $block.End
        $remove = @($block.Start, $block.End) + $middles
        foreach ($r in ($remove | Sort-Object -Descending)) { $steps.RemoveAt($r) }
        $at = $block.Start
        $desc = Get-FujiText 'editor.history.unwrap' $block.Kind $block.Name
    }
    if ($steps.Count -eq 0) { $Editor.Selected = -1 } else { $Editor.Selected = [Math]::Min($at, $steps.Count - 1) }
    Submit-FujiEditorChange -Editor $Editor -Description $desc
}

function Copy-FujiEditorStep {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $steps = Get-FujiCurrentStepList $Editor
    $sel = $Editor.Selected
    if ($sel -lt 0 -or $sel -ge $steps.Count) { return $false }
    $cmd = $steps[$sel].cmd
    if (Test-FujiBlockMiddle $cmd) {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.middleNoCopy' ((Get-FujiCommandDef $cmd)['title'])) -Level 'warn'
        return $false
    }
    $range = Get-FujiBlockRange -Steps $steps -Index $sel
    if (Test-FujiBlockEnd $cmd) {
        # A lone block end would close the enclosing block early: copy the whole block instead
        $start = Find-FujiBlockStart -Steps $steps -EndIndex $sel
        if ($start -lt 0) { return $false }
        $range = @{ From = $start; To = $sel }
    }
    $copies = New-Object -TypeName 'System.Collections.Generic.List[object]'
    for ($i = $range.From; $i -le $range.To; $i++) { $copies.Add((Copy-FujiStep -Step $steps[$i])) }
    $steps.InsertRange($range.To + 1, $copies)
    $Editor.Selected = $range.To + 1
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText 'editor.history.copy' (Get-FujiStepCaption $copies[0]))
    return $true
}

# A disabled step is kept but skipped at run time (a disabled block start skips the whole block)
function Switch-FujiEditorStepDisabled {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $steps = Get-FujiCurrentStepList $Editor
    $sel = $Editor.Selected
    if ($sel -lt 0 -or $sel -ge $steps.Count) { return $false }
    $step = $steps[$sel]
    if ((Test-FujiBlockEnd $step.cmd) -or (Test-FujiBlockMiddle $step.cmd)) {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.noDisable' ((Get-FujiCommandDef $step.cmd)['title'])) -Level 'warn'
        return $false
    }
    if ($step.Contains('disabled')) {
        $step.Remove('disabled')
        $key = 'editor.history.enable'
    } else {
        $step['disabled'] = $true
        $key = 'editor.history.disable'
    }
    Submit-FujiEditorChange -Editor $Editor -Description (Get-FujiText $key (Get-FujiStepCaption $step))
    return $true
}

# ----------------------------------------------------------------- the step editor dialog
# @{ Values = ordered settings by field id (prop fields too); CustomLabel = label typed by the user }
function Get-FujiStepEditState {
    param([Parameter(Mandatory)][string]$Cmd, [System.Collections.IDictionary]$Step = $null, [scriptblock]$MacroNameOf = $null)
    $def = Get-FujiCommandDef $Cmd
    $val = [string]$def['defaultVal']
    if ($null -ne $Step) { $val = [string]$Step.val }
    $values = ConvertFrom-FujiStepValue -Cmd $Cmd -Value $val
    foreach ($f in $def['fields']) {
        if (-not $f.Contains('prop')) { continue }
        $id = [string]$f['id']
        $values[$id] = ''
        if ($null -ne $Step -and $Step.Contains($id) -and $Step[$id]) { $values[$id] = [string]$Step[$id] }
    }
    $custom = ''
    if ($null -ne $Step -and $Step.label -and $Step.label -cne (Get-FujiStepLabel -Cmd $Cmd -Value $val -MacroNameOf $MacroNameOf)) { $custom = [string]$Step.label }
    return @{ Values = $values; CustomLabel = $custom }
}

# Raw: what the dialog's fields hold, by field id. Returns @{ Error } or @{ Step }.
function Complete-FujiStepEdit {
    param([Parameter(Mandatory)][string]$Cmd, [Parameter(Mandatory)][System.Collections.IDictionary]$Raw, [AllowEmptyString()][string]$Label = '', [scriptblock]$MacroNameOf = $null)
    $def = Get-FujiCommandDef $Cmd
    $v = [ordered]@{}
    foreach ($f in $def['fields']) {
        if ($f['type'] -eq 'capture' -or $f['type'] -eq 'rectcapture') { continue }
        $id = [string]$f['id']
        $text = ''
        if ($Raw.Contains($id) -and $null -ne $Raw[$id]) { $text = [string]$Raw[$id] }
        if ($f.Contains('raw') -and $f['raw']) { $v[$id] = $text } else { $v[$id] = $text.Trim() }
    }
    $err = Test-FujiStepSetting -Cmd $Cmd -Settings $v
    if ($err) { return @{ Error = $err } }
    $macroName = ''
    if ($Cmd -eq 'CALL_MACRO' -and $MacroNameOf) { $macroName = [string](& $MacroNameOf $v['id']) }
    $val = ConvertTo-FujiStepValue -Cmd $Cmd -Settings $v -MacroName $macroName
    $text = ([string]$Label).Trim()
    if (-not $text) { $text = Get-FujiStepLabel -Cmd $Cmd -Value $val -MacroNameOf $MacroNameOf }
    $step = [ordered]@{ cmd = $Cmd; val = $val; label = $text }
    foreach ($f in $def['fields']) {
        if ($f.Contains('prop') -and $v[[string]$f['id']]) { $step[[string]$f['id']] = $v[[string]$f['id']] }
    }
    return @{ Step = $step }
}

# ----------------------------------------------------------------- CSV loaded in the editor
function New-FujiCsvState {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Creates an in-memory value only')]
    param()
    return @{ Path = ''; Encoding = ''; Records = @(); Header = $null; Rows = @(); Warnings = @() }
}

function Set-FujiCsvHeader {
    param([Parameter(Mandatory)][hashtable]$Editor, [bool]$HasHeader)
    $csv = $Editor.Csv
    $records = @($csv.Records)
    $csv.Header = $null
    if ($HasHeader -and $records.Count -gt 0) { $csv.Header = [string[]]$records[0] }
    if ($HasHeader) { $csv.Rows = @($records | Select-Object -Skip 1) } else { $csv.Rows = $records }
}

function Get-FujiCsvMaxColumn {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $csv = $Editor.Csv
    $max = 0
    if ($null -ne $csv.Header) { $max = $csv.Header.Length }
    $limit = [Math]::Min(@($csv.Rows).Count, 200)
    for ($i = 0; $i -lt $limit; $i++) { if ($csv.Rows[$i].Length -gt $max) { $max = $csv.Rows[$i].Length } }
    return $max
}

function Get-FujiCsvHeaderName {
    param([Parameter(Mandatory)][hashtable]$Editor, [int]$Column)
    $h = $Editor.Csv.Header
    if ($null -ne $h -and $Column -ge 1 -and $Column -le $h.Length) { return ([string]$h[$Column - 1]).Trim() }
    return ''
}

# Reads a CSV into the editor. Returns @{ Ok; HeaderForced } (HeaderForced: a results / error CSV
# turns "first line is the header" on)
function Import-FujiEditorCsv {
    param([Parameter(Mandatory)][hashtable]$Editor, [AllowEmptyString()][string]$Path, [string]$Encoding = 'auto', [bool]$HasHeader = $true)
    $p = ([string]$Path).Trim().Trim('"')
    if (-not $p) {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.csv.noPath') -Level 'warn'
        return @{ Ok = $false; HeaderForced = $false }
    }
    if (-not (Test-Path -LiteralPath $p -PathType Leaf)) {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.csv.notFound' $p) -Level 'error'
        return @{ Ok = $false; HeaderForced = $false }
    }
    try {
        $res = Read-FujiCsvText -Path $p -Encoding $Encoding
        $parsed = ConvertFrom-FujiCsv -Text $res.Text
    } catch {
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.csv.failed' $_.Exception.Message) -Level 'error'
        return @{ Ok = $false; HeaderForced = $false }
    }
    $csv = $Editor.Csv
    $csv.Path = $p
    $csv.Encoding = $res.Encoding
    $csv.Records = @($parsed.Records)
    $csv.Warnings = @($parsed.Warnings)
    $forced = $false
    if (-not $HasHeader -and $csv.Records.Count -gt 0) {
        $marker = Get-FujiText 'editor.csv.resultHeaderName'
        foreach ($f in $csv.Records[0]) {
            if (([string]$f).Trim() -ceq $marker) { $forced = $true }
        }
        if ($forced) {
            $HasHeader = $true
            Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.csv.resultHeader')
        }
    }
    Set-FujiCsvHeader -Editor $Editor -HasHeader $HasHeader
    Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.csv.loaded' (@($csv.Rows).Count) (Get-FujiEncodingLabel $csv.Encoding) $p) -Level 'ok'
    Write-FujiCsvShapeWarning -Editor $Editor
    return @{ Ok = $true; HeaderForced = $forced }
}

function Get-FujiEncodingLabel {
    param([string]$Encoding)
    $t = Get-FujiText ('editor.csv.encodings.' + $Encoding)
    if ($t -eq ('editor.csv.encodings.' + $Encoding)) { return $Encoding }
    return $t
}

function Write-FujiCsvShapeWarning {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $csv = $Editor.Csv
    foreach ($w in $csv.Warnings) { Write-FujiEditorLog -Editor $Editor -Message ([string][char]0x26A0 + ' ' + $w) -Level 'warn' }
    $rows = @($csv.Rows)
    $expected = 0
    if ($null -ne $csv.Header) { $expected = $csv.Header.Length } elseif ($rows.Count -gt 0) { $expected = $rows[0].Length }
    $odd = New-Object -TypeName 'System.Collections.Generic.List[int]'
    $blank = 0
    for ($i = 0; $i -lt $rows.Count; $i++) {
        if (Test-FujiBlankRow -Row $rows[$i]) { $blank++ }
        elseif ($rows[$i].Length -ne $expected) { $odd.Add($i + 1) }
    }
    if ($odd.Count -gt 0) {
        $list = ($odd | Select-Object -First 5) -join ([string][char]0x30FB)
        if ($odd.Count -gt 5) { $list += Get-FujiText 'editor.csv.oddMore' ($odd.Count - 5) }
        Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.csv.oddRows' $list) -Level 'warn'
    }
    if ($blank -gt 0) { Write-FujiEditorLog -Editor $Editor -Message (Get-FujiText 'editor.csv.blankRows' $blank) }
}

# One line for the toolbar: "rows x columns [encoding] header: ..."
function Get-FujiCsvInfoText {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $csv = $Editor.Csv
    if (-not $csv.Path) { return (Get-FujiText 'editor.csv.none') }
    $text = Get-FujiText 'editor.csv.info' (@($csv.Rows).Count) (Get-FujiCsvMaxColumn $Editor) (Get-FujiEncodingLabel $csv.Encoding)
    if ($null -ne $csv.Header) { $text += Get-FujiText 'editor.csv.infoHeader' (Format-FujiShort ($csv.Header -join ', ') 60) }
    return $text
}

# Choices for the editor's "insert a placeholder" list: @(@(token, description), ...)
function Get-FujiPlaceholderChoice {
    param([Parameter(Mandatory)][hashtable]$Editor)
    $list = New-Object -TypeName 'System.Collections.Generic.List[object]'
    $cols = Get-FujiCsvMaxColumn $Editor
    for ($i = 1; $i -le $cols; $i++) {
        $name = Get-FujiCsvHeaderName -Editor $Editor -Column $i
        # An all-digit header would be read as a column number, and braces cannot be inside a placeholder
        $byName = $name -and $name -notmatch '^[0-9]+$' -and $name -notmatch '[{}]'
        $token = '{{' + $i + '}}'
        if ($byName) { $token = '{{' + $name + '}}' }
        $desc = Get-FujiText 'editor.placeholder.csvCol' $i
        if ($name) { $desc += Get-FujiText 'editor.placeholder.csvColName' $name }
        $list.Add(@($token, $desc))
    }
    if ($cols -eq 0) { $list.Add(@('{{1}}', (Get-FujiText 'editor.placeholder.csvFirst'))) }
    foreach ($n in (Get-FujiDefinedVarName -Steps (Get-FujiCurrentStepList $Editor) -ErrorVarName (Get-FujiText 'data.errorVar'))) {
        $list.Add(@(('{{$' + $n + '}}'), (Get-FujiText 'editor.placeholder.var' $n)))
    }
    foreach ($p in $script:FujiCommands['placeholderHelp']) { $list.Add(@([string]$p[0], [string]$p[1])) }
    return , $list
}

# ----------------------------------------------------------------- screen capture helper
# Rectangle around the cursor kept on the desktop, with the cursor at its centre (CLICK_IMG clicks
# the centre of the match): near an edge it shrinks symmetrically. Screen: @{ X; Y; Width; Height }
function Get-FujiCaptureRect {
    param([int]$X, [int]$Y, [int]$Width, [int]$Height, [Parameter(Mandatory)][hashtable]$Screen)
    $hw = [Math]::Max(1, [Math]::Min([Math]::Floor($Width / 2), [Math]::Min($X - $Screen.X, $Screen.X + $Screen.Width - 1 - $X)))
    $hh = [Math]::Max(1, [Math]::Min([Math]::Floor($Height / 2), [Math]::Min($Y - $Screen.Y, $Screen.Y + $Screen.Height - 1 - $Y)))
    return @{ X = [int]($X - $hw); Y = [int]($Y - $hh); Width = [int]($hw * 2); Height = [int]($hh * 2) }
}

# ===== src/Files.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Files
# ---------------------------------------------------------------------------------------------

# PowerShell 7 (.NET) needs the code pages provider for Shift_JIS; Windows PowerShell 5.1 has it
function Get-FujiEncoding {
    param([Parameter(Mandatory)][ValidateSet('utf-8', 'shift_jis', 'unicode')][string]$Name)
    switch ($Name) {
        'utf-8' { return (New-Object -TypeName System.Text.UTF8Encoding -ArgumentList $false) }
        'unicode' { return [System.Text.Encoding]::Unicode }
        'shift_jis' {
            if ($PSVersionTable.PSEdition -eq 'Core' -and -not $script:FujiCodePagesReady) {
                [System.Text.Encoding]::RegisterProvider([System.Text.CodePagesEncodingProvider]::Instance)
                $script:FujiCodePagesReady = $true
            }
            return [System.Text.Encoding]::GetEncoding(932)
        }
    }
}
$script:FujiCodePagesReady = $false

# Decodes bytes; a byte order mark wins over the requested encoding and is dropped
function ConvertFrom-FujiByteArray {
    param([Parameter(Mandatory)][AllowEmptyCollection()][byte[]]$Bytes, [Parameter(Mandatory)][string]$Encoding)
    if ($Bytes.Length -ge 3 -and $Bytes[0] -eq 0xEF -and $Bytes[1] -eq 0xBB -and $Bytes[2] -eq 0xBF) {
        return (Get-FujiEncoding -Name 'utf-8').GetString($Bytes, 3, $Bytes.Length - 3)
    }
    if ($Bytes.Length -ge 2 -and $Bytes[0] -eq 0xFF -and $Bytes[1] -eq 0xFE) {
        return [System.Text.Encoding]::Unicode.GetString($Bytes, 2, $Bytes.Length - 2)
    }
    return (Get-FujiEncoding -Name $Encoding).GetString($Bytes)
}

# CSV text with the HTA's rules: "auto" tries UTF-8 and falls back to Shift_JIS when the bytes are
# not valid UTF-8. Returns @{ Text; Encoding }.
function Read-FujiCsvText {
    param([Parameter(Mandatory)][string]$Path, [ValidateSet('auto', 'utf-8', 'shift_jis', 'unicode')][string]$Encoding = 'auto')
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    if ($Encoding -ne 'auto') {
        return @{ Text = (ConvertFrom-FujiByteArray -Bytes $bytes -Encoding $Encoding); Encoding = $Encoding }
    }
    $text = ConvertFrom-FujiByteArray -Bytes $bytes -Encoding 'utf-8'
    if ($text.IndexOf([char]0xFFFD) -lt 0) {
        return @{ Text = $text; Encoding = 'utf-8' }
    }
    return @{ Text = (ConvertFrom-FujiByteArray -Bytes $bytes -Encoding 'shift_jis'); Encoding = 'shift_jis' }
}

# UTF-8 (BOM only when asked: CSV files for Excel)
function Write-FujiTextFile {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][AllowEmptyString()][string]$Text, [switch]$Bom)
    $enc = New-Object -TypeName System.Text.UTF8Encoding -ArgumentList ([bool]$Bom)
    [System.IO.File]::WriteAllText($Path, $Text, $enc)
}

# The only good copy is never overwritten in place: write a sibling file, read it back, keep the
# previous version as BackupPath, then replace the target
function Write-FujiFileSafely {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][AllowEmptyString()][string]$Text, [string]$BackupPath)
    $tmp = $Path + '.saving'
    Write-FujiTextFile -Path $tmp -Text $Text
    if ((Read-FujiUtf8File -Path $tmp) -cne $Text) {
        Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
        throw (Get-FujiText 'data.verifyFailed')
    }
    if ($BackupPath -and (Test-Path -LiteralPath $Path -PathType Leaf)) {
        Copy-Item -LiteralPath $Path -Destination $BackupPath -Force
    }
    Copy-Item -LiteralPath $tmp -Destination $Path -Force
    Remove-Item -LiteralPath $tmp -Force
}

# ===== src/Json.ps1 =====
# ---------------------------------------------------------------------------------------------
#  JSON
#  ConvertFrom-Json gives PSCustomObjects (and Windows PowerShell 5.1 has no -AsHashtable), so data
#  is turned into ordered dictionaries and lists once after reading. Writing uses our own
#  serializer: the output is the same on 5.1 and 7 (key order kept, JSON.stringify-style escapes,
#  no depth limit), so files written by the HTA and by this edition look alike.
# ---------------------------------------------------------------------------------------------

function ConvertTo-FujiData {
    param($InputObject)
    if ($null -eq $InputObject) { return $null }
    if ($InputObject -is [System.Management.Automation.PSCustomObject]) {
        $map = [ordered]@{}
        foreach ($p in $InputObject.PSObject.Properties) {
            $map[$p.Name] = ConvertTo-FujiData -InputObject $p.Value
        }
        return $map
    }
    if ($InputObject -is [System.Collections.IList] -and $InputObject -isnot [string]) {
        $list = New-Object -TypeName 'System.Collections.Generic.List[object]'
        foreach ($item in $InputObject) { $list.Add((ConvertTo-FujiData -InputObject $item)) }
        return , $list
    }
    return $InputObject
}

function ConvertFrom-FujiJson {
    param([Parameter(Mandatory)][AllowEmptyString()][string]$Json)
    # Wrapped in an object: ConvertFrom-Json enumerates a top-level array on PowerShell 7 but not on
    # 5.1, and a one-element array would otherwise collapse into its element
    $wrapper = ConvertFrom-Json -InputObject ('{"v":' + $Json + '}')
    $value = ConvertTo-FujiData -InputObject $wrapper.v
    if ($value -is [System.Collections.IList]) { return , $value }
    return $value
}

$script:FujiJsonEscape = New-Object -TypeName System.Text.RegularExpressions.Regex -ArgumentList @('["\\\x00-\x1F]', [System.Text.RegularExpressions.RegexOptions]::CultureInvariant)
$script:FujiJsonEscapes = @{ [char]0x22 = '\"'; [char]0x5C = '\\'; [char]0x08 = '\b'; [char]0x0C = '\f'; [char]0x0A = '\n'; [char]0x0D = '\r'; [char]0x09 = '\t' }

# JSON.stringify's escaping: quote, backslash and control characters only (text stays readable)
function ConvertTo-FujiJsonString {
    param([AllowNull()][AllowEmptyString()][string]$Value)
    if (-not $script:FujiJsonEscape.IsMatch([string]$Value)) { return '"' + $Value + '"' }
    $escaped = $script:FujiJsonEscape.Replace($Value, {
        param($m)
        $c = $m.Value[0]
        if ($script:FujiJsonEscapes.ContainsKey($c)) { return $script:FujiJsonEscapes[$c] }
        return ('\u{0:x4}' -f [int]$c)
    })
    return '"' + $escaped + '"'
}

# Indent: spaces per level (0 = one line), like JSON.stringify(value, null, indent)
function ConvertTo-FujiJson {
    param($InputObject, [int]$Indent = 2, [int]$Level = 0)
    $nl = ''
    $pad = ''
    $padIn = ''
    $colon = ':'
    if ($Indent -gt 0) {
        $nl = "`n"
        $pad = ' ' * ($Indent * $Level)
        $padIn = ' ' * ($Indent * ($Level + 1))
        $colon = ': '
    }
    if ($null -eq $InputObject) { return 'null' }
    if ($InputObject -is [string] -or $InputObject -is [char]) { return (ConvertTo-FujiJsonString -Value ([string]$InputObject)) }
    if ($InputObject -is [bool]) { if ($InputObject) { return 'true' } else { return 'false' } }
    if ($InputObject -is [int] -or $InputObject -is [long] -or $InputObject -is [double] -or $InputObject -is [decimal] -or $InputObject -is [single]) {
        return ([System.Convert]::ToString($InputObject, [System.Globalization.CultureInfo]::InvariantCulture))
    }
    if ($InputObject -is [System.Collections.IDictionary]) {
        if ($InputObject.Count -eq 0) { return '{}' }
        $parts = New-Object -TypeName 'System.Collections.Generic.List[string]'
        foreach ($key in $InputObject.Keys) {
            $parts.Add($padIn + (ConvertTo-FujiJsonString -Value ([string]$key)) + $colon + (ConvertTo-FujiJson -InputObject $InputObject[$key] -Indent $Indent -Level ($Level + 1)))
        }
        return '{' + $nl + ($parts -join (',' + $nl)) + $nl + $pad + '}'
    }
    if ($InputObject -is [System.Collections.IEnumerable]) {
        $parts = New-Object -TypeName 'System.Collections.Generic.List[string]'
        foreach ($item in $InputObject) {
            $parts.Add($padIn + (ConvertTo-FujiJson -InputObject $item -Indent $Indent -Level ($Level + 1)))
        }
        if ($parts.Count -eq 0) { return '[]' }
        return '[' + $nl + ($parts -join (',' + $nl)) + $nl + $pad + ']'
    }
    return (ConvertTo-FujiJsonString -Value ([string]$InputObject))
}

# ===== src/Native.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Windows API functions without a C# compiler
#  Add-Type with C# source starts csc.exe on Windows PowerShell 5.1, which takes seconds (more
#  when antivirus checks it) on every start. The same declarations are made here at run time
#  with System.Reflection.Emit (DefinePInvokeMethod): nothing is compiled or written to disk.
# ---------------------------------------------------------------------------------------------

$script:FujiNative = $null

# The type holding the functions: [type] with static methods, e.g. ($t)::SetProcessDPIAware()
function Get-FujiNativeType {
    if ($null -ne $script:FujiNative) { return $script:FujiNative }
    $name = New-Object -TypeName System.Reflection.AssemblyName -ArgumentList 'FujiNative'
    $asm = [System.Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly($name, [System.Reflection.Emit.AssemblyBuilderAccess]::Run)
    $module = $asm.DefineDynamicModule('FujiNative')
    $tb = $module.DefineType('FujiNative.User32', [System.Reflection.TypeAttributes]'Public, Class, Abstract, Sealed')
    # name, return type, parameter types, character set
    $declarations = @(
        @('SetProcessDPIAware', [bool], [type[]]@(), [System.Runtime.InteropServices.CharSet]::Auto),
        @('SendMessage', [IntPtr], [type[]]@([IntPtr], [int], [IntPtr], [string]), [System.Runtime.InteropServices.CharSet]::Unicode)
    )
    foreach ($d in $declarations) {
        $m = $tb.DefinePInvokeMethod($d[0], 'user32.dll',
            [System.Reflection.MethodAttributes]'Public, Static, PinvokeImpl, HideBySig',
            [System.Reflection.CallingConventions]::Standard, $d[1], $d[2],
            [System.Runtime.InteropServices.CallingConvention]::Winapi, $d[3])
        $m.SetImplementationFlags([System.Reflection.MethodImplAttributes]::PreserveSig)
    }
    $script:FujiNative = $tb.CreateType()
    return $script:FujiNative
}

# ===== src/Placeholders.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Placeholders  {{1}} {{column}} {{$variable}} {{ROW}} {{ROW+1}} {{TODAY}} {{WAREKI}} ...
#  (same rules as the HTA's placeholderValue / expandPlaceholders)
#
#  Context (hashtable):
#    Row     @{ No = <int>; Data = <string[]> }   the CSV row being processed (No 0 = no CSV)
#    Header  <string[]> or $null                  CSV header
#    Vars    <IDictionary>                        variables
#    Now     <datetime>                           optional, for tests (default: Get-Date)
#    Log     <scriptblock> { param($Message, $Level) }   optional
# ---------------------------------------------------------------------------------------------

$script:FujiPlaceholder = New-Object -TypeName System.Text.RegularExpressions.Regex -ArgumentList @('\{\{([^{}]+)\}\}', [System.Text.RegularExpressions.RegexOptions]::CultureInvariant)
# Characters with a meaning on a command line: an inserted value holding one makes RUN refuse the row
$script:FujiCommandUnsafe = New-Object -TypeName System.Text.RegularExpressions.Regex -ArgumentList @('["&|<>^%\r\n]', [System.Text.RegularExpressions.RegexOptions]::CultureInvariant)

function Write-FujiContextLog {
    param([hashtable]$Context, [string]$Message, [string]$Level = 'info')
    if ($Context -and $Context.ContainsKey('Log') -and $Context.Log) { & $Context.Log $Message $Level }
}

# Value of one placeholder key, or $null when the key means nothing
function Get-FujiPlaceholderValue {
    param([Parameter(Mandatory)][string]$Key, [hashtable]$Context = @{})
    $now = Get-Date
    if ($Context.ContainsKey('Now') -and $Context.Now) { $now = [datetime]$Context.Now }
    $row = @{ No = 0; Data = @() }
    if ($Context.ContainsKey('Row') -and $Context.Row) { $row = $Context.Row }
    $data = @($row.Data)
    if ($Key -match '^[0-9]+$') {
        $col = [int]$Key
        if ($col -ge 1 -and $col -le $data.Count) { return [string]$data[$col - 1] }
        return ''
    }
    # An exact CSV header wins over the built-in names, so a column called "ROW" or "DAY" works
    if ($Context.ContainsKey('Header') -and $Context.Header) {
        $header = @($Context.Header)
        for ($i = 0; $i -lt $header.Count; $i++) {
            if (([string]$header[$i]).Trim() -ceq $Key) {
                if ($i -lt $data.Count) { return [string]$data[$i] }
                return ''
            }
        }
    }
    if ($Key.StartsWith('$')) {
        $name = $Key.Substring(1).Trim()
        if ($Context.ContainsKey('Vars') -and $Context.Vars -and $Context.Vars.Contains($name)) { return [string]$Context.Vars[$name] }
        Write-FujiContextLog -Context $Context -Message (Get-FujiText 'placeholder.emptyVar' $name)
        return ''
    }
    $up = $Key.ToUpperInvariant()
    $m = [regex]::Match($up, '^ROW\s*([+\-])\s*([0-9]+)$')
    if ($m.Success) {
        $delta = [int]$m.Groups[2].Value
        if ($m.Groups[1].Value -eq '-') { $delta = -$delta }
        return [string]([int]$row.No + $delta)
    }
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    switch -CaseSensitive ($up) {
        'ROW' { return [string]$row.No }
        'TODAY' { return $now.ToString('yyyy/MM/dd', $inv) }
        'TODAY_JP' { return [string]$now.Year + (Get-FujiText 'date.year') + $now.Month + (Get-FujiText 'date.month') + $now.Day + (Get-FujiText 'date.day') }
        'WAREKI' { return (Get-FujiWarekiDate -Date $now) }
        'WAREKI_YEAR' { return (Get-FujiWarekiYear -Date $now) }
        'YYYYMMDD' { return $now.ToString('yyyyMMdd', $inv) }
        'NOW' { return $now.ToString('HH:mm', $inv) }
        'TIMESTAMP' { return $now.ToString('yyyyMMdd_HHmmss', $inv) }
        'YEAR' { return [string]$now.Year }
        'MONTH' { return [string]$now.Month }
        'DAY' { return [string]$now.Day }
    }
    return $null
}

# Unsafe (optional list): collects inserted values that hold command-line characters (for RUN)
function Expand-FujiPlaceholder {
    param(
        [AllowNull()][AllowEmptyString()][string]$Text,
        [hashtable]$Context = @{},
        [System.Collections.Generic.List[string]]$Unsafe = $null
    )
    if ([string]::IsNullOrEmpty($Text)) { return '' }
    $sb = New-Object -TypeName System.Text.StringBuilder
    $last = 0
    foreach ($m in $script:FujiPlaceholder.Matches($Text)) {
        [void]$sb.Append($Text, $last, $m.Index - $last)
        $value = Get-FujiPlaceholderValue -Key $m.Groups[1].Value.Trim() -Context $Context
        if ($null -eq $value) {
            Write-FujiContextLog -Context $Context -Message (Get-FujiText 'placeholder.unknown' $m.Value) -Level 'warn'
            $value = $m.Value
        } elseif ($null -ne $Unsafe -and $script:FujiCommandUnsafe.IsMatch($value)) {
            $short = $value
            if ($short.Length -gt 20) { $short = $short.Substring(0, 20) + [char]0x2026 }
            $Unsafe.Add(('{0}={1}{2}{3}' -f $m.Value, [char]0x300C, $short, [char]0x300D))
        }
        [void]$sb.Append($value)
        $last = $m.Index + $m.Length
    }
    [void]$sb.Append($Text, $last, $Text.Length - $last)
    return $sb.ToString()
}

# ===== src/Text.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Text resources
#  Every Japanese text lives in fujikyun_ja.json (UTF-8): Windows PowerShell 5.1 reads a script
#  without a BOM in the ANSI code page, so the .ps1 files stay ASCII only.
# ---------------------------------------------------------------------------------------------

$script:FujiText = $null

# Reads a UTF-8 file strictly: bytes that are not UTF-8 (for example a file saved as Shift_JIS)
# throw instead of turning into replacement characters. A UTF-8 BOM is accepted and dropped.
function Read-FujiUtf8File {
    param([Parameter(Mandatory)][string]$Path)
    $strict = New-Object -TypeName System.Text.UTF8Encoding -ArgumentList $false, $true
    $text = [System.IO.File]::ReadAllText($Path, $strict)
    if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
    return $text
}

function Import-FujiText {
    param([Parameter(Mandatory)][string]$Path)
    $script:FujiText = Read-FujiUtf8File -Path $Path | ConvertFrom-Json
    # "Fujikyun" built from code points so this file stays ASCII
    $expected = -join ([char[]](0x3075, 0x3058, 0x30AD, 0x30E5, 0x30F3))
    if ([string]$script:FujiText.sentinel -ne $expected) {
        throw ('Text resource {0} is not the expected UTF-8 file' -f $Path)
    }
}

# Get-FujiText 'calc.badChar' 'x'  ->  the text at that dotted path, formatted with the arguments
function Get-FujiText {
    param(
        [Parameter(Mandatory)][string]$Key,
        [Parameter(ValueFromRemainingArguments)][object[]]$FormatArgs
    )
    $node = $script:FujiText
    foreach ($part in $Key.Split('.')) {
        if ($null -eq $node) { break }
        $p = $node.PSObject.Properties[$part]
        if ($null -eq $p) { $node = $null; break }
        $node = $p.Value
    }
    if ($null -eq $node) { return $Key }
    if ($node -is [System.Array]) { return , $node }
    if ($node -is [System.Management.Automation.PSCustomObject]) { return $node }
    if ($FormatArgs -and $FormatArgs.Count -gt 0) { return ([string]$node -f $FormatArgs) }
    return [string]$node
}

# ===== src/Values.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Values: numbers, dates, calculation, string operations and conditions
#  (same results as the HTA's toNumberOrNull, warekiOf, parseDateText, calcExpression, strOp,
#  evalCondition; full-width characters are written as \uXXXX so this file stays ASCII)
# ---------------------------------------------------------------------------------------------

$script:FujiInvariant = [System.Globalization.CultureInfo]::InvariantCulture
$script:FujiRegexOptions = [System.Text.RegularExpressions.RegexOptions]::CultureInvariant

function ConvertTo-FujiHalfWidthDigit {
    param([AllowNull()][AllowEmptyString()][string]$Text)
    if ($null -eq $Text) { return '' }
    return [regex]::Replace($Text, '[\uFF10-\uFF19]', { param($m) [string][char]([int][char]$m.Value - 0xFEE0) })
}

# Numbers are [decimal]: exact up to 28 digits, so long IDs and money totals never lose digits
# (the HTA's JavaScript doubles do, beyond 15 digits)
function ConvertTo-FujiNumberText {
    param([decimal]$Value)
    return $Value.ToString('0.##########', $script:FujiInvariant)
}

# "1,200" / full-width digits and commas -> number; anything else (or too long to be exact) -> $null
function ConvertTo-FujiNumber {
    param([AllowNull()][AllowEmptyString()][string]$Text)
    $t = (ConvertTo-FujiHalfWidthDigit -Text ([string]$Text).Trim()) -replace '[,\uFF0C]', ''
    if ($t -notmatch '^[+\-]?[0-9]+(\.[0-9]+)?$') { return $null }
    if (($t -replace '^[+\-]?0*|\.', '').Length -gt 28) { return $null }
    return [decimal]::Parse($t, [System.Globalization.NumberStyles]::Number, $script:FujiInvariant)
}

# ----------------------------------------------------------------- dates
# Eras from Meiji (residents' birth dates reach back to Taisho and Meiji), newest first, in the
# order of date.eras in the text resource: first day (yyyymmdd) and year offset
$script:FujiEraStarts = @(20190501, 19890108, 19261225, 19120730, 18680101)
$script:FujiEraOffsets = @(2018, 1988, 1925, 1911, 1867)

function Get-FujiWarekiYear {
    param([Parameter(Mandatory)][datetime]$Date)
    $eras = Get-FujiText 'date.eras'
    $key = $Date.Year * 10000 + $Date.Month * 100 + $Date.Day
    for ($i = 0; $i -lt $script:FujiEraStarts.Count; $i++) {
        if ($key -ge $script:FujiEraStarts[$i]) {
            $ey = $Date.Year - $script:FujiEraOffsets[$i]
            $num = [string]$ey
            if ($ey -eq 1) { $num = Get-FujiText 'date.firstYear' }
            return $eras[$i] + $num + (Get-FujiText 'date.year')
        }
    }
    return [string]$Date.Year + (Get-FujiText 'date.year')
}

function Get-FujiWarekiDate {
    param([Parameter(Mandatory)][datetime]$Date)
    return (Get-FujiWarekiYear -Date $Date) + $Date.Month + (Get-FujiText 'date.month') + $Date.Day + (Get-FujiText 'date.day')
}

function Format-FujiDate {
    param([Parameter(Mandatory)][datetime]$Date)
    return $Date.ToString('yyyy/MM/dd', $script:FujiInvariant)
}

# Reads 2026/10/01, 2026-10-1, 20261001, Reiwa 8 nen 10 gatsu 1 nichi, full-width digits; $null otherwise
function ConvertFrom-FujiDateText {
    param([AllowNull()][AllowEmptyString()][string]$Text)
    $t = ConvertTo-FujiHalfWidthDigit -Text ([string]$Text).Trim()
    $eras = Get-FujiText 'date.eras'
    $first = [regex]::Escape((Get-FujiText 'date.firstYear'))
    $nen = [regex]::Escape((Get-FujiText 'date.year'))
    $tsuki = [regex]::Escape((Get-FujiText 'date.month'))
    $hi = [regex]::Escape((Get-FujiText 'date.day'))
    $eraPattern = (@($eras) | ForEach-Object { [regex]::Escape($_) }) -join '|'
    $m = [regex]::Match($t, ('({0})([0-9]+|{1}){2}([0-9]{{1,2}}){3}([0-9]{{1,2}}){4}' -f $eraPattern, $first, $nen, $tsuki, $hi))
    try {
        if ($m.Success) {
            $base = $script:FujiEraOffsets[[array]::IndexOf([string[]]$eras, $m.Groups[1].Value)]
            $ey = 1
            if ($m.Groups[2].Value -match '^[0-9]+$') { $ey = [int]$m.Groups[2].Value }
            return (New-Object -TypeName DateTime -ArgumentList ($base + $ey), ([int]$m.Groups[3].Value), ([int]$m.Groups[4].Value))
        }
        $m = [regex]::Match($t, '^([0-9]{4})([0-9]{2})([0-9]{2})$')
        if (-not $m.Success) { $m = [regex]::Match($t, '([0-9]{4})[^0-9]+([0-9]{1,2})[^0-9]+([0-9]{1,2})') }
        if (-not $m.Success) { return $null }
        return (New-Object -TypeName DateTime -ArgumentList ([int]$m.Groups[1].Value), ([int]$m.Groups[2].Value), ([int]$m.Groups[3].Value))
    } catch [System.ArgumentOutOfRangeException] {
        return $null
    }
}

# ----------------------------------------------------------------- calculation  (+ - * / % and brackets)
function Invoke-FujiCalc {
    param([AllowNull()][AllowEmptyString()][string]$Expression)
    $s = ConvertTo-FujiHalfWidthDigit -Text ([string]$Expression)
    $s = $s -replace '[,\uFF0C]', '' -replace '\uFF0B', '+' -replace '[\uFF0D\u2212]', '-' -replace '[\uFF0A\u00D7]', '*'
    $s = $s -replace '[\uFF0F\u00F7]', '/' -replace '\uFF05', '%' -replace '\uFF08', '(' -replace '\uFF09', ')' -replace '\uFF0E', '.'
    $s = $s -replace '\s+', ''
    if ($s -eq '') { throw (Get-FujiText 'calc.empty') }
    $state = @{ S = $s; Pos = 0 }
    try {
        $result = Read-FujiCalcExpr -State $state
    } catch [System.OverflowException] {
        throw (Get-FujiText 'calc.tooBig')
    } catch [System.Management.Automation.MethodInvocationException] {
        if ($_.Exception.InnerException -is [System.OverflowException]) { throw (Get-FujiText 'calc.tooBig') }
        throw
    }
    if ($state.Pos -lt $s.Length) { throw (Get-FujiText 'calc.badChar' $s.Substring($state.Pos)) }
    return (ConvertTo-FujiNumberText -Value ([Math]::Round([decimal]$result, 10, [System.MidpointRounding]::AwayFromZero)))
}

function Get-FujiCalcPeek {
    param($State)
    if ($State.Pos -lt $State.S.Length) { return [string]$State.S[$State.Pos] }
    return ''
}

function Read-FujiCalcNumber {
    param($State)
    $m = [regex]::Match($State.S.Substring($State.Pos), '^[0-9]+(\.[0-9]+)?')
    if (-not $m.Success) {
        $rest = $State.S.Substring($State.Pos)
        if ($rest -eq '') { $rest = Get-FujiText 'calc.ended' }
        throw (Get-FujiText 'calc.badChar' $rest)
    }
    $State.Pos += $m.Length
    if (($m.Value -replace '^0*|\.', '').Length -gt 28) { throw (Get-FujiText 'calc.tooBig') }
    return [decimal]::Parse($m.Value, $script:FujiInvariant)
}

function Read-FujiCalcFactor {
    param($State)
    $c = Get-FujiCalcPeek -State $State
    if ($c -eq '+') { $State.Pos++; return (Read-FujiCalcFactor -State $State) }
    if ($c -eq '-') { $State.Pos++; return [decimal]::Negate((Read-FujiCalcFactor -State $State)) }
    if ($c -eq '(') {
        $State.Pos++
        $v = Read-FujiCalcExpr -State $State
        if ((Get-FujiCalcPeek -State $State) -ne ')') { throw (Get-FujiText 'calc.paren') }
        $State.Pos++
        return $v
    }
    return (Read-FujiCalcNumber -State $State)
}

function Read-FujiCalcTerm {
    param($State)
    $v = Read-FujiCalcFactor -State $State
    while (@('*', '/', '%') -contains (Get-FujiCalcPeek -State $State)) {
        $op = Get-FujiCalcPeek -State $State
        $State.Pos++
        $r = Read-FujiCalcFactor -State $State
        # [decimal] methods throw OverflowException (PowerShell operators could switch to double)
        if ($op -eq '*') {
            $v = [decimal]::Multiply($v, $r)
        } else {
            if ($r -eq 0) { throw (Get-FujiText 'calc.divZero') }
            # Remainder keeps the sign of the dividend, like JavaScript
            if ($op -eq '/') { $v = [decimal]::Divide($v, $r) } else { $v = [decimal]::Remainder($v, $r) }
        }
    }
    return $v
}

function Read-FujiCalcExpr {
    param($State)
    $v = Read-FujiCalcTerm -State $State
    while (@('+', '-') -contains (Get-FujiCalcPeek -State $State)) {
        $op = Get-FujiCalcPeek -State $State
        $State.Pos++
        $r = Read-FujiCalcTerm -State $State
        if ($op -eq '+') { $v = [decimal]::Add($v, $r) } else { $v = [decimal]::Subtract($v, $r) }
    }
    return $v
}

# ----------------------------------------------------------------- string operations (STR_OP)
function Invoke-FujiStringOp {
    param(
        [Parameter(Mandatory)][string]$Op,
        [AllowEmptyString()][string]$Text = '',
        [AllowEmptyString()][string]$A = '',
        [AllowEmptyString()][string]$B = ''
    )
    $s = $Text
    switch ($Op) {
        'REPLACE' {
            if ($A -eq '') { return $s }
            return $s.Replace($A, $B)
        }
        'REGEX_REPLACE' { return [regex]::Replace($s, $A, $B, $script:FujiRegexOptions) }
        'REGEX_EXTRACT' {
            $m = [regex]::Match($s, $A, $script:FujiRegexOptions)
            $g = 0
            if ($B -ne '') { $g = Get-FujiInt -Text $B -Default 0 }
            if ($m.Success -and $g -ge 0 -and $g -lt $m.Groups.Count -and $m.Groups[$g].Success) { return $m.Groups[$g].Value }
            return ''
        }
        'SUBSTR' {
            $start = [Math]::Max(1, (Get-FujiInt -Text $A -Default 1)) - 1
            if ($start -ge $s.Length) { return '' }
            if ($B -eq '') { return $s.Substring($start) }
            $n = [Math]::Min([Math]::Max(0, (Get-FujiInt -Text $B -Default 0)), $s.Length - $start)
            return $s.Substring($start, $n)
        }
        'SPLIT' {
            $sep = $A
            if ($sep -eq '') { $sep = ',' }
            $parts = $s.Split([string[]]@($sep), [System.StringSplitOptions]::None)
            $idx = Get-FujiInt -Text $B -Default 1
            if ($idx -ge 1 -and $idx -le $parts.Length) { return $parts[$idx - 1] }
            return ''
        }
        'TRIM' { return ($s -replace '^[\s\u3000]+|[\s\u3000]+$', '') }
        'ZEN2HAN' {
            $r = [regex]::Replace($s, '[\uFF01-\uFF5E]', { param($m) [string][char]([int][char]$m.Value - 0xFEE0) })
            return $r.Replace([string][char]0x3000, ' ')
        }
        'HAN2ZEN' {
            $r = [regex]::Replace($s, '[!-~]', { param($m) [string][char]([int][char]$m.Value + 0xFEE0) })
            return $r.Replace(' ', [string][char]0x3000)
        }
        'PAD' {
            $len = Get-FujiInt -Text $A -Default 0
            $fill = '0'
            if ($B -ne '') { $fill = [string]$B[0] }
            while ($s.Length -lt $len) { $s = $fill + $s }
            return $s
        }
        'WAREKI' {
            $d = ConvertFrom-FujiDateText -Text $s
            if ($null -eq $d) { throw (Get-FujiText 'strOp.badDate' $s) }
            return (Get-FujiWarekiDate -Date $d)
        }
        'DATE_ADD' {
            $d = ConvertFrom-FujiDateText -Text $s
            if ($null -eq $d) { throw (Get-FujiText 'strOp.badDate' $s) }
            return (Format-FujiDate -Date $d.AddDays((Get-FujiInt -Text $A -Default 0)))
        }
        'COMMA' {
            $n = (ConvertTo-FujiHalfWidthDigit -Text $s).Replace(',', '')
            $parts = $n.Split('.')
            $parts[0] = [regex]::Replace($parts[0], '\B(?=([0-9]{3})+(?![0-9]))', ',')
            return ($parts -join '.')
        }
        'UNCOMMA' { return ($s -replace '[,\uFF0C]', '') }
        'LENGTH' { return [string]$s.Length }
    }
    return $s
}

# parseInt-like: leading integer of the (half-width) text, or Default
function Get-FujiInt {
    param([AllowEmptyString()][string]$Text, [int]$Default = 0)
    $m = [regex]::Match((ConvertTo-FujiHalfWidthDigit -Text $Text).Trim(), '^[+\-]?[0-9]+')
    if ($m.Success) { return [int]$m.Value }
    return $Default
}

# ----------------------------------------------------------------- conditions (IF_START / LOOP_START while)
# Left / Right are already expanded. WINDOW / FILE checks go through the context so the runner (and
# the tests) decide how a window is found.
function Test-FujiCondition {
    param(
        [Parameter(Mandatory)][string]$Op,
        [AllowEmptyString()][string]$Left = '',
        [AllowEmptyString()][string]$Right = '',
        [hashtable]$Context = @{}
    )
    $ln = ConvertTo-FujiNumber -Text $Left
    $rn = ConvertTo-FujiNumber -Text $Right
    $numeric = ($null -ne $ln) -and ($null -ne $rn)
    $cmp = [string]::CompareOrdinal($Left, $Right)
    switch ($Op) {
        'EQ' { if ($numeric) { return ($ln -eq $rn) } else { return ($Left -ceq $Right) } }
        'NE' { if ($numeric) { return ($ln -ne $rn) } else { return ($Left -cne $Right) } }
        'CONTAINS' { return ($Left.IndexOf($Right, [System.StringComparison]::Ordinal) -ge 0) }
        'NOT_CONTAINS' { return ($Left.IndexOf($Right, [System.StringComparison]::Ordinal) -lt 0) }
        'EMPTY' { return ($Left.Trim() -eq '') }
        'NOT_EMPTY' { return ($Left.Trim() -ne '') }
        'GT' { if ($numeric) { return ($ln -gt $rn) } else { return ($cmp -gt 0) } }
        'GE' { if ($numeric) { return ($ln -ge $rn) } else { return ($cmp -ge 0) } }
        'LT' { if ($numeric) { return ($ln -lt $rn) } else { return ($cmp -lt 0) } }
        'LE' { if ($numeric) { return ($ln -le $rn) } else { return ($cmp -le 0) } }
        'REGEX' { return [regex]::IsMatch($Left, $Right, $script:FujiRegexOptions) }
        'FILE' { return (Test-FujiFileCondition -Path $Left -Context $Context) }
        'NO_FILE' { return -not (Test-FujiFileCondition -Path $Left -Context $Context) }
        'WINDOW' { return (Test-FujiWindowCondition -Title $Left -Context $Context) }
        'NO_WINDOW' { return -not (Test-FujiWindowCondition -Title $Left -Context $Context) }
    }
    return $false
}

function Test-FujiFileCondition {
    param([string]$Path, [hashtable]$Context)
    if ($Context.ContainsKey('FileExists')) { return [bool](& $Context.FileExists $Path) }
    return ($Path -ne '' -and (Test-Path -LiteralPath $Path -PathType Leaf))
}

function Test-FujiWindowCondition {
    param([string]$Title, [hashtable]$Context)
    if ($Context.ContainsKey('WindowExists')) { return [bool](& $Context.WindowExists $Title) }
    return $false
}

# ===== gui/Common.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Window helpers: fonts, colours, log, small dialogs (Windows Forms, Windows only)
#  Event handlers only use $script: state, $this (the control) and $_ (event arguments): a
#  handler runs after the function that attached it has returned.
# ---------------------------------------------------------------------------------------------

$script:Ui = @{}
$script:LogBuffer = New-Object -TypeName 'System.Collections.Generic.List[object]'
$script:LogLimit = 500
$script:CategoryColors = @{
    input = '#1e88e5'; wait = '#c0a000'; flow = '#fb8c00'; var = '#3949ab'
    mouse = '#00897b'; window = '#8e24aa'; group = '#795548'; note = '#43a047'
}
$script:CategoryBack = @{ group = '#f6f1ee'; note = '#f5fbf5' }
$script:LogColors = @{ info = '#ece6f0'; ok = '#a5e3a8'; warn = '#ffe082'; error = '#ff8a9a'; run = '#8fd3ff' }

$script:ColorCache = @{}
function Get-FujiColor {
    param([Parameter(Mandatory)][string]$Hex)
    if (-not $script:ColorCache.ContainsKey($Hex)) { $script:ColorCache[$Hex] = [System.Drawing.ColorTranslator]::FromHtml($Hex) }
    return $script:ColorCache[$Hex]
}

# Pixels at 96 dpi -> pixels on this screen (the process is DPI aware)
function Get-FujiScaled {
    param([double]$Pixels)
    return [int][Math]::Round($Pixels * $script:Ui.Scale)
}

function Initialize-FujiUi {
    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing
    # Real pixels everywhere (screen capture and clicks use the same coordinates as the screen)
    $native = Get-FujiNativeType
    [void]$native::SetProcessDPIAware()
    [System.Windows.Forms.Application]::EnableVisualStyles()
    try { [System.Windows.Forms.Application]::SetCompatibleTextRenderingDefault($false) } catch { $null = $_ }
    $g = [System.Drawing.Graphics]::FromHwnd([IntPtr]::Zero)
    try { $script:Ui.Scale = $g.DpiX / 96.0 } finally { $g.Dispose() }
    $family = Select-FujiFontFamily -Names @('Yu Gothic UI', 'Meiryo UI', 'MS UI Gothic') -Default 'Segoe UI'
    $script:Ui.Font = New-Object -TypeName System.Drawing.Font -ArgumentList $family, 10
    $script:Ui.BoldFont = New-Object -TypeName System.Drawing.Font -ArgumentList $script:Ui.Font, ([System.Drawing.FontStyle]::Bold)
    $script:Ui.StrikeFont = New-Object -TypeName System.Drawing.Font -ArgumentList $script:Ui.Font, ([System.Drawing.FontStyle]::Strikeout)
    $script:Ui.SmallFont = New-Object -TypeName System.Drawing.Font -ArgumentList $family, 9
    $mono = Select-FujiFontFamily -Names @('BIZ UDGothic', 'MS Gothic') -Default 'Consolas'
    $script:Ui.LogFont = New-Object -TypeName System.Drawing.Font -ArgumentList $mono, 9.5
    $script:Ui.ToolTip = New-Object -TypeName System.Windows.Forms.ToolTip
    $script:Ui.ToolTip.AutoPopDelay = 20000
}

# The first installed font of Names (asks for each one: listing every font of the PC is slow)
function Select-FujiFontFamily {
    param([string[]]$Names, [string]$Default)
    foreach ($n in $Names) {
        try {
            $f = New-Object -TypeName System.Drawing.FontFamily -ArgumentList $n
            $f.Dispose()
            return $n
        } catch {
            $null = $_
        }
    }
    return $Default
}

# Runs an event handler body; an unexpected error goes to the log instead of closing the window
function Invoke-FujiUi {
    param([Parameter(Mandatory)][scriptblock]$Action)
    try {
        & $Action
    } catch {
        # The innermost place in the script (InvocationInfo only names the outermost call)
        $where = ''
        $trace = [string]$_.ScriptStackTrace
        if ($trace) { $where = ' [' + ($trace -split "`r?`n")[0].Trim() + ']' }
        Write-FujiUiLog -Message ((Get-FujiText 'gui.unexpected' $_.Exception.Message) + $where) -Level 'error'
    }
}

# ----------------------------------------------------------------- log
function Write-FujiUiLog {
    param([string]$Message, [string]$Level = 'info')
    $line = '[' + (Get-Date -Format 'HH:mm:ss') + '] ' + $Message
    $box = $script:Ui['Log']
    # Colours need the RichTextBox's window: lines before it exists wait in the buffer
    if ($null -eq $box -or -not $box.IsHandleCreated) {
        $script:LogBuffer.Add(@($line, $Level))
        return
    }
    Add-FujiLogLine -Box $box -Line $line -Level $Level
}

function Add-FujiLogLine {
    param($Box, [string]$Line, [string]$Level)
    $color = $script:LogColors[$Level]
    if (-not $color) { $color = $script:LogColors['info'] }
    $Box.SelectionStart = $Box.TextLength
    $Box.SelectionLength = 0
    $Box.SelectionColor = Get-FujiColor $color
    if ($Level -eq 'error') { $Box.SelectionFont = $script:Ui.BoldFont } else { $Box.SelectionFont = $Box.Font }
    $Box.AppendText($Line + "`n")
    if ($Box.Lines.Length -gt $script:LogLimit + 50) {
        $Box.ReadOnly = $false
        $Box.Select(0, $Box.GetFirstCharIndexFromLine($Box.Lines.Length - $script:LogLimit))
        $Box.SelectedText = ''
        $Box.ReadOnly = $true
    }
    $Box.SelectionStart = $Box.TextLength
    $Box.ScrollToCaret()
}

# ----------------------------------------------------------------- controls
function New-FujiButton {
    param([string]$Text, [string]$Tip = '', $Tag = $null)
    $b = New-Object -TypeName System.Windows.Forms.Button
    $b.Text = $Text
    $b.AutoSize = $true
    $b.AutoSizeMode = [System.Windows.Forms.AutoSizeMode]::GrowAndShrink
    $b.Padding = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 4), (Get-FujiScaled 2), (Get-FujiScaled 4), (Get-FujiScaled 2)
    $b.Margin = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 2)
    $b.UseMnemonic = $false
    $b.Tag = $Tag
    if ($Tip) { $script:Ui.ToolTip.SetToolTip($b, $Tip) }
    return $b
}

function New-FujiLabel {
    param([string]$Text, [int]$MaxWidth = 0)
    $l = New-Object -TypeName System.Windows.Forms.Label
    $l.Text = $Text
    $l.AutoSize = $true
    $l.UseMnemonic = $false
    $l.Margin = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 3), (Get-FujiScaled 7), (Get-FujiScaled 3), (Get-FujiScaled 3)
    if ($MaxWidth -gt 0) { $l.MaximumSize = New-Object -TypeName System.Drawing.Size -ArgumentList $MaxWidth, 0 }
    return $l
}

function New-FujiTextBox {
    param([string]$Text = '', [int]$Width = 200, [switch]$Multiline)
    $t = New-Object -TypeName System.Windows.Forms.TextBox
    $t.Width = $Width
    if ($Multiline) {
        $t.Multiline = $true
        $t.AcceptsReturn = $true
        $t.ScrollBars = [System.Windows.Forms.ScrollBars]::Vertical
        $t.Height = Get-FujiScaled 90
    }
    $t.Text = $Text
    $t.Margin = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 2), (Get-FujiScaled 3), (Get-FujiScaled 2), (Get-FujiScaled 3)
    return $t
}

# Drop-down list; Values (codes) kept in Tag beside the shown labels
function New-FujiComboBox {
    param([object[]]$Items = @(), [object[]]$Values = $null, [int]$Width = 200)
    $c = New-Object -TypeName System.Windows.Forms.ComboBox
    $c.DropDownStyle = [System.Windows.Forms.ComboBoxStyle]::DropDownList
    $c.Width = $Width
    $c.Margin = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 2), (Get-FujiScaled 3), (Get-FujiScaled 2), (Get-FujiScaled 3)
    foreach ($i in $Items) { [void]$c.Items.Add([string]$i) }
    $c.Tag = $Values
    return $c
}

# One full-width column: rows that hold wrapping FlowLayoutPanels get the width to wrap in
function Add-FujiFullColumn {
    param([Parameter(Mandatory)][System.Windows.Forms.TableLayoutPanel]$Table)
    [void]$Table.ColumnStyles.Add((New-Object -TypeName System.Windows.Forms.ColumnStyle -ArgumentList ([System.Windows.Forms.SizeType]::Percent), 100))
}

# NoWrap: one line (its preferred height is then exact inside a TableLayoutPanel)
function New-FujiFlow {
    param([switch]$NoWrap)
    $f = New-Object -TypeName System.Windows.Forms.FlowLayoutPanel
    $f.AutoSize = $true
    $f.AutoSizeMode = [System.Windows.Forms.AutoSizeMode]::GrowAndShrink
    $f.WrapContents = -not $NoWrap
    $f.Margin = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList 0
    $f.Dock = [System.Windows.Forms.DockStyle]::Fill
    return $f
}

function New-FujiDialogForm {
    param([string]$Title, [int]$Width, [int]$Height)
    $f = New-Object -TypeName System.Windows.Forms.Form
    $f.Text = $Title
    $f.Font = $script:Ui.Font
    $f.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::None
    $f.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterParent
    $f.ShowInTaskbar = $false
    $f.MinimizeBox = $false
    $f.MaximizeBox = $false
    $f.ClientSize = New-Object -TypeName System.Drawing.Size -ArgumentList $Width, $Height
    $f.KeyPreview = $true
    return $f
}

# A row of buttons at the bottom of a dialog, right-aligned
function New-FujiButtonBar {
    $bar = New-Object -TypeName System.Windows.Forms.FlowLayoutPanel
    $bar.Dock = [System.Windows.Forms.DockStyle]::Bottom
    $bar.FlowDirection = [System.Windows.Forms.FlowDirection]::RightToLeft
    $bar.AutoSize = $true
    $bar.AutoSizeMode = [System.Windows.Forms.AutoSizeMode]::GrowAndShrink
    $bar.Padding = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 8)
    return $bar
}

function Get-FujiOwner {
    $f = $script:Ui['Form']
    if ($null -ne $f -and $f.Visible) { return $f }
    return $null
}

function Show-FujiDialog {
    param([Parameter(Mandatory)]$Form)
    $owner = Get-FujiOwner
    if ($null -eq $owner) { $Form.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterScreen; return $Form.ShowDialog() }
    return $Form.ShowDialog($owner)
}

# ----------------------------------------------------------------- small dialogs
function Show-FujiMessage {
    param([string]$Title, [string]$Message)
    [void](Show-FujiChoice -Title $Title -Message $Message -Buttons @((Get-FujiText 'gui.ok')))
}

# Returns the index of the pressed button, -1 when closed (Esc / x). The first button is the default.
function Show-FujiChoice {
    param([string]$Title, [string]$Message, [string[]]$Buttons)
    $width = Get-FujiScaled 520
    $f = New-FujiDialogForm -Title $Title -Width $width -Height (Get-FujiScaled 200)
    $f.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
    $f.AutoSize = $true
    $f.AutoSizeMode = [System.Windows.Forms.AutoSizeMode]::GrowAndShrink
    $text = New-FujiLabel -Text $Message -MaxWidth ($width - (Get-FujiScaled 30))
    $text.Margin = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 14)
    $layout = New-Object -TypeName System.Windows.Forms.TableLayoutPanel
    $layout.AutoSize = $true
    $layout.AutoSizeMode = [System.Windows.Forms.AutoSizeMode]::GrowAndShrink
    $layout.ColumnCount = 1
    $layout.MinimumSize = New-Object -TypeName System.Drawing.Size -ArgumentList $width, 0
    [void]$layout.Controls.Add($text)
    $bar = New-Object -TypeName System.Windows.Forms.FlowLayoutPanel
    $bar.AutoSize = $true
    $bar.FlowDirection = [System.Windows.Forms.FlowDirection]::RightToLeft
    $bar.Dock = [System.Windows.Forms.DockStyle]::Fill
    $bar.Padding = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 8)
    $script:Ui.ChoiceResult = -1
    # RightToLeft: add the last button first so they read in the given order
    for ($i = $Buttons.Count - 1; $i -ge 0; $i--) {
        $b = New-FujiButton -Text $Buttons[$i] -Tag $i
        $b.MinimumSize = New-Object -TypeName System.Drawing.Size -ArgumentList (Get-FujiScaled 90), 0
        $b.Add_Click({ $script:Ui.ChoiceResult = [int]$this.Tag; $this.FindForm().Close() })
        [void]$bar.Controls.Add($b)
        if ($i -eq 0) { $f.AcceptButton = $b }
    }
    [void]$layout.Controls.Add($bar)
    [void]$f.Controls.Add($layout)
    $f.Add_Shown({ $this.AcceptButton.Focus() })
    $f.Add_KeyDown({ if ($_.KeyCode -eq [System.Windows.Forms.Keys]::Escape) { $this.Close() } })
    [void](Show-FujiDialog -Form $f)
    $f.Dispose()
    return $script:Ui.ChoiceResult
}

# One line of text; '' when cancelled. Empty input is refused in the dialog.
function Show-FujiInput {
    param([string]$Title, [string]$Label, [string]$Default = '')
    $width = Get-FujiScaled 460
    $f = New-FujiDialogForm -Title $Title -Width $width -Height (Get-FujiScaled 170)
    $f.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::FixedDialog
    $layout = New-Object -TypeName System.Windows.Forms.TableLayoutPanel
    $layout.Dock = [System.Windows.Forms.DockStyle]::Fill
    $layout.ColumnCount = 1
    Add-FujiFullColumn -Table $layout
    $layout.Padding = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 10)
    [void]$layout.Controls.Add((New-FujiLabel -Text $Label))
    $box = New-FujiTextBox -Text $Default -Width ($width - (Get-FujiScaled 30))
    [void]$layout.Controls.Add($box)
    $err = New-FujiLabel -Text ''
    $err.ForeColor = Get-FujiColor '#c62828'
    [void]$layout.Controls.Add($err)
    $bar = New-FujiButtonBar
    $cancel = New-FujiButton -Text (Get-FujiText 'gui.cancel')
    $cancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $ok = New-FujiButton -Text (Get-FujiText 'gui.ok')
    [void]$bar.Controls.Add($cancel)
    [void]$bar.Controls.Add($ok)
    $script:Ui.InputDialog = @{ Box = $box; Error = $err; Value = '' }
    $ok.Add_Click({
            $d = $script:Ui.InputDialog
            $v = $d.Box.Text.Trim()
            if ($v -eq '') { $d.Error.Text = Get-FujiText 'gui.emptyInput'; return }
            $d.Value = $v
            $this.FindForm().DialogResult = [System.Windows.Forms.DialogResult]::OK
        })
    $f.AcceptButton = $ok
    $f.CancelButton = $cancel
    [void]$f.Controls.Add($layout)
    [void]$f.Controls.Add($bar)
    $f.Add_Shown({ $script:Ui.InputDialog.Box.SelectAll(); $script:Ui.InputDialog.Box.Focus() })
    $result = Show-FujiDialog -Form $f
    $f.Dispose()
    if ($result -ne [System.Windows.Forms.DialogResult]::OK) { return '' }
    return $script:Ui.InputDialog.Value
}

function Open-FujiFolder {
    param([Parameter(Mandatory)][string]$Path)
    Start-Process -FilePath (Join-Path $env:SystemRoot 'explorer.exe') -ArgumentList ('/select,"' + $Path + '"')
}

# ===== gui/MainForm.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Main window: macro and CSV toolbars, command palette, step list, log
#  The step list is an owner-drawn ListBox; $script:Rows maps its rows to step indexes
#  (blocks inside a collapsed block have no row). Every change: editor function, then Update-FujiAll.
# ---------------------------------------------------------------------------------------------

$script:Rows = New-Object -TypeName 'System.Collections.Generic.List[object]'
$script:Refreshing = $false
$script:DropRow = -1
$script:DragRow = -1
$script:DragFrom = $null
$script:ToggleClicked = $false
$script:TextFlags = $null   # set by Show-FujiMainForm (needs Windows Forms loaded)

function Show-FujiMainForm {
    $script:TextFlags = [System.Windows.Forms.TextFormatFlags]'NoPrefix, SingleLine, VerticalCenter, EndEllipsis'
    $form = New-Object -TypeName System.Windows.Forms.Form
    $form.Text = Get-FujiText 'gui.title'
    $form.Font = $script:Ui.Font
    $form.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::None
    $area = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
    $form.Size = New-Object -TypeName System.Drawing.Size -ArgumentList ([Math]::Min((Get-FujiScaled 1280), $area.Width)), ([Math]::Min((Get-FujiScaled 900), $area.Height))
    $form.MinimumSize = New-Object -TypeName System.Drawing.Size -ArgumentList (Get-FujiScaled 640), (Get-FujiScaled 480)
    $form.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterScreen
    $form.KeyPreview = $true
    $form.BackColor = Get-FujiColor '#fdf7fb'
    $script:Ui.Form = $form

    # Docking, not a TableLayoutPanel: a docked FlowLayoutPanel gets its height from wrapping at the
    # real window width (an auto-sized table row measured the toolbars far too tall)
    # No layout while the controls are added (each addition would lay out the window again)
    $form.SuspendLayout()
    $bottom = New-FujiBottomPanel
    $bottom.Dock = [System.Windows.Forms.DockStyle]::Bottom
    $bottom.Height = Get-FujiScaled 210
    [void]$form.Controls.Add((New-FujiStepListPanel))
    [void]$form.Controls.Add($bottom)
    $toolbars = @(New-FujiTopPanel)
    # The last added docks first: add from the bottom row up so the first row is at the top
    for ($i = $toolbars.Count - 1; $i -ge 0; $i--) { [void]$form.Controls.Add($toolbars[$i]) }
    $form.ResumeLayout($true)
    $script:StartMarks.Add($script:StartWatch.Elapsed.TotalSeconds)

    $form.Add_KeyDown({ $e = $_; Invoke-FujiUi { Invoke-FujiShortcut -KeyEvent $e } })
    $form.Add_FormClosing({ $e = $_; Invoke-FujiUi { Confirm-FujiClose -CloseEvent $e } })
    $form.Add_Shown({
            Invoke-FujiUi {
                foreach ($entry in $script:LogBuffer) { Add-FujiLogLine -Box $script:Ui.Log -Line $entry[0] -Level $entry[1] }
                $script:LogBuffer.Clear()
                Write-FujiUiLog -Message (Get-FujiText 'gui.welcome') -Level 'ok'
                Write-FujiStartupTime
                if ($script:Ed.Notices.Count -gt 0) { Show-FujiMessage -Title (Get-FujiText 'gui.noticeTitle') -Message ($script:Ed.Notices -join "`r`n`r`n") }
                $script:Ui.List.Focus()
            }
        })
    Update-FujiAll
    $script:StartMarks.Add($script:StartWatch.Elapsed.TotalSeconds)
    [System.Windows.Forms.Application]::Run($form)
}

# How long the start took: from the PowerShell process start (includes reading this script),
# and the parts measured inside the script (StartMarks: texts and commands, window setup, data)
function Write-FujiStartupTime {
    $total = ((Get-Date) - (Get-Process -Id $PID).StartTime).TotalSeconds
    $m = $script:StartMarks
    $w = $script:StartWatch.Elapsed.TotalSeconds
    if ($m.Count -lt 5) { return }
    $f = '0.0'
    $before = $total - $w
    Write-FujiUiLog -Message (Get-FujiText 'gui.startupTime' $total.ToString($f) $before.ToString($f) $m[0].ToString($f) ($m[1] - $m[0]).ToString($f) ($m[2] - $m[1]).ToString($f) ($m[3] - $m[2]).ToString($f) ($m[4] - $m[3]).ToString($f) ($w - $m[4]).ToString($f))
}

# ----------------------------------------------------------------- top panel
function New-FujiRowLabel {
    param([string]$Text)
    $l = New-FujiLabel -Text $Text
    $l.Font = $script:Ui.BoldFont
    $l.ForeColor = Get-FujiColor '#ad1457'
    return $l
}

function New-FujiTopPanel {
    $top = New-Object -TypeName 'System.Collections.Generic.List[object]'

    # save
    $row = New-FujiFlow
    $row.SuspendLayout()
    $save = New-FujiButton -Text (Get-FujiText 'gui.save') -Tip (Get-FujiText 'gui.saveTip')
    $save.Font = $script:Ui.BoldFont
    $save.Add_Click({ Invoke-FujiUi { Save-FujiUi } })
    $state = New-FujiLabel -Text ''
    $state.Font = $script:Ui.BoldFont
    $script:Ui.SaveState = $state
    [void]$row.Controls.Add($save)
    [void]$row.Controls.Add($state)
    $top.Add((Set-FujiToolbarRow $row))

    # macro
    $row = New-FujiFlow
    $row.SuspendLayout()
    [void]$row.Controls.Add((New-FujiRowLabel (Get-FujiText 'gui.macro')))
    $combo = New-FujiComboBox -Width (Get-FujiScaled 320)
    $combo.Add_SelectedIndexChanged({ Invoke-FujiUi { Select-FujiMacroUi } })
    $script:Ui.MacroCombo = $combo
    [void]$row.Controls.Add($combo)
    foreach ($b in @(
            @('gui.newMacro', '', { Invoke-FujiUi { Add-FujiMacroUi } }),
            @('gui.rename', '', { Invoke-FujiUi { Rename-FujiMacroUi } }),
            @('gui.duplicateMacro', '', { Invoke-FujiUi { Copy-FujiCurrentMacro -Editor $script:Ed; Update-FujiAll } }),
            @('gui.deleteMacro', '', { Invoke-FujiUi { Remove-FujiMacroUi } }),
            @('gui.template', 'gui.templateTip', { Invoke-FujiUi { New-FujiMacroFromTemplateUi } }),
            @('gui.export', 'gui.exportTip', { Invoke-FujiUi { Export-FujiMacroUi } }),
            @('gui.import', 'gui.importTip', { Invoke-FujiUi { Import-FujiMacroUi } })
        )) {
        $tip = ''
        if ($b[1]) { $tip = Get-FujiText $b[1] }
        $btn = New-FujiButton -Text (Get-FujiText $b[0]) -Tip $tip
        $btn.Add_Click($b[2])
        [void]$row.Controls.Add($btn)
    }
    [void]$row.Controls.Add((New-FujiRowLabel (Get-FujiText 'gui.target')))
    $target = New-FujiTextBox -Width (Get-FujiScaled 220)
    $script:Ui.ToolTip.SetToolTip($target, (Get-FujiText 'gui.targetTip'))
    $target.Add_Leave({ Invoke-FujiUi { Set-FujiTargetWindowUi } })
    $target.Add_KeyDown({
            $e = $_
            if ($e.KeyCode -eq [System.Windows.Forms.Keys]::Enter) { $e.SuppressKeyPress = $true; Invoke-FujiUi { Set-FujiTargetWindowUi } }
        })
    $script:Ui.Target = $target
    [void]$row.Controls.Add($target)
    $wl = New-FujiButton -Text (Get-FujiText 'gui.windowList') -Tip (Get-FujiText 'gui.windowListTip')
    $wl.Add_Click({ Invoke-FujiUi { Select-FujiWindowUi } })
    [void]$row.Controls.Add($wl)
    $top.Add((Set-FujiToolbarRow $row))

    # CSV
    $row = New-FujiFlow
    $row.SuspendLayout()
    [void]$row.Controls.Add((New-FujiRowLabel (Get-FujiText 'gui.csv')))
    $path = New-FujiTextBox -Width (Get-FujiScaled 380)
    $path.Add_KeyDown({
            $e = $_
            if ($e.KeyCode -eq [System.Windows.Forms.Keys]::Enter) { $e.SuppressKeyPress = $true; Invoke-FujiUi { Import-FujiCsvUi } }
        })
    $script:Ui.CsvPath = $path
    [void]$row.Controls.Add($path)
    $browse = New-FujiButton -Text (Get-FujiText 'gui.csvBrowse')
    $browse.Add_Click({ Invoke-FujiUi { Select-FujiCsvFileUi } })
    $load = New-FujiButton -Text (Get-FujiText 'gui.csvLoad')
    $load.Add_Click({ Invoke-FujiUi { Import-FujiCsvUi } })
    $header = New-Object -TypeName System.Windows.Forms.CheckBox
    $header.Text = Get-FujiText 'gui.csvHeader'
    $header.AutoSize = $true
    $header.Checked = $true
    $header.Margin = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 6), (Get-FujiScaled 6), (Get-FujiScaled 2), 0
    $header.Add_CheckedChanged({ Invoke-FujiUi { Set-FujiCsvHeaderUi } })
    $script:Ui.CsvHeader = $header
    $encLabels = @()
    $encValues = @()
    foreach ($p in (Get-FujiText 'gui.csvEncodings')) { $encValues += [string]$p[0]; $encLabels += [string]$p[1] }
    $enc = New-FujiComboBox -Items $encLabels -Values $encValues -Width (Get-FujiScaled 170)
    $enc.SelectedIndex = 0
    $enc.Add_SelectedIndexChanged({ Invoke-FujiUi { if (-not $script:Refreshing -and $script:Ed.Csv.Path) { Import-FujiCsvUi } } })
    $script:Ui.CsvEncoding = $enc
    $info = New-FujiLabel -Text (Get-FujiText 'editor.csv.none')
    $info.ForeColor = Get-FujiColor '#5e5368'
    $script:Ui.CsvInfo = $info
    foreach ($c in @($browse, $load, $header, $enc, $info)) { [void]$row.Controls.Add($c) }
    $top.Add((Set-FujiToolbarRow $row))

    # palette
    $row = New-FujiFlow
    $row.SuspendLayout()
    [void]$row.Controls.Add((New-FujiRowLabel (Get-FujiText 'gui.add')))
    foreach ($group in $script:FujiCommands['palette']) {
        $gl = New-FujiLabel -Text ([string]$group['label'])
        $gl.ForeColor = Get-FujiColor '#7a6f84'
        $gl.Font = $script:Ui.SmallFont
        $gl.Margin = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 8), (Get-FujiScaled 8), 0, 0
        [void]$row.Controls.Add($gl)
        $color = Get-FujiColor $script:CategoryColors[[string]$group['category']]
        foreach ($cmd in $group['cmds']) {
            $def = Get-FujiCommandDef ([string]$cmd)
            $btn = New-FujiButton -Text ([string]$def['icon'] + ' ' + [string]$def['title']) -Tip ([string]$cmd + ': ' + [string]$def['help']) -Tag ([string]$cmd)
            $btn.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
            $btn.FlatAppearance.BorderColor = $color
            $btn.BackColor = Get-FujiTint -Color $color -Amount 0.88
            $btn.Add_Click({ $cmdName = [string]$this.Tag; Invoke-FujiUi { Add-FujiStepUi -Cmd $cmdName } })
            [void]$row.Controls.Add($btn)
        }
    }
    $top.Add((Set-FujiToolbarRow $row))

    # edit
    $row = New-FujiFlow
    $row.SuspendLayout()
    [void]$row.Controls.Add((New-FujiRowLabel (Get-FujiText 'gui.edit')))
    $undo = New-FujiButton -Text (Get-FujiText 'gui.undo') -Tip (Get-FujiText 'gui.undoTip')
    $undo.Add_Click({ Invoke-FujiUi { if (Undo-FujiEditorChange -Editor $script:Ed) { Update-FujiAll } } })
    $redo = New-FujiButton -Text (Get-FujiText 'gui.redo') -Tip (Get-FujiText 'gui.redoTip')
    $redo.Add_Click({ Invoke-FujiUi { if (Redo-FujiEditorChange -Editor $script:Ed) { Update-FujiAll } } })
    $script:Ui.Undo = $undo
    $script:Ui.Redo = $redo
    $hist = New-FujiComboBox -Width (Get-FujiScaled 300)
    $script:Ui.ToolTip.SetToolTip($hist, (Get-FujiText 'gui.historyTip'))
    $hist.Add_SelectedIndexChanged({ Invoke-FujiUi { Restore-FujiHistoryUi } })
    $script:Ui.History = $hist
    foreach ($c in @($undo, $redo, $hist)) { [void]$row.Controls.Add($c) }
    foreach ($b in @(
            @('gui.moveUp', 'gui.moveUpTip', { Invoke-FujiUi { Move-FujiStepUi -Direction -1 } }),
            @('gui.moveDown', 'gui.moveDownTip', { Invoke-FujiUi { Move-FujiStepUi -Direction 1 } }),
            @('gui.editStep', 'gui.editStepTip', { Invoke-FujiUi { Edit-FujiStepUi } }),
            @('gui.deleteStep', 'gui.deleteStepTip', { Invoke-FujiUi { Remove-FujiStepUi } }),
            @('gui.duplicate', 'gui.duplicateTip', { Invoke-FujiUi { if (Copy-FujiEditorStep -Editor $script:Ed) { Update-FujiAll } } }),
            @('gui.disable', 'gui.disableTip', { Invoke-FujiUi { if (Switch-FujiEditorStepDisabled -Editor $script:Ed) { Update-FujiAll } } }),
            @('gui.expandAll', '', { Invoke-FujiUi { Set-FujiAllCollapsed -Editor $script:Ed -Collapsed $false; Update-FujiStepList } }),
            @('gui.collapseAll', '', { Invoke-FujiUi { Set-FujiAllCollapsed -Editor $script:Ed -Collapsed $true; Update-FujiStepList; Update-FujiInsertHint } })
        )) {
        $tip = ''
        if ($b[1]) { $tip = Get-FujiText $b[1] }
        $btn = New-FujiButton -Text (Get-FujiText $b[0]) -Tip $tip
        $btn.Add_Click($b[2])
        [void]$row.Controls.Add($btn)
    }
    $hint = New-FujiLabel -Text ''
    $hint.ForeColor = Get-FujiColor '#5e5368'
    $script:Ui.InsertHint = $hint
    [void]$row.Controls.Add($hint)
    $top.Add((Set-FujiToolbarRow $row))
    return $top.ToArray()
}

function Set-FujiToolbarRow {
    param([Parameter(Mandatory)]$Row)
    $Row.ResumeLayout($false)
    $Row.Dock = [System.Windows.Forms.DockStyle]::Top
    $Row.Padding = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 6), (Get-FujiScaled 1), (Get-FujiScaled 6), (Get-FujiScaled 1)
    return $Row
}

# Color mixed with white (Amount 0 = the colour, 1 = white)
function Get-FujiTint {
    param([System.Drawing.Color]$Color, [double]$Amount)
    $r = [int]($Color.R + (255 - $Color.R) * $Amount)
    $g = [int]($Color.G + (255 - $Color.G) * $Amount)
    $b = [int]($Color.B + (255 - $Color.B) * $Amount)
    return [System.Drawing.Color]::FromArgb($r, $g, $b)
}

# ----------------------------------------------------------------- step list
function New-FujiStepListPanel {
    $listHost = New-Object -TypeName System.Windows.Forms.Panel
    $listHost.Dock = [System.Windows.Forms.DockStyle]::Fill
    $listHost.Padding = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 6), (Get-FujiScaled 2), (Get-FujiScaled 6), (Get-FujiScaled 2)
    $lb = New-Object -TypeName System.Windows.Forms.ListBox
    $lb.Dock = [System.Windows.Forms.DockStyle]::Fill
    $lb.DrawMode = [System.Windows.Forms.DrawMode]::OwnerDrawFixed
    $lb.ItemHeight = [Math]::Min(255, [System.Windows.Forms.TextRenderer]::MeasureText('Ag', $script:Ui.Font).Height + (Get-FujiScaled 12))
    $lb.IntegralHeight = $false
    $lb.AllowDrop = $true
    $lb.BackColor = [System.Drawing.Color]::White
    $lb.Add_DrawItem({ $e = $_; Invoke-FujiUi { Show-FujiStepRow -DrawEvent $e } })
    $lb.Add_SelectedIndexChanged({ Invoke-FujiUi { Select-FujiStepUi } })
    $lb.Add_MouseDown({ $e = $_; Invoke-FujiUi { Start-FujiListMouse -MouseEvent $e } })
    $lb.Add_MouseMove({ $e = $_; Invoke-FujiUi { Move-FujiListMouse -MouseEvent $e } })
    $lb.Add_MouseUp({ $script:DragFrom = $null })
    # a double click on the fold mark only folds and unfolds
    $lb.Add_DoubleClick({ Invoke-FujiUi { if (-not $script:ToggleClicked) { Edit-FujiStepUi } } })
    $lb.Add_DragOver({ $e = $_; Invoke-FujiUi { Update-FujiDropTarget -DragEvent $e } })
    $lb.Add_DragDrop({ Invoke-FujiUi { Complete-FujiDrop } })
    $lb.Add_DragLeave({ $script:DropRow = -1; $script:Ui.List.Invalidate() })
    $lb.Add_Resize({ $this.Invalidate() })
    $script:Ui.List = $lb
    $empty = New-FujiLabel -Text ((Get-FujiText 'gui.empty') + "`r`n" + (Get-FujiText 'gui.emptyHint'))
    $empty.Dock = [System.Windows.Forms.DockStyle]::Top
    $empty.AutoSize = $false
    $empty.Height = Get-FujiScaled 70
    $empty.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
    $empty.ForeColor = Get-FujiColor '#7a6f84'
    $empty.BackColor = [System.Drawing.Color]::White
    $empty.Visible = $false
    $script:Ui.Empty = $empty
    [void]$listHost.Controls.Add($lb)
    [void]$listHost.Controls.Add($empty)
    return $listHost
}

# Left edge of a row's contents and its fold mark (same numbers for drawing and clicking)
function Get-FujiRowLayout {
    param([int]$Depth, [int]$Left)
    $x = $Left + (Get-FujiScaled 4) + $Depth * (Get-FujiScaled 22)
    return @{ Bar = $x; Toggle = $x + (Get-FujiScaled 8); ToggleEnd = $x + (Get-FujiScaled 26) }
}

function Write-FujiRowText {
    param($Graphics, [string]$Text, $Font, [System.Drawing.Color]$Color, [int]$X, [System.Drawing.Rectangle]$Bounds, [System.Drawing.Color]$Back = [System.Drawing.Color]::Empty)
    if ($X -ge $Bounds.Right -or $Text -eq '') { return $X }
    $size = [System.Windows.Forms.TextRenderer]::MeasureText($Graphics, $Text, $Font, $Bounds.Size, $script:TextFlags)
    $pad = 0
    if (-not $Back.IsEmpty) { $pad = Get-FujiScaled 4 }
    $w = [Math]::Min($size.Width + $pad * 2, $Bounds.Right - $X)
    $rect = New-Object -TypeName System.Drawing.Rectangle -ArgumentList $X, $Bounds.Y, $w, $Bounds.Height
    if (-not $Back.IsEmpty) {
        $h = $size.Height + (Get-FujiScaled 2)
        $tag = New-Object -TypeName System.Drawing.Rectangle -ArgumentList $X, ($Bounds.Y + [int](($Bounds.Height - $h) / 2)), $w, $h
        $brush = New-Object -TypeName System.Drawing.SolidBrush -ArgumentList $Back
        try { $Graphics.FillRectangle($brush, $tag) } finally { $brush.Dispose() }
        $rect = $tag
    }
    $flags = $script:TextFlags
    if ($pad -gt 0) { $flags = $flags -bor [System.Windows.Forms.TextFormatFlags]::HorizontalCenter }
    [System.Windows.Forms.TextRenderer]::DrawText($Graphics, $Text, $Font, $rect, $Color, $flags)
    return ($X + $w + (Get-FujiScaled 6))
}

function Show-FujiStepRow {
    param([Parameter(Mandatory)]$DrawEvent)
    $e = $DrawEvent
    $i = $e.Index
    if ($i -lt 0 -or $i -ge $script:Rows.Count) { return }
    $row = $script:Rows[$i]
    $steps = Get-FujiCurrentStepList $script:Ed
    if ($row.Index -ge $steps.Count) { return }
    $step = $steps[$row.Index]
    $def = Get-FujiCommandDef $step.cmd
    if ($null -eq $def) { $def = Get-FujiCommandDef 'COMMENT' }
    $cat = [string]$def['category']
    $catColor = Get-FujiColor $script:CategoryColors[$cat]
    $g = $e.Graphics
    $b = $e.Bounds
    $selected = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
    $disabled = $step.Contains('disabled') -and $step['disabled']
    $collapsed = $step.Contains('collapsed') -and $step['collapsed']
    $back = [System.Drawing.Color]::White
    if ($script:CategoryBack.ContainsKey($cat)) { $back = Get-FujiColor $script:CategoryBack[$cat] }
    if ($selected) { $back = Get-FujiColor '#dcecfd' }
    $brush = New-Object -TypeName System.Drawing.SolidBrush -ArgumentList $back
    try { $g.FillRectangle($brush, $b) } finally { $brush.Dispose() }
    if ($selected) {
        $pen = New-Object -TypeName System.Drawing.Pen -ArgumentList (Get-FujiColor '#2196f3'), 1
        try { $g.DrawRectangle($pen, $b.X, $b.Y, $b.Width - 1, $b.Height - 1) } finally { $pen.Dispose() }
    }
    $lay = Get-FujiRowLayout -Depth $row.Depth -Left $b.X
    $brush = New-Object -TypeName System.Drawing.SolidBrush -ArgumentList $catColor
    try { $g.FillRectangle($brush, $lay.Bar, $b.Y + 2, (Get-FujiScaled 4), $b.Height - 4) } finally { $brush.Dispose() }
    $grey = Get-FujiColor '#8a7f94'
    if (Test-FujiBlockStart $step.cmd) {
        $glyph = [string][char]0x25BC
        if ($collapsed) { $glyph = [string][char]0x25B6 }
        [void](Write-FujiRowText -Graphics $g -Text $glyph -Font $script:Ui.SmallFont -Color $grey -X $lay.Toggle -Bounds $b)
    }
    $x = $lay.ToggleEnd
    $no = New-Object -TypeName System.Drawing.Rectangle -ArgumentList $x, $b.Y, (Get-FujiScaled 36), $b.Height
    [System.Windows.Forms.TextRenderer]::DrawText($g, [string]($row.Index + 1), $script:Ui.SmallFont, $no, $grey, ($script:TextFlags -bor [System.Windows.Forms.TextFormatFlags]::Right))
    $x += Get-FujiScaled 44
    $badgeColor = $catColor
    if ($disabled) { $badgeColor = Get-FujiColor '#9e9e9e' }
    $x = Write-FujiRowText -Graphics $g -Text ([string]$def['icon'] + ' ' + $step.cmd) -Font $script:Ui.SmallFont -Color ([System.Drawing.Color]::White) -X $x -Bounds $b -Back $badgeColor
    $font = $script:Ui.Font
    $color = Get-FujiColor '#2b2430'
    if ($disabled) {
        $x = Write-FujiRowText -Graphics $g -Text (Get-FujiText 'gui.off') -Font $script:Ui.SmallFont -Color ([System.Drawing.Color]::White) -X $x -Bounds $b -Back (Get-FujiColor '#757575')
        $font = $script:Ui.StrikeFont
        $color = Get-FujiColor '#9e9e9e'
    }
    $label = [string]$step.label
    if (-not $label) { $label = Get-FujiStepLabel -Cmd $step.cmd -Value $step.val }
    $more = ''
    if ($collapsed) { $more = Get-FujiText 'gui.collapsedCount' $row.HiddenCount }
    if ($step.cmd -eq 'COMMENT') {
        $c = Get-FujiColor '#2e7d32'
        if ($disabled) { $c = $color }
        [void](Write-FujiRowText -Graphics $g -Text ((Get-FujiText 'gui.commentPrefix') + (Format-FujiShort $step.val 120)) -Font $font -Color $c -X $x -Bounds $b)
    } elseif ($step.cmd -eq 'GROUP_START') {
        $bold = $script:Ui.BoldFont
        if ($disabled) { $bold = $font }
        $x = Write-FujiRowText -Graphics $g -Text ([string]$def['icon'] + ' ' + $step.val) -Font $bold -Color $color -X $x -Bounds $b
        $when = ''
        if ($step.Contains('when')) { if ($step['when'] -eq 'first') { $when = Get-FujiText 'gui.whenFirst' } elseif ($step['when'] -eq 'last') { $when = Get-FujiText 'gui.whenLast' } }
        if ($when) { $x = Write-FujiRowText -Graphics $g -Text $when -Font $script:Ui.SmallFont -Color ([System.Drawing.Color]::White) -X $x -Bounds $b -Back (Get-FujiColor '#7e57c2') }
        [void](Write-FujiRowText -Graphics $g -Text $more -Font $script:Ui.SmallFont -Color $grey -X $x -Bounds $b)
    } elseif (Test-FujiBlockEnd $step.cmd) {
        [void](Write-FujiRowText -Graphics $g -Text ((Get-FujiText 'gui.blockEndPrefix') + [string]$def['title']) -Font $font -Color (Get-FujiColor '#8d6e63') -X $x -Bounds $b)
    } elseif (Test-FujiBlockMiddle $step.cmd) {
        [void](Write-FujiRowText -Graphics $g -Text ([string]$def['icon'] + ' ' + [string]$def['title']) -Font $script:Ui.BoldFont -Color $color -X $x -Bounds $b)
    } elseif ((Test-FujiBlockStart $step.cmd) -or ($def.Contains('hideVal') -and $def['hideVal'])) {
        $x = Write-FujiRowText -Graphics $g -Text $label -Font $font -Color $color -X $x -Bounds $b
        [void](Write-FujiRowText -Graphics $g -Text $more -Font $script:Ui.SmallFont -Color $grey -X $x -Bounds $b)
    } else {
        $x = Write-FujiRowText -Graphics $g -Text $label -Font $font -Color $color -X $x -Bounds $b
        [void](Write-FujiRowText -Graphics $g -Text (Format-FujiShort $step.val 60) -Font $script:Ui.SmallFont -Color $grey -X ($x + (Get-FujiScaled 6)) -Bounds $b)
    }
    # where a dragged step would land
    if ($script:DropRow -ge 0) {
        $y = -1
        if ($script:DropRow -eq $i) { $y = $b.Top + 1 }
        elseif ($script:DropRow -eq $script:Rows.Count -and $i -eq $script:Rows.Count - 1) { $y = $b.Bottom - 2 }
        if ($y -ge 0) {
            $pen = New-Object -TypeName System.Drawing.Pen -ArgumentList (Get-FujiColor '#e91e63'), (Get-FujiScaled 3)
            try { $g.DrawLine($pen, $b.Left, $y, $b.Right, $y) } finally { $pen.Dispose() }
        }
    }
}

function Select-FujiStepUi {
    if ($script:Refreshing) { return }
    $i = $script:Ui.List.SelectedIndex
    if ($i -ge 0 -and $i -lt $script:Rows.Count) { $script:Ed.Selected = $script:Rows[$i].Index } else { $script:Ed.Selected = -1 }
    Update-FujiInsertHint
}

function Start-FujiListMouse {
    param([Parameter(Mandatory)]$MouseEvent)
    $lb = $script:Ui.List
    $script:DragFrom = $null
    $script:ToggleClicked = $false
    $i = $lb.IndexFromPoint($MouseEvent.Location)
    if ($i -lt 0 -or $i -ge $script:Rows.Count) {
        $lb.ClearSelected()
        $script:Ed.Selected = -1
        Update-FujiInsertHint
        return
    }
    if ($MouseEvent.Button -ne [System.Windows.Forms.MouseButtons]::Left) { return }
    $row = $script:Rows[$i]
    $steps = Get-FujiCurrentStepList $script:Ed
    $lay = Get-FujiRowLayout -Depth $row.Depth -Left $lb.GetItemRectangle($i).X
    if ((Test-FujiBlockStart $steps[$row.Index].cmd) -and $MouseEvent.X -ge $lay.Toggle - (Get-FujiScaled 4) -and $MouseEvent.X -lt $lay.ToggleEnd) {
        $script:ToggleClicked = $true
        Switch-FujiBlockCollapsed -Editor $script:Ed -Index $row.Index
        Update-FujiStepList
        Update-FujiInsertHint
        return
    }
    $script:DragFrom = @{ Row = $i; X = $MouseEvent.X; Y = $MouseEvent.Y }
}

function Move-FujiListMouse {
    param([Parameter(Mandatory)]$MouseEvent)
    $from = $script:DragFrom
    if ($null -eq $from -or $MouseEvent.Button -ne [System.Windows.Forms.MouseButtons]::Left) { return }
    $drag = [System.Windows.Forms.SystemInformation]::DragSize
    if ([Math]::Abs($MouseEvent.X - $from.X) -lt $drag.Width -and [Math]::Abs($MouseEvent.Y - $from.Y) -lt $drag.Height) { return }
    $script:DragFrom = $null
    $script:DragRow = $from.Row
    try {
        [void]$script:Ui.List.DoDragDrop('fujikyun-step', [System.Windows.Forms.DragDropEffects]::Move)
    } finally {
        $script:DragRow = -1
        if ($script:DropRow -ge 0) { $script:DropRow = -1; $script:Ui.List.Invalidate() }
    }
}

function Update-FujiDropTarget {
    param([Parameter(Mandatory)]$DragEvent)
    if ($script:DragRow -lt 0) { $DragEvent.Effect = [System.Windows.Forms.DragDropEffects]::None; return }
    $lb = $script:Ui.List
    $pt = $lb.PointToClient((New-Object -TypeName System.Drawing.Point -ArgumentList $DragEvent.X, $DragEvent.Y))
    # scroll near the edges
    $edge = $lb.ItemHeight
    if ($pt.Y -lt $edge -and $lb.TopIndex -gt 0) { $lb.TopIndex-- }
    elseif ($pt.Y -gt $lb.ClientSize.Height - $edge -and $lb.TopIndex -lt $lb.Items.Count - 1) { $lb.TopIndex++ }
    $i = $lb.IndexFromPoint($pt)
    if ($i -lt 0 -or $i -ge $script:Rows.Count) {
        $target = $script:Rows.Count
    } else {
        $r = $lb.GetItemRectangle($i)
        $target = $i
        if ($pt.Y -gt $r.Top + $r.Height / 2) { $target = $i + 1 }
    }
    if ($target -ne $script:DropRow) {
        $script:DropRow = $target
        $lb.Invalidate()
    }
    $DragEvent.Effect = [System.Windows.Forms.DragDropEffects]::Move
}

function Complete-FujiDrop {
    $target = $script:DropRow
    $fromRow = $script:DragRow
    $script:DropRow = -1
    if ($fromRow -lt 0 -or $target -lt 0) { $script:Ui.List.Invalidate(); return }
    $steps = Get-FujiCurrentStepList $script:Ed
    $range = Get-FujiBlockRange -Steps $steps -Index $script:Rows[$fromRow].Index
    $insertAt = $steps.Count
    if ($target -lt $script:Rows.Count) { $insertAt = $script:Rows[$target].Index }
    [void](Move-FujiEditorRange -Editor $script:Ed -From $range.From -To $range.To -InsertAt $insertAt -DescriptionKey 'move')
    Update-FujiAll
}

# ----------------------------------------------------------------- bottom panel
function New-FujiBottomPanel {
    $panel = New-Object -TypeName System.Windows.Forms.TableLayoutPanel
    $panel.Dock = [System.Windows.Forms.DockStyle]::Fill
    $panel.ColumnCount = 1
    Add-FujiFullColumn -Table $panel
    $panel.RowCount = 2
    [void]$panel.RowStyles.Add((New-Object -TypeName System.Windows.Forms.RowStyle -ArgumentList ([System.Windows.Forms.SizeType]::AutoSize)))
    [void]$panel.RowStyles.Add((New-Object -TypeName System.Windows.Forms.RowStyle -ArgumentList ([System.Windows.Forms.SizeType]::Percent), 100))
    $panel.Padding = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 6), 0, (Get-FujiScaled 6), (Get-FujiScaled 6)
    $row = New-FujiFlow -NoWrap
    $run = New-FujiButton -Text (Get-FujiText 'gui.run')
    $run.Font = $script:Ui.BoldFont
    $run.Add_Click({ Write-FujiUiLog -Message (Get-FujiText 'gui.runNotYet') -Level 'warn' })
    [void]$row.Controls.Add($run)
    $panel.Controls.Add($row, 0, 0)
    $log = New-Object -TypeName System.Windows.Forms.RichTextBox
    $log.Dock = [System.Windows.Forms.DockStyle]::Fill
    $log.ReadOnly = $true
    $log.BackColor = Get-FujiColor '#2d2733'
    $log.ForeColor = Get-FujiColor '#ece6f0'
    $log.Font = $script:Ui.LogFont
    $log.BorderStyle = [System.Windows.Forms.BorderStyle]::None
    $log.DetectUrls = $false
    $log.HideSelection = $false
    $script:Ui.Log = $log
    $panel.Controls.Add($log, 0, 1)
    return $panel
}

# ----------------------------------------------------------------- refresh
function Update-FujiAll {
    Update-FujiMacroSelect
    Update-FujiStepList
    Update-FujiHistoryUi
    Update-FujiSaveState
    Update-FujiInsertHint
}

function Update-FujiMacroSelect {
    $script:Refreshing = $true
    try {
        $c = $script:Ui.MacroCombo
        $c.BeginUpdate()
        $c.Items.Clear()
        for ($i = 0; $i -lt $script:Ed.Data.macros.Count; $i++) {
            $m = $script:Ed.Data.macros[$i]
            [void]$c.Items.Add((Get-FujiText 'gui.macroItem' ($i + 1) $m.name $m.steps.Count))
        }
        $c.EndUpdate()
        $c.SelectedIndex = $script:Ed.MacroIndex
        $m = Get-FujiCurrentMacro $script:Ed
        $script:Ui.Target.Text = [string]$m.targetWindow
    } finally {
        $script:Refreshing = $false
    }
}

function Update-FujiStepList {
    $script:Refreshing = $true
    try {
        $lb = $script:Ui.List
        $script:Rows = Get-FujiStepRow -Editor $script:Ed
        $top = $lb.TopIndex
        $lb.BeginUpdate()
        $lb.Items.Clear()
        $sel = -1
        for ($i = 0; $i -lt $script:Rows.Count; $i++) {
            [void]$lb.Items.Add($i)
            if ($script:Rows[$i].Index -eq $script:Ed.Selected) { $sel = $i }
        }
        if ($lb.Items.Count -gt 0) { $lb.TopIndex = [Math]::Min($top, $lb.Items.Count - 1) }
        $lb.SelectedIndex = $sel
        $lb.EndUpdate()
        if ($sel -ge 0) {
            $visible = [Math]::Max(1, [int]($lb.ClientSize.Height / $lb.ItemHeight))
            if ($sel -lt $lb.TopIndex -or $sel -ge $lb.TopIndex + $visible) { $lb.TopIndex = [Math]::Max(0, $sel - [int]($visible / 3)) }
        }
        $script:Ui.Empty.Visible = ($script:Rows.Count -eq 0)
    } finally {
        $script:Refreshing = $false
    }
}

function Update-FujiHistoryUi {
    $script:Refreshing = $true
    try {
        $c = $script:Ui.History
        $h = $script:Ed.History
        $c.BeginUpdate()
        $c.Items.Clear()
        $positions = @()
        for ($i = $h.Count - 1; $i -ge 0; $i--) {
            $mark = Get-FujiText 'gui.historyNoMark'
            if ($i -eq $script:Ed.HistoryPos) { $mark = Get-FujiText 'gui.historyMark' }
            [void]$c.Items.Add((Get-FujiText 'gui.historyItem' $mark ($i + 1) $h[$i].Time $h[$i].Desc))
            $positions += $i
        }
        $c.Tag = $positions
        $c.EndUpdate()
        $c.SelectedIndex = [Array]::IndexOf([object[]]$positions, [object]$script:Ed.HistoryPos)
        $script:Ui.Undo.Enabled = $script:Ed.HistoryPos -gt 0
        $script:Ui.Redo.Enabled = $script:Ed.HistoryPos -lt $h.Count - 1
    } finally {
        $script:Refreshing = $false
    }
}

function Update-FujiSaveState {
    $l = $script:Ui.SaveState
    if ($script:Ed.Dirty) {
        $l.Text = Get-FujiText 'gui.dirtyState'
        $l.ForeColor = Get-FujiColor '#c62828'
    } else {
        $l.Text = Get-FujiText 'gui.savedState'
        $l.ForeColor = Get-FujiColor '#2e7d32'
    }
}

function Update-FujiInsertHint {
    $steps = Get-FujiCurrentStepList $script:Ed
    if ($script:Ed.Selected -ge 0 -and $script:Ed.Selected -lt $steps.Count) {
        $script:Ui.InsertHint.Text = Get-FujiText 'gui.insertAfter' (Get-FujiInsertionIndex $script:Ed)
    } else {
        $script:Ui.InsertHint.Text = Get-FujiText 'gui.insertEnd'
    }
}

function Update-FujiCsvInfo {
    $script:Ui.CsvInfo.Text = Get-FujiCsvInfoText -Editor $script:Ed
    $script:Ui.ToolTip.SetToolTip($script:Ui.CsvInfo, [string]$script:Ed.Csv.Path)
}

# ----------------------------------------------------------------- macros
function Select-FujiMacroUi {
    if ($script:Refreshing) { return }
    $script:Ed.MacroIndex = $script:Ui.MacroCombo.SelectedIndex
    $script:Ed.Selected = -1
    Update-FujiAll
    if ($script:Ui.List.Items.Count -gt 0) { $script:Ui.List.TopIndex = 0 }
}

function Add-FujiMacroUi {
    $name = Show-FujiInput -Title (Get-FujiText 'gui.newMacroTitle') -Label (Get-FujiText 'gui.macroNameLabel') -Default (Get-FujiText 'editor.newMacro')
    if (-not $name) { return }
    Add-FujiMacro -Editor $script:Ed -Name $name
    Update-FujiAll
}

function Rename-FujiMacroUi {
    $m = Get-FujiCurrentMacro $script:Ed
    $name = Show-FujiInput -Title (Get-FujiText 'gui.renameTitle') -Label (Get-FujiText 'gui.renameLabel') -Default $m.name
    if (-not $name) { return }
    Rename-FujiMacro -Editor $script:Ed -Name $name
    Update-FujiAll
}

function Remove-FujiMacroUi {
    $m = Get-FujiCurrentMacro $script:Ed
    $answer = Show-FujiChoice -Title (Get-FujiText 'gui.deleteMacroTitle') -Message (Get-FujiText 'gui.deleteMacroText' $m.name $m.steps.Count) -Buttons @((Get-FujiText 'gui.deleteMacroButton'), (Get-FujiText 'gui.cancel'))
    if ($answer -ne 0) { return }
    Remove-FujiCurrentMacro -Editor $script:Ed
    Update-FujiAll
}

function Set-FujiTargetWindowUi {
    if ($script:Refreshing) { return }
    $m = Get-FujiCurrentMacro $script:Ed
    if ($null -eq $m -or $m.targetWindow -ceq $script:Ui.Target.Text.Trim()) { return }
    Set-FujiTargetWindow -Editor $script:Ed -Title $script:Ui.Target.Text
    Update-FujiAll
}

function Export-FujiMacroUi {
    try {
        $path = Export-FujiCurrentMacro -Editor $script:Ed
    } catch {
        Write-FujiUiLog -Message (Get-FujiText 'editor.exportFailed' $_.Exception.Message) -Level 'error'
        return
    }
    $answer = Show-FujiChoice -Title (Get-FujiText 'gui.exportDoneTitle') -Message (Get-FujiText 'gui.exportDone' $path) -Buttons @((Get-FujiText 'gui.openFolder'), (Get-FujiText 'gui.close'))
    if ($answer -eq 0) { Open-FujiFolder -Path $path }
}

function Import-FujiMacroUi {
    $dlg = New-Object -TypeName System.Windows.Forms.OpenFileDialog
    $dlg.Filter = Get-FujiText 'gui.jsonFilter'
    $folder = Get-FujiEditorPath $script:Ed $script:FujiFileNames.Export
    if (Test-Path -LiteralPath $folder) { $dlg.InitialDirectory = $folder } else { $dlg.InitialDirectory = $script:Ed.Directory }
    try {
        if ($dlg.ShowDialog($script:Ui.Form) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $message = Import-FujiMacroFile -Editor $script:Ed -Path $dlg.FileName
    } finally {
        $dlg.Dispose()
    }
    if ($message) { Show-FujiMessage -Title (Get-FujiText 'gui.importFailedTitle') -Message $message }
    Update-FujiAll
}

function Select-FujiWindowUi {
    $titles = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowTitle } | ForEach-Object { $_.MainWindowTitle } | Sort-Object -Unique)
    $f = New-FujiDialogForm -Title (Get-FujiText 'gui.windowListTitle') -Width (Get-FujiScaled 600) -Height (Get-FujiScaled 440)
    $help = New-FujiLabel -Text (Get-FujiText 'gui.windowListHelp') -MaxWidth (Get-FujiScaled 580)
    $help.Dock = [System.Windows.Forms.DockStyle]::Top
    $lb = New-Object -TypeName System.Windows.Forms.ListBox
    $lb.Dock = [System.Windows.Forms.DockStyle]::Fill
    $lb.IntegralHeight = $false
    foreach ($t in $titles) { [void]$lb.Items.Add($t) }
    $bar = New-FujiButtonBar
    $cancel = New-FujiButton -Text (Get-FujiText 'gui.cancel')
    $cancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $ok = New-FujiButton -Text (Get-FujiText 'gui.ok')
    $ok.DialogResult = [System.Windows.Forms.DialogResult]::OK
    if ($titles.Count -eq 0) { [void]$lb.Items.Add((Get-FujiText 'gui.windowNone')); $lb.Enabled = $false; $ok.Enabled = $false } else { $lb.SelectedIndex = 0 }
    $lb.Add_DoubleClick({ if ($this.SelectedIndex -ge 0) { $this.FindForm().DialogResult = [System.Windows.Forms.DialogResult]::OK } })
    [void]$bar.Controls.Add($cancel)
    [void]$bar.Controls.Add($ok)
    $f.AcceptButton = $ok
    $f.CancelButton = $cancel
    [void]$f.Controls.Add($lb)
    [void]$f.Controls.Add($help)
    [void]$f.Controls.Add($bar)
    $result = Show-FujiDialog -Form $f
    $title = ''
    if ($result -eq [System.Windows.Forms.DialogResult]::OK -and $titles.Count -gt 0 -and $lb.SelectedIndex -ge 0) { $title = [string]$lb.SelectedItem }
    $f.Dispose()
    if (-not $title) { return }
    $script:Ui.Target.Text = $title
    Set-FujiTargetWindowUi
}

# ----------------------------------------------------------------- templates
# Read on first use (a 200 KB file: reading it at start made the window slow to open)
$script:Templates = $null
function Get-FujiTemplateData {
    if ($null -eq $script:Templates) {
        $script:Templates = ConvertFrom-FujiJson -Json (Read-FujiUtf8File -Path (Join-Path $script:Ed.Directory 'fujikyun_templates.json'))
    }
    return $script:Templates
}

function Show-FujiTemplateGallery {
    $all = (Get-FujiTemplateData)['templates']
    $f = New-FujiDialogForm -Title (Get-FujiText 'gui.templateTitle' $all.Count) -Width (Get-FujiScaled 1000) -Height (Get-FujiScaled 640)
    $f.MinimumSize = New-Object -TypeName System.Drawing.Size -ArgumentList (Get-FujiScaled 600), (Get-FujiScaled 400)
    $topRow = New-FujiFlow
    $topRow.Dock = [System.Windows.Forms.DockStyle]::Top
    $topRow.Padding = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 6)
    [void]$topRow.Controls.Add((New-FujiLabel -Text (Get-FujiText 'gui.templateHelp') -MaxWidth (Get-FujiScaled 960)))
    [void]$topRow.SetFlowBreak($topRow.Controls[0], $true)
    [void]$topRow.Controls.Add((New-FujiLabel -Text (Get-FujiText 'gui.category')))
    $cats = New-Object -TypeName 'System.Collections.Generic.List[object]'
    $cats.Add((Get-FujiText 'gui.allCategories'))
    foreach ($c in (Get-FujiTemplateData)['categories']) { $cats.Add([string]$c) }
    $combo = New-FujiComboBox -Items $cats.ToArray() -Values $cats.ToArray() -Width (Get-FujiScaled 280)
    [void]$topRow.Controls.Add($combo)
    $split = New-Object -TypeName System.Windows.Forms.SplitContainer
    # A new SplitContainer is 150 px wide: size it before placing the splitter
    $split.Size = $f.ClientSize
    $split.SplitterDistance = Get-FujiScaled 420
    $split.Dock = [System.Windows.Forms.DockStyle]::Fill
    $lb = New-Object -TypeName System.Windows.Forms.ListBox
    $lb.Dock = [System.Windows.Forms.DockStyle]::Fill
    $lb.IntegralHeight = $false
    $details = New-Object -TypeName System.Windows.Forms.TextBox
    $details.Dock = [System.Windows.Forms.DockStyle]::Fill
    $details.Multiline = $true
    $details.ReadOnly = $true
    $details.ScrollBars = [System.Windows.Forms.ScrollBars]::Vertical
    $details.BackColor = [System.Drawing.Color]::White
    [void]$split.Panel1.Controls.Add($lb)
    [void]$split.Panel2.Controls.Add($details)
    $bar = New-FujiButtonBar
    $close = New-FujiButton -Text (Get-FujiText 'gui.close')
    $close.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $create = New-FujiButton -Text (Get-FujiText 'gui.create')
    $create.Font = $script:Ui.BoldFont
    $create.DialogResult = [System.Windows.Forms.DialogResult]::OK
    [void]$bar.Controls.Add($close)
    [void]$bar.Controls.Add($create)
    $f.AcceptButton = $create
    $f.CancelButton = $close
    [void]$f.Controls.Add($split)
    [void]$f.Controls.Add($topRow)
    [void]$f.Controls.Add($bar)
    $script:Ui.Gallery = @{ List = $lb; Details = $details; Shown = (New-Object -TypeName 'System.Collections.Generic.List[object]'); Combo = $combo }
    $combo.Add_SelectedIndexChanged({ Invoke-FujiUi { Update-FujiTemplateList } })
    $lb.Add_SelectedIndexChanged({ Invoke-FujiUi { Update-FujiTemplateDetail } })
    $lb.Add_DoubleClick({ if ($this.SelectedIndex -ge 0) { $this.FindForm().DialogResult = [System.Windows.Forms.DialogResult]::OK } })
    $combo.SelectedIndex = 0
    $result = Show-FujiDialog -Form $f
    $chosen = $null
    if ($result -eq [System.Windows.Forms.DialogResult]::OK -and $lb.SelectedIndex -ge 0) { $chosen = $script:Ui.Gallery.Shown[$lb.SelectedIndex] }
    $f.Dispose()
    $script:Ui.Gallery = $null
    return $chosen
}

function Update-FujiTemplateList {
    $gal = $script:Ui.Gallery
    $cat = ''
    if ($gal.Combo.SelectedIndex -gt 0) { $cat = [string]$gal.Combo.SelectedItem }
    $gal.Shown.Clear()
    $gal.List.BeginUpdate()
    $gal.List.Items.Clear()
    foreach ($t in (Get-FujiTemplateData)['templates']) {
        if ($cat -and $t['category'] -ne $cat) { continue }
        $gal.Shown.Add($t)
        [void]$gal.List.Items.Add((Get-FujiText 'gui.templateItem' (Get-FujiText ('gui.levels.' + $t['level'])) $t['name']))
    }
    $gal.List.EndUpdate()
    if ($gal.List.Items.Count -gt 0) { $gal.List.SelectedIndex = 0 } else { $gal.Details.Text = '' }
}

function Update-FujiTemplateDetail {
    $gal = $script:Ui.Gallery
    $i = $gal.List.SelectedIndex
    if ($i -lt 0) { $gal.Details.Text = ''; return }
    $t = $gal.Shown[$i]
    $target = [string]$t['targetWindow']
    if (-not $target) { $target = Get-FujiText 'gui.tplNoTarget' }
    $level = Get-FujiText ('gui.levels.' + $t['level'])
    $prepare = Join-FujiTextList -Items $t['prepare'] -Separator (Get-FujiText 'gui.tplJoin')
    $customize = Join-FujiTextList -Items $t['customize'] -Separator (Get-FujiText 'gui.tplLines')
    $steps = $t['steps']
    $lines = New-Object -TypeName 'System.Collections.Generic.List[string]'
    $lines.Add((Get-FujiText 'gui.templateItem' $level $t['name']))
    $lines.Add('')
    $lines.Add([string]$t['summary'])
    $lines.Add('')
    $lines.Add((Get-FujiText 'gui.tplUseCase' $t['useCase']))
    $lines.Add('')
    $lines.Add((Get-FujiText 'gui.tplPrepare' $prepare))
    $lines.Add('')
    $lines.Add((Get-FujiText 'gui.tplCustomize' $customize))
    $lines.Add('')
    $lines.Add((Get-FujiText 'gui.tplMeta' $target $t['csvFile'] $steps.Count))
    $gal.Details.Text = [string]::Join("`r`n", $lines.ToArray())
}

# Items of a list from a JSON file joined into one text. A plain loop on purpose: "@(...)" around
# such a list failed on Windows PowerShell 5.1 with "argument types do not match"
function Join-FujiTextList {
    param($Items, [string]$Separator)
    $parts = New-Object -TypeName 'System.Collections.Generic.List[string]'
    foreach ($x in $Items) { $parts.Add([string]$x) }
    return [string]::Join($Separator, $parts.ToArray())
}

function New-FujiMacroFromTemplateUi {
    $tpl = Show-FujiTemplateGallery
    if ($null -eq $tpl) { return }
    $name = New-FujiMacroFromTemplate -Editor $script:Ed -Template $tpl
    Update-FujiAll
    try {
        $csvPath = Write-FujiTemplateCsv -Editor $script:Ed -Template $tpl
        if ($csvPath) {
            $script:Refreshing = $true
            try {
                $script:Ui.CsvPath.Text = $csvPath
                $script:Ui.CsvHeader.Checked = $true
                $script:Ui.CsvEncoding.SelectedIndex = 0
            } finally {
                $script:Refreshing = $false
            }
            Import-FujiCsvUi
            Write-FujiUiLog -Message (Get-FujiText 'editor.templateCsvOptions')
        }
    } catch {
        Write-FujiUiLog -Message (Get-FujiText 'editor.templateCsvFailed' $_.Exception.Message) -Level 'warn'
    }
    $lines = Get-FujiText 'gui.tplLines'
    Show-FujiMessage -Title (Get-FujiText 'gui.templateDoneTitle') -Message (Get-FujiText 'editor.templateDone' $name (Join-FujiTextList -Items $tpl['prepare'] -Separator $lines) (Join-FujiTextList -Items $tpl['customize'] -Separator $lines))
}

# ----------------------------------------------------------------- CSV
function Select-FujiCsvFileUi {
    $dlg = New-Object -TypeName System.Windows.Forms.OpenFileDialog
    $dlg.Filter = Get-FujiText 'gui.csvFilter'
    $current = $script:Ui.CsvPath.Text.Trim().Trim('"')
    if ($current -and (Test-Path -LiteralPath $current -PathType Leaf)) { $dlg.InitialDirectory = Split-Path -Path $current -Parent } else { $dlg.InitialDirectory = $script:Ed.Directory }
    try {
        if ($dlg.ShowDialog($script:Ui.Form) -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $script:Ui.CsvPath.Text = $dlg.FileName
    } finally {
        $dlg.Dispose()
    }
    Import-FujiCsvUi
}

function Import-FujiCsvUi {
    $enc = [string]([object[]]$script:Ui.CsvEncoding.Tag)[$script:Ui.CsvEncoding.SelectedIndex]
    $res = Import-FujiEditorCsv -Editor $script:Ed -Path $script:Ui.CsvPath.Text -Encoding $enc -HasHeader $script:Ui.CsvHeader.Checked
    if ($res.HeaderForced) {
        $script:Refreshing = $true
        try { $script:Ui.CsvHeader.Checked = $true } finally { $script:Refreshing = $false }
    }
    Update-FujiCsvInfo
}

function Set-FujiCsvHeaderUi {
    if ($script:Refreshing -or @($script:Ed.Csv.Records).Count -eq 0) { return }
    Set-FujiCsvHeader -Editor $script:Ed -HasHeader $script:Ui.CsvHeader.Checked
    Write-FujiUiLog -Message (Get-FujiText 'editor.csv.headerToggled' (@($script:Ed.Csv.Rows).Count))
    Update-FujiCsvInfo
}

# ----------------------------------------------------------------- steps
function Add-FujiStepUi {
    param([Parameter(Mandatory)][string]$Cmd)
    $step = Show-FujiStepDialog -Cmd $Cmd
    if ($null -eq $step) { return }
    [void](Add-FujiEditorStep -Editor $script:Ed -Step $step)
    Update-FujiAll
}

function Edit-FujiStepUi {
    $steps = Get-FujiCurrentStepList $script:Ed
    $i = $script:Ed.Selected
    if ($i -lt 0 -or $i -ge $steps.Count) { return }
    $step = $steps[$i]
    $def = Get-FujiCommandDef $step.cmd
    if ($def['format'] -eq 'none') {
        $text = Get-FujiText 'gui.markerText'
        if ((Test-FujiBlockEnd $step.cmd) -or (Test-FujiBlockMiddle $step.cmd)) { $text += Get-FujiText 'gui.markerChild' }
        Show-FujiMessage -Title ([string]$def['icon'] + ' ' + [string]$def['title']) -Message $text
        return
    }
    $updated = Show-FujiStepDialog -Cmd $step.cmd -Step $step
    if ($null -eq $updated) { return }
    Set-FujiEditorStep -Editor $script:Ed -Index $i -Updated $updated
    Update-FujiAll
}

function Remove-FujiStepUi {
    $i = $script:Ed.Selected
    if ($i -lt 0 -or $i -ge (Get-FujiCurrentStepList $script:Ed).Count) { return }
    $block = Get-FujiEditorBlock -Editor $script:Ed -Index $i
    if ($null -eq $block) {
        Remove-FujiEditorStep -Editor $script:Ed -Index $i -Mode 'Step'
    } else {
        $answer = Show-FujiChoice -Title (Get-FujiText 'gui.deleteBlockTitle' $block.Kind) -Message (Get-FujiText 'gui.deleteBlockText' $block.Kind $block.Name) -Buttons @((Get-FujiText 'gui.deleteAll'), (Get-FujiText 'gui.unwrap'), (Get-FujiText 'gui.cancel'))
        if ($answer -eq 0) { Remove-FujiEditorStep -Editor $script:Ed -Index $i -Mode 'All' }
        elseif ($answer -eq 1) { Remove-FujiEditorStep -Editor $script:Ed -Index $i -Mode 'Frame' }
        else { return }
    }
    Update-FujiAll
}

function Move-FujiStepUi {
    param([int]$Direction)
    if (Move-FujiEditorStep -Editor $script:Ed -Direction $Direction) { Update-FujiAll }
}

function Restore-FujiHistoryUi {
    if ($script:Refreshing) { return }
    $c = $script:Ui.History
    if ($c.SelectedIndex -lt 0) { return }
    $pos = [int]([object[]]$c.Tag)[$c.SelectedIndex]
    if (Restore-FujiHistory -Editor $script:Ed -Position $pos) { Update-FujiAll }
}

# ----------------------------------------------------------------- save, close, keys
function Save-FujiUi {
    if ($script:Ed.SaveBlockReason) {
        $answer = Show-FujiChoice -Title (Get-FujiText 'gui.saveConfirmTitle') -Message (Get-FujiText 'gui.saveConfirm' $script:Ed.SaveBlockReason) -Buttons @((Get-FujiText 'gui.cancel'), (Get-FujiText 'gui.overwrite'))
        if ($answer -ne 1) { return }
        $script:Ed.SaveBlockReason = ''
    }
    $err = Save-FujiEditorData -Editor $script:Ed
    if ($err) { Show-FujiMessage -Title (Get-FujiText 'gui.saveErrorTitle') -Message (Get-FujiText 'gui.saveError' $err) }
    Update-FujiSaveState
}

function Confirm-FujiClose {
    param([Parameter(Mandatory)]$CloseEvent)
    if (-not $script:Ed.Dirty) { return }
    $answer = Show-FujiChoice -Title (Get-FujiText 'gui.closeDirtyTitle') -Message (Get-FujiText 'gui.closeDirty') -Buttons @((Get-FujiText 'gui.yes'), (Get-FujiText 'gui.no'))
    if ($answer -ne 0) { $CloseEvent.Cancel = $true }
}

function Invoke-FujiShortcut {
    param([Parameter(Mandatory)]$KeyEvent)
    $k = $KeyEvent.KeyCode
    $keys = [System.Windows.Forms.Keys]
    if ($KeyEvent.Control -and $k -eq $keys::S) {
        $KeyEvent.SuppressKeyPress = $true
        Save-FujiUi
        return
    }
    $active = $script:Ui.Form.ActiveControl
    if ($active -is [System.Windows.Forms.TextBoxBase] -or $active -is [System.Windows.Forms.ComboBox]) { return }
    $handled = $true
    if ($KeyEvent.Control -and $k -eq $keys::Z) { if (Undo-FujiEditorChange -Editor $script:Ed) { Update-FujiAll } }
    elseif ($KeyEvent.Control -and $k -eq $keys::Y) { if (Redo-FujiEditorChange -Editor $script:Ed) { Update-FujiAll } }
    elseif ($KeyEvent.Control -and $k -eq $keys::D) { if (Copy-FujiEditorStep -Editor $script:Ed) { Update-FujiAll } }
    elseif ($KeyEvent.Control -and ($k -eq $keys::OemQuestion -or $k -eq $keys::Divide)) { if (Switch-FujiEditorStepDisabled -Editor $script:Ed) { Update-FujiAll } }
    elseif ($KeyEvent.Alt -and $k -eq $keys::Up) { Move-FujiStepUi -Direction -1 }
    elseif ($KeyEvent.Alt -and $k -eq $keys::Down) { Move-FujiStepUi -Direction 1 }
    elseif ($k -eq $keys::Delete -and $script:Ed.Selected -ge 0) { Remove-FujiStepUi }
    elseif ($k -eq $keys::Enter -and $script:Ed.Selected -ge 0 -and $active -isnot [System.Windows.Forms.ButtonBase]) { Edit-FujiStepUi }
    elseif ($k -eq $keys::Escape) {
        $script:Ui.List.ClearSelected()
        $script:Ed.Selected = -1
        Update-FujiInsertHint
    } else { $handled = $false }
    if ($handled) { $KeyEvent.SuppressKeyPress = $true; $KeyEvent.Handled = $true }
}

# ===== gui/StepDialog.ps1 =====
# ---------------------------------------------------------------------------------------------
#  Step editor dialog, built from the command's fields in fujikyun_commands.json
#  Field types: text, textarea, select, keypreset, csvcol, imgpath, capture, rectcapture,
#  macroselect; "placeholders" adds the insert-a-placeholder list, "hint" a note below.
# ---------------------------------------------------------------------------------------------

$script:StepDlg = $null
$script:EmSetCueBanner = 0x1501

# Returns the new step (ordered dictionary) or $null when cancelled
function Show-FujiStepDialog {
    param([Parameter(Mandatory)][string]$Cmd, $Step = $null)
    $def = Get-FujiCommandDef $Cmd
    $lookup = Get-FujiMacroNameLookup $script:Ed
    $state = Get-FujiStepEditState -Cmd $Cmd -Step $Step -MacroNameOf $lookup
    $titleKey = 'gui.addTitle'
    if ($null -ne $Step) { $titleKey = 'gui.editTitle' }
    $width = Get-FujiScaled 720
    $content = $width - (Get-FujiScaled 60)
    $form = New-FujiDialogForm -Title (Get-FujiText $titleKey $def['icon'] $def['title'] $Cmd) -Width $width -Height (Get-FujiScaled 400)
    $form.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::Sizable
    $form.MinimumSize = New-Object -TypeName System.Drawing.Size -ArgumentList ([int]($width / 2)), (Get-FujiScaled 220)

    $panel = New-Object -TypeName System.Windows.Forms.TableLayoutPanel
    $panel.Dock = [System.Windows.Forms.DockStyle]::Fill
    $panel.ColumnCount = 1
    Add-FujiFullColumn -Table $panel
    $panel.AutoScroll = $true
    $panel.Padding = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 12)

    $script:StepDlg = @{
        Form = $form; Cmd = $Cmd; Inputs = @{}; Status = @{}; Cues = (New-Object -TypeName 'System.Collections.Generic.List[object]')
        Timer = $null; Mode = ''; Remaining = 0; First = $null; Result = $null
        Preview = $null; ImgW = $null; ImgH = $null; Error = $null; Label = $null
    }

    $help = New-FujiLabel -Text ([string]$def['help']) -MaxWidth $content
    $help.ForeColor = Get-FujiColor '#5e5368'
    [void]$panel.Controls.Add($help)
    foreach ($field in $def['fields']) {
        Add-FujiStepField -Panel $panel -Field $field -Value ([string]$state.Values[[string]$field['id']]) -Width $content
    }
    [void]$panel.Controls.Add((New-FujiFieldLabel -Text (Get-FujiText 'gui.labelField') -Width $content))
    $labelBox = New-FujiTextBox -Text $state.CustomLabel -Width $content
    $script:StepDlg.Label = $labelBox
    [void]$panel.Controls.Add($labelBox)
    $err = New-FujiLabel -Text '' -MaxWidth $content
    $err.ForeColor = Get-FujiColor '#c62828'
    $err.Font = $script:Ui.BoldFont
    $script:StepDlg.Error = $err
    [void]$panel.Controls.Add($err)

    $bar = New-FujiButtonBar
    $cancel = New-FujiButton -Text (Get-FujiText 'gui.cancel')
    $cancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $okText = Get-FujiText 'gui.addButton'
    if ($null -ne $Step) { $okText = Get-FujiText 'gui.update' }
    $ok = New-FujiButton -Text $okText
    $ok.Font = $script:Ui.BoldFont
    $ok.Add_Click({ Invoke-FujiUi { Complete-FujiStepDialog } })
    [void]$bar.Controls.Add($cancel)
    [void]$bar.Controls.Add($ok)
    $form.AcceptButton = $ok
    $form.CancelButton = $cancel
    [void]$form.Controls.Add($panel)
    [void]$form.Controls.Add($bar)

    # Height that fits the fields, within the screen
    $pref = $panel.GetPreferredSize((New-Object -TypeName System.Drawing.Size -ArgumentList $width, 0))
    $area = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
    $height = [Math]::Min([int]($area.Height * 0.85), $pref.Height + $bar.GetPreferredSize([System.Drawing.Size]::Empty).Height + (Get-FujiScaled 20))
    $form.ClientSize = New-Object -TypeName System.Drawing.Size -ArgumentList $width, ([Math]::Max($height, (Get-FujiScaled 200)))

    $form.Add_Shown({
            # Grey example text inside empty one-line boxes (EM_SETCUEBANNER)
            $native = Get-FujiNativeType
            foreach ($cue in $script:StepDlg.Cues) {
                [void]$native::SendMessage($cue[0].Handle, $script:EmSetCueBanner, [IntPtr]1, [string]$cue[1])
            }
            Update-FujiImagePreview -Opening
        })
    $form.Add_FormClosed({ if ($script:StepDlg.Timer) { $script:StepDlg.Timer.Stop(); $script:StepDlg.Timer.Dispose() } })
    [void](Show-FujiDialog -Form $form)
    $result = $script:StepDlg.Result
    if ($script:StepDlg.Preview -and $script:StepDlg.Preview.Image) { $script:StepDlg.Preview.Image.Dispose() }
    $form.Dispose()
    $script:StepDlg = $null
    return $result
}

function New-FujiFieldLabel {
    param([string]$Text, [int]$Width)
    $l = New-FujiLabel -Text $Text -MaxWidth $Width
    $l.Font = $script:Ui.BoldFont
    $l.Margin = New-Object -TypeName System.Windows.Forms.Padding -ArgumentList (Get-FujiScaled 3), (Get-FujiScaled 10), (Get-FujiScaled 3), 0
    return $l
}

function New-FujiHintLabel {
    param([string]$Text, [int]$Width)
    $l = New-FujiLabel -Text $Text -MaxWidth $Width
    $l.ForeColor = Get-FujiColor '#7a6f84'
    $l.Font = $script:Ui.SmallFont
    return $l
}

# A drop-down that fills Target: Mode 'set' replaces the text, 'append' adds to it
function New-FujiHelperCombo {
    param([string]$First, [object[]]$Choices, [object[]]$Values, $Target, [string]$Mode, [int]$Width)
    # Lists, not "@(..) + @(..)": that form failed on Windows PowerShell 5.1 ("argument types do not match")
    $items = New-Object -TypeName 'System.Collections.Generic.List[object]'
    $items.Add($First)
    foreach ($x in $Choices) { $items.Add($x) }
    $vals = New-Object -TypeName 'System.Collections.Generic.List[object]'
    $vals.Add('')
    foreach ($x in $Values) { $vals.Add($x) }
    $c = New-FujiComboBox -Items $items.ToArray() -Width $Width
    $c.Tag = @{ Values = $vals.ToArray(); Target = $Target; Mode = $Mode }
    $c.SelectedIndex = 0
    $c.Add_SelectedIndexChanged({
            $box = $this
            if ($box.SelectedIndex -le 0) { return }
            $info = $box.Tag
            $v = [string]$info.Values[$box.SelectedIndex]
            if ($info.Mode -eq 'append') {
                $info.Target.Text += $v
                $info.Target.Focus()
                $info.Target.SelectionStart = $info.Target.TextLength
            } else {
                $info.Target.Text = $v
            }
            $box.SelectedIndex = 0
        })
    return $c
}

function Set-FujiComboValue {
    param($Combo, [string]$Value)
    $i = [Array]::IndexOf([object[]]$Combo.Tag, $Value)
    if ($i -lt 0) { $i = 0 }
    if ($Combo.Items.Count -gt 0) { $Combo.SelectedIndex = $i }
}

function Get-FujiInputValue {
    param($Control)
    if ($Control -is [System.Windows.Forms.ComboBox]) {
        if ($Control.SelectedIndex -lt 0) { return '' }
        return [string]([object[]]$Control.Tag)[$Control.SelectedIndex]
    }
    return [string]$Control.Text
}

function Add-FujiStepField {
    param($Panel, [System.Collections.IDictionary]$Field, [string]$Value, [int]$Width)
    $d = $script:StepDlg
    $id = [string]$Field['id']
    $type = [string]$Field['type']
    [void]$Panel.Controls.Add((New-FujiFieldLabel -Text ([string]$Field['label']) -Width $Width))
    $row = New-FujiFlow -NoWrap
    $inputControl = $null
    switch ($type) {
        'textarea' {
            $inputControl = New-FujiTextBox -Text $Value -Width $Width -Multiline
            [void]$row.Controls.Add($inputControl)
        }
        'select' {
            $labels = @()
            $values = @()
            foreach ($o in $Field['options']) { $values += [string]$o[0]; $labels += [string]$o[1] }
            $inputControl = New-FujiComboBox -Items $labels -Values $values -Width ([Math]::Min($Width, (Get-FujiScaled 460)))
            Set-FujiComboValue -Combo $inputControl -Value $Value
            [void]$row.Controls.Add($inputControl)
        }
        'keypreset' {
            $inputControl = New-FujiTextBox -Text $Value -Width (Get-FujiScaled 260)
            $choices = @()
            $keys = @()
            foreach ($p in $script:FujiCommands['keyPresets']) { $keys += [string]$p[0]; $choices += ([string]$p[0] + '  ' + [string]$p[1]) }
            [void]$row.Controls.Add($inputControl)
            [void]$row.Controls.Add((New-FujiHelperCombo -First (Get-FujiText 'gui.presetKeys') -Choices $choices -Values $keys -Target $inputControl -Mode 'set' -Width (Get-FujiScaled 300)))
        }
        'csvcol' {
            $inputControl = New-FujiTextBox -Text $Value -Width (Get-FujiScaled 120)
            [void]$row.Controls.Add($inputControl)
            $cols = Get-FujiCsvMaxColumn $script:Ed
            if ($cols -gt 0) {
                $choices = @()
                $nums = @()
                $first = @()
                if (@($script:Ed.Csv.Rows).Count -gt 0) { $first = @($script:Ed.Csv.Rows[0]) }
                for ($i = 1; $i -le $cols; $i++) {
                    $name = Get-FujiCsvHeaderName -Editor $script:Ed -Column $i
                    if (-not $name) { $name = Get-FujiText 'gui.noHeader' }
                    $sample = ''
                    if ($i -le $first.Count) { $sample = Format-FujiShort ([string]$first[$i - 1]) 14 }
                    $choices += (Get-FujiText 'gui.csvColItem' $i $name $sample)
                    $nums += [string]$i
                }
                [void]$row.Controls.Add((New-FujiHelperCombo -First (Get-FujiText 'gui.csvCols') -Choices $choices -Values $nums -Target $inputControl -Mode 'set' -Width (Get-FujiScaled 420)))
            }
        }
        'imgpath' {
            $inputControl = New-FujiTextBox -Text $Value -Width ($Width - (Get-FujiScaled 150))
            $inputControl.Add_TextChanged({ Invoke-FujiUi { Update-FujiImagePreview } })
            $browse = New-FujiButton -Text (Get-FujiText 'gui.imgBrowse')
            $browse.Add_Click({ Invoke-FujiUi { Select-FujiImageFile } })
            [void]$row.Controls.Add($inputControl)
            [void]$row.Controls.Add($browse)
            [void]$Panel.Controls.Add($row)
            $row = New-FujiFlow -NoWrap
            $cap = New-FujiButton -Text (Get-FujiText 'gui.imgCapture') -Tag 'img'
            $cap.Add_Click({ Invoke-FujiUi { Start-FujiStepCapture -Mode 'img' } })
            $d.ImgW = New-FujiTextBox -Text '60' -Width (Get-FujiScaled 50)
            $d.ImgH = New-FujiTextBox -Text '30' -Width (Get-FujiScaled 50)
            [void]$row.Controls.Add($cap)
            [void]$row.Controls.Add((New-FujiLabel -Text (Get-FujiText 'gui.imgWidth')))
            [void]$row.Controls.Add($d.ImgW)
            [void]$row.Controls.Add((New-FujiLabel -Text ([string][char]0x00D7 + ' ' + (Get-FujiText 'gui.imgHeight'))))
            [void]$row.Controls.Add($d.ImgH)
            [void]$Panel.Controls.Add($row)
            $d.Status['img'] = New-FujiHintLabel -Text '' -Width $Width
            [void]$Panel.Controls.Add($d.Status['img'])
            $pic = New-Object -TypeName System.Windows.Forms.PictureBox
            $pic.SizeMode = [System.Windows.Forms.PictureBoxSizeMode]::Zoom
            $pic.Size = New-Object -TypeName System.Drawing.Size -ArgumentList (Get-FujiScaled 240), (Get-FujiScaled 90)
            $pic.BorderStyle = [System.Windows.Forms.BorderStyle]::FixedSingle
            $d.Preview = $pic
            $row = New-FujiFlow -NoWrap
            [void]$row.Controls.Add($pic)
        }
        'capture' {
            $b = New-FujiButton -Text (Get-FujiText 'gui.capture')
            $b.Add_Click({ Invoke-FujiUi { Start-FujiStepCapture -Mode 'pos' } })
            [void]$row.Controls.Add($b)
            $d.Status['pos'] = New-FujiHintLabel -Text '' -Width ($Width - (Get-FujiScaled 260))
            [void]$row.Controls.Add($d.Status['pos'])
        }
        'rectcapture' {
            $b = New-FujiButton -Text (Get-FujiText 'gui.rect')
            $b.Add_Click({ Invoke-FujiUi { Start-FujiStepCapture -Mode 'rect1' } })
            [void]$row.Controls.Add($b)
            $d.Status['rect'] = New-FujiHintLabel -Text '' -Width $Width
            [void]$Panel.Controls.Add($row)
            $row = New-FujiFlow -NoWrap
            [void]$row.Controls.Add($d.Status['rect'])
        }
        'macroselect' {
            $labels = New-Object -TypeName 'System.Collections.Generic.List[object]'
            $values = New-Object -TypeName 'System.Collections.Generic.List[object]'
            $labels.Add((Get-FujiText 'gui.chooseMacro'))
            $values.Add('')
            for ($i = 0; $i -lt $script:Ed.Data.macros.Count; $i++) {
                $m = $script:Ed.Data.macros[$i]
                $text = [string]$m.name
                if ($i -eq $script:Ed.MacroIndex) { $text += Get-FujiText 'gui.thisMacro' }
                $labels.Add($text)
                $values.Add([string]$m.id)
            }
            $inputControl = New-FujiComboBox -Items $labels.ToArray() -Values $values.ToArray() -Width ([Math]::Min($Width, (Get-FujiScaled 460)))
            Set-FujiComboValue -Combo $inputControl -Value $Value
            [void]$row.Controls.Add($inputControl)
        }
        default {
            $inputControl = New-FujiTextBox -Text $Value -Width $Width
            [void]$row.Controls.Add($inputControl)
        }
    }
    if ($null -ne $inputControl) {
        $d.Inputs[$id] = $inputControl
        if ($inputControl -is [System.Windows.Forms.TextBox] -and -not $inputControl.Multiline -and $Field.Contains('placeholder') -and $Field['placeholder']) {
            $d.Cues.Add(@($inputControl, [string]$Field['placeholder']))
        }
    }
    [void]$Panel.Controls.Add($row)
    if ($Field.Contains('placeholders') -and $Field['placeholders'] -and $null -ne $inputControl) {
        $choices = @()
        $tokens = @()
        foreach ($p in (Get-FujiPlaceholderChoice -Editor $script:Ed)) { $tokens += [string]$p[0]; $choices += ([string]$p[0] + '  ' + [string]$p[1]) }
        [void]$Panel.Controls.Add((New-FujiHelperCombo -First (Get-FujiText 'gui.placeholders') -Choices $choices -Values $tokens -Target $inputControl -Mode 'append' -Width (Get-FujiScaled 420)))
    }
    if ($type -eq 'csvcol' -and (Get-FujiCsvMaxColumn $script:Ed) -eq 0) {
        [void]$Panel.Controls.Add((New-FujiHintLabel -Text (Get-FujiText 'gui.csvColHint') -Width $Width))
    }
    if ($Field.Contains('hint') -and $Field['hint']) {
        [void]$Panel.Controls.Add((New-FujiHintLabel -Text ([string]$Field['hint']) -Width $Width))
    }
}

function Complete-FujiStepDialog {
    $d = $script:StepDlg
    $raw = @{}
    foreach ($id in $d.Inputs.Keys) { $raw[$id] = Get-FujiInputValue $d.Inputs[$id] }
    $res = Complete-FujiStepEdit -Cmd $d.Cmd -Raw $raw -Label $d.Label.Text -MacroNameOf (Get-FujiMacroNameLookup $script:Ed)
    if ($res.ContainsKey('Error')) {
        $d.Error.Text = $res.Error
        return
    }
    $d.Result = $res.Step
    $d.Form.DialogResult = [System.Windows.Forms.DialogResult]::OK
}

# ----------------------------------------------------------------- reference image
# Opening: the dialog was just opened. A network path (\\server\...) from a macro file is not read
# then: reading it connects to that server, and Windows may send the user's sign-in (NTLM) to it.
# It is shown once the user types or picks the path.
function Update-FujiImagePreview {
    param([switch]$Opening)
    $d = $script:StepDlg
    if ($null -eq $d -or $null -eq $d.Preview -or -not $d.Inputs.ContainsKey('path')) { return }
    $old = $d.Preview.Image
    $d.Preview.Image = $null
    if ($old) { $old.Dispose() }
    $full = Resolve-FujiEditorPath -Editor $script:Ed -Path $d.Inputs['path'].Text
    if ($full -eq '') { return }
    if ($Opening -and ($full.StartsWith('\\') -or $full.StartsWith('//'))) {
        $d.Status['img'].Text = Get-FujiText 'gui.imgNetworkNotShown' $full
        return
    }
    if (-not (Test-Path -LiteralPath $full -PathType Leaf)) {
        $d.Status['img'].Text = Get-FujiText 'gui.imgMissing' $full
        return
    }
    # A copy, so the file is not kept locked while the dialog is open
    $src = [System.Drawing.Image]::FromFile($full)
    try { $d.Preview.Image = New-Object -TypeName System.Drawing.Bitmap -ArgumentList $src } finally { $src.Dispose() }
    if ($d.Status['img'].Text.StartsWith([string][char]0x26A0)) { $d.Status['img'].Text = '' }
}

function Select-FujiImageFile {
    $dlg = New-Object -TypeName System.Windows.Forms.OpenFileDialog
    $dlg.Filter = Get-FujiText 'gui.imageFilter'
    $folder = Get-FujiEditorPath $script:Ed $script:FujiFileNames.Images
    if (Test-Path -LiteralPath $folder) { $dlg.InitialDirectory = $folder } else { $dlg.InitialDirectory = $script:Ed.Directory }
    if ($dlg.ShowDialog($script:StepDlg.Form) -eq [System.Windows.Forms.DialogResult]::OK) {
        $path = $dlg.FileName
        $base = $script:Ed.Directory.TrimEnd('\') + '\'
        if ($path.StartsWith($base, [System.StringComparison]::OrdinalIgnoreCase)) { $path = $path.Substring($base.Length) }
        $script:StepDlg.Inputs['path'].Text = $path
    }
    $dlg.Dispose()
}

# ----------------------------------------------------------------- mouse position / region / image capture
# Counts down with a timer (the window stays responsive), then reads the cursor position
function Start-FujiStepCapture {
    param([ValidateSet('pos', 'rect1', 'img')][string]$Mode)
    $d = $script:StepDlg
    if ($null -eq $d.Timer) {
        $d.Timer = New-Object -TypeName System.Windows.Forms.Timer
        $d.Timer.Interval = 1000
        $d.Timer.Add_Tick({ Invoke-FujiUi { Step-FujiStepCapture } })
    }
    $d.Timer.Stop()
    $d.Mode = $Mode
    $d.Remaining = 3
    if ($Mode -eq 'img') { $d.Remaining = 5 }
    Update-FujiCaptureStatus
    $d.Timer.Start()
}

function Update-FujiCaptureStatus {
    $d = $script:StepDlg
    switch ($d.Mode) {
        'pos' { $d.Status['pos'].Text = Get-FujiText 'gui.captureWait' $d.Remaining }
        'rect1' { $d.Status['rect'].Text = Get-FujiText 'gui.rectWait1' $d.Remaining }
        'rect2' { $d.Status['rect'].Text = Get-FujiText 'gui.rectWait2' $d.Remaining }
        'img' { $d.Status['img'].Text = Get-FujiText 'gui.imgWait' $d.Remaining }
    }
}

function Step-FujiStepCapture {
    $d = $script:StepDlg
    if ($null -eq $d) { return }
    $d.Remaining--
    if ($d.Remaining -gt 0) { Update-FujiCaptureStatus; return }
    $p = [System.Windows.Forms.Cursor]::Position
    switch ($d.Mode) {
        'pos' {
            $d.Timer.Stop()
            $d.Inputs['x'].Text = [string]$p.X
            $d.Inputs['y'].Text = [string]$p.Y
            $d.Status['pos'].Text = Get-FujiText 'gui.captureDone' $p.X $p.Y
        }
        'rect1' {
            $d.First = $p
            [System.Media.SystemSounds]::Beep.Play()
            $d.Mode = 'rect2'
            $d.Remaining = 3
            Update-FujiCaptureStatus
        }
        'rect2' {
            $d.Timer.Stop()
            $a = $d.First
            $x = [Math]::Min($a.X, $p.X)
            $y = [Math]::Min($a.Y, $p.Y)
            $w = [Math]::Abs($p.X - $a.X)
            $h = [Math]::Abs($p.Y - $a.Y)
            $d.Inputs['x'].Text = [string]$x
            $d.Inputs['y'].Text = [string]$y
            $d.Inputs['w'].Text = [string]$w
            $d.Inputs['h'].Text = [string]$h
            if ($d.Inputs.ContainsKey('area')) { Set-FujiComboValue -Combo $d.Inputs['area'] -Value 'RECT' }
            $d.Status['rect'].Text = Get-FujiText 'gui.rectDone' $x $y $w $h
        }
        'img' {
            $d.Timer.Stop()
            Save-FujiCursorImage -Cursor $p
        }
    }
}

function Save-FujiCursorImage {
    param([Parameter(Mandatory)][System.Drawing.Point]$Cursor)
    $d = $script:StepDlg
    $w = [Math]::Min(400, [Math]::Max(8, (Get-FujiInt -Text $d.ImgW.Text -Default 60)))
    $h = [Math]::Min(400, [Math]::Max(8, (Get-FujiInt -Text $d.ImgH.Text -Default 30)))
    $vs = [System.Windows.Forms.SystemInformation]::VirtualScreen
    $r = Get-FujiCaptureRect -X $Cursor.X -Y $Cursor.Y -Width $w -Height $h -Screen @{ X = $vs.X; Y = $vs.Y; Width = $vs.Width; Height = $vs.Height }
    $folder = Get-FujiEditorPath $script:Ed $script:FujiFileNames.Images
    if (-not (Test-Path -LiteralPath $folder -PathType Container)) { [void](New-Item -ItemType Directory -Path $folder) }
    $name = 'img_' + (Get-FujiTimeStamp) + '.png'
    $relative = $script:FujiFileNames.Images + '\' + $name
    $bmp = New-Object -TypeName System.Drawing.Bitmap -ArgumentList $r.Width, $r.Height
    try {
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try { $g.CopyFromScreen($r.X, $r.Y, 0, 0, $bmp.Size) } finally { $g.Dispose() }
        $bmp.Save((Join-Path $folder $name), [System.Drawing.Imaging.ImageFormat]::Png)
    } catch {
        $d.Status['img'].Text = Get-FujiText 'gui.imgFailed' $_.Exception.Message
        return
    } finally {
        $bmp.Dispose()
    }
    $d.Inputs['path'].Text = $relative
    $text = Get-FujiText 'gui.imgDone' $Cursor.X $Cursor.Y $r.Width $r.Height $relative
    if ($r.Width -lt $w - 1 -or $r.Height -lt $h - 1) { $text += Get-FujiText 'gui.imgEdge' }
    $d.Status['img'].Text = $text
    Write-FujiUiLog -Message (Get-FujiText 'gui.imgSaved' $relative) -Level 'ok'
}

    Import-FujiText -Path (Join-Path $here 'fujikyun_ja.json')
    $textReady = $true
    Import-FujiCommand -Path (Join-Path $here 'fujikyun_commands.json')
    $script:StartMarks.Add($script:StartWatch.Elapsed.TotalSeconds)
    Initialize-FujiUi
    $script:StartMarks.Add($script:StartWatch.Elapsed.TotalSeconds)
    $script:Ed = New-FujiEditor -Directory $here -Log { param($Message, $Level) Write-FujiUiLog -Message $Message -Level $Level }
    # CSV step labels show the loaded CSV's column names
    $script:FujiCsvHeaderNameOf = { param($Column) Get-FujiCsvHeaderName -Editor $script:Ed -Column $Column }
    Write-FujiUiLog -Message (Get-FujiText 'gui.workDir' $here)
    Initialize-FujiEditorData -Editor $script:Ed -AskRestoreTemp {
        $ask = Get-FujiText 'editor.tempAsk' $script:FujiFileNames.Macro $script:FujiFileNames.DiscardedTemp
        (Show-FujiChoice -Title (Get-FujiText 'gui.tempTitle') -Message $ask -Buttons @((Get-FujiText 'gui.yes'), (Get-FujiText 'gui.no'))) -eq 0
    }
    $script:StartMarks.Add($script:StartWatch.Elapsed.TotalSeconds)
    Show-FujiMainForm
} catch {
    $detail = $_.Exception.Message
    if ($_.InvocationInfo) { $detail += "`r`n" + $_.InvocationInfo.ScriptName + ':' + $_.InvocationInfo.ScriptLineNumber }
    $message = 'Fujikyun could not start.' + "`r`n" + $detail
    if ($textReady) { $message = Get-FujiText 'gui.startupError' $detail }
    try {
        Add-Type -AssemblyName System.Windows.Forms
        [void][System.Windows.Forms.MessageBox]::Show($message, 'Fujikyun', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Error)
    } catch {
        Write-Error -Message $message
    }
    exit 1
}
